
      // Safe JSON.stringify override to handle circular structures globally and prevent app crashes
      (function() {
        const nativeStringify = JSON.stringify;
        JSON.stringify = function (value, replacer, space) {
          const seen = new WeakSet();
          const safeReplacer = (key, val) => {
            if (typeof val === "object" && val !== null) {
              if (val instanceof HTMLElement || val instanceof Node) {
                return "[DOMElement]";
              }
              if (seen.has(val)) {
                return "[Circular]";
              }
              seen.add(val);
            }
            if (replacer) {
              return replacer(key, val);
            }
            return val;
          };
          try {
            return nativeStringify(value, safeReplacer, space);
          } catch (err) {
            console.warn("JSON.stringify error handled:", err);
            return "[SerializationError]";
          }
        };
      })();

