      // Safe, loop-protected error logging to server
      const reportedErrors = new Set();
      function logErrorToServer(errorType, message, stack) {
        const errorKey = `${errorType}:${message}`;
        if (reportedErrors.has(errorKey)) return;
        reportedErrors.add(errorKey);

        // Prevent reporting of api/state or common fetch failures to avoid loops
        if (
          message &&
          (message.includes("/api/state") ||
            message.includes("Failed to fetch") ||
            message.includes("Load failed"))
        ) {
          return;
        }

        fetch("/api/state", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            errorLog: `${errorType}: ${message} | Stack: ${stack || ""}`,
          }),
        }).catch((err) => {
          // Silent catch to prevent infinite unhandledrejection loops
          console.warn("Failed to report error to server:", err);
        });
      }

      window.onerror = function (msg, url, line, col, err) {
        const message = String(msg || "");
        const stack = err
          ? err.stack
          : `line: ${line}, col: ${col}, url: ${url}`;
        logErrorToServer("UncaughtError", message, stack);
      };

      window.addEventListener("unhandledrejection", function (event) {
        const reason = event.reason;
        const message = reason
          ? reason.message || String(reason)
          : "Unknown rejection";
        const stack = reason ? reason.stack || "" : "";
        logErrorToServer("UnhandledPromise", message, stack);
      });

