      function applyBannerScale() {
        document
          .querySelectorAll(".banner-scale-wrapper")
          .forEach((wrapper) => {
            const banner = wrapper.querySelector(".banner-scale");
            if (!banner) return;

            const customWidth = banner.getAttribute("data-desktop-width");
            const desktopWidth = customWidth ? parseInt(customWidth) : 1152;

            wrapper.style.maxWidth = desktopWidth + "px";
            banner.style.setProperty("--desktop-width", desktopWidth + "px");

            // offsetHeight gives the actual unscaled height
            const desktopHeight = banner.offsetHeight;

            // Get the wrapper's own width (which respects parent padding)
            const availableWidth = wrapper.clientWidth;
            const boundedWidth = Math.min(availableWidth, desktopWidth);
            const scale = Math.min(1, boundedWidth / desktopWidth);

            wrapper.style.setProperty("--scale", scale);
            wrapper.style.height = desktopHeight * scale + "px";
          });
      }
      window.addEventListener("resize", applyBannerScale);

