            document.addEventListener("DOMContentLoaded", () => {
              const dayEl = document.getElementById("banner-cd-day");
              const hourEl = document.getElementById("banner-cd-hour");
              const minEl = document.getElementById("banner-cd-minute");
              const secEl = document.getElementById("banner-cd-second");
              const openingTextEl = document.getElementById(
                "banner-grand-opening-text",
              );

              let countdownInterval;

              const startCountdown = () => {
                if (countdownInterval) clearInterval(countdownInterval);
                if (!dayEl || !hourEl || !minEl || !secEl || !openingTextEl)
                  return;

                const text = openingTextEl.innerText;
                const dateMatch = text.match(
                  /(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?/,
                );

                let targetDate;
                if (dateMatch) {
                  const day = parseInt(dateMatch[1]);
                  const month = parseInt(dateMatch[2]) - 1;
                  const year = dateMatch[3]
                    ? parseInt(dateMatch[3])
                    : new Date().getFullYear();

                  targetDate = new Date(year, month, day, 0, 0, 0);
                } else {
                  targetDate = new Date();
                  targetDate.setDate(targetDate.getDate() + 3);
                }

                const updateTimer = () => {
                  const now = new Date();
                  let diff = Math.floor(
                    (targetDate.getTime() - now.getTime()) / 1000,
                  );

                  if (diff < 0) diff = 0;

                  const d = Math.floor(diff / 86400);
                  const h = Math.floor((diff % 86400) / 3600);
                  const m = Math.floor((diff % 3600) / 60);
                  const s = diff % 60;

                  const dStr = d.toString().padStart(2, "0");
                  const hStr = h.toString().padStart(2, "0");
                  const mStr = m.toString().padStart(2, "0");
                  const sStr = s.toString().padStart(2, "0");

                  const dayEl = document.getElementById("banner-cd-day");
                  const hourEl = document.getElementById("banner-cd-hour");
                  const minEl = document.getElementById("banner-cd-minute");
                  const secEl = document.getElementById("banner-cd-second");

                  const userDayEl =
                    document.getElementById("user-banner-cd-day");
                  const userHourEl = document.getElementById(
                    "user-banner-cd-hour",
                  );
                  const userMinEl = document.getElementById(
                    "user-banner-cd-minute",
                  );
                  const userSecEl = document.getElementById(
                    "user-banner-cd-second",
                  );

                  if (dayEl) dayEl.innerText = dStr;
                  if (hourEl) hourEl.innerText = hStr;
                  if (minEl) minEl.innerText = mStr;
                  if (secEl) secEl.innerText = sStr;

                  if (userDayEl) userDayEl.innerText = dStr;
                  if (userHourEl) userHourEl.innerText = hStr;
                  if (userMinEl) userMinEl.innerText = mStr;
                  if (userSecEl) userSecEl.innerText = sStr;

                  if (diff <= 0) {
                    clearInterval(countdownInterval);
                  }
                };

                updateTimer();
                countdownInterval = setInterval(updateTimer, 1000);
              };

              startCountdown();

              if (openingTextEl) {
                openingTextEl.addEventListener("input", startCountdown);
              }
            });
          


        function handleDietOptChange(inputEl, groupName) {
          const wrapper = inputEl.closest('[id^="diet-grid-"]');
          if (!wrapper) return;
          const container = wrapper.firstElementChild;

          const fn = () => {
            // Ensure dynamic layout by switching to flex-wrap if grid or flex-col
            if (container.classList.contains("grid")) {
              container.classList.remove(
                "grid",
                "grid-cols-2",
                "grid-cols-1",
                "sm:grid-cols-2",
              );
              container.classList.add("flex", "flex-wrap");
            }
            if (container.classList.contains("flex-col")) {
              container.classList.remove("flex-col");
              container.classList.add("flex-wrap");
            }
            if (container.classList.contains("space-y-3")) {
              container.classList.remove("space-y-3");
              container.classList.add("gap-3");
            }

            const labels = Array.from(
              container.querySelectorAll(".diet-opt-label"),
            );
            const checked = container.querySelector(
              'input[name="' + groupName + '"]:checked',
            );
            if (!checked) return;

            const activeItem = checked.closest(".diet-opt-label");

            labels.forEach((l) => {
              l.classList.remove("diet-opt-active", "diet-opt-inactive");
            });

            activeItem.classList.add("diet-opt-active");

            const unselected = labels.filter((l) => l !== activeItem);
            unselected.forEach((l) => l.classList.add("diet-opt-inactive"));

            activeItem.style.order = 1;
            unselected.forEach((l, idx) => {
              l.style.order = idx + 2;
            });
          };

          if (document.startViewTransition) {
            document.startViewTransition(fn);
          } else {
            fn();
          }
        }
      


