      window.initScrollReveal = function() {
  if (window.revealObserver) { window.revealObserver.disconnect(); }
  const reveals = document.querySelectorAll('.reveal, .reveal-left, .reveal-right, .reveal-scale');
  reveals.forEach(r => r.classList.remove('active'));
  window.revealObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('active');
      } else {
        entry.target.classList.remove('active');
      }
    });
  }, { threshold: 0.1 });
  reveals.forEach(r => window.revealObserver.observe(r));

  // SCROLL SEQUENCE REVEAL
  window.initHeroSequence = function() {
    const sequenceSection = document.getElementById('section-scroll-sequence');
    if (!sequenceSection) return;
    const canvas = document.getElementById('sequence-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    
    canvas.width = 1280;
    canvas.height = 720;

    const useDynamic = window.heroSequenceFrames && window.heroSequenceFrames.length > 0;
    const totalFrames = useDynamic ? window.heroSequenceFrames.length : 40;
    const images = [];

    for (let i = 0; i < totalFrames; i++) {
      const img = new Image();
      if (useDynamic) {
        img.src = window.heroSequenceFrames[i];
      } else {
        const num = (i + 4).toString().padStart(3, '0');
        img.src = `./sequence/ezgif-frame-${num}.png`;
      }
      images.push(img);
    }

    images[0].onload = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(images[0], 0, 0, canvas.width, canvas.height);
    };

    if (window.heroSequenceScrollListener) {
      window.removeEventListener('scroll', window.heroSequenceScrollListener);
    }

    window.heroSequenceScrollListener = () => {
      requestAnimationFrame(() => {
        const rect = sequenceSection.getBoundingClientRect();
        let scrollFraction = 0;
        const maxScroll = rect.height - window.innerHeight;
        if (rect.top > 0) { scrollFraction = 0; }
        else if (rect.top < -maxScroll) { scrollFraction = 1; }
        else { scrollFraction = -rect.top / maxScroll; }
        
        const frameIndex = Math.min(totalFrames - 1, Math.max(0, Math.floor(scrollFraction * totalFrames)));
        if (images[frameIndex] && images[frameIndex].complete) {
          ctx.clearRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(images[frameIndex], 0, 0, canvas.width, canvas.height);
        }
      });
    };
    window.addEventListener('scroll', window.heroSequenceScrollListener);
  };
  window.initHeroSequence();
};
