        if (!cat) return "Khác";
        const c = cat.toLowerCase();
        if (c === "đạm" || c === "thịt" || c === "thủy sản") return "Đạm";
        if (c === "tinh bột") return "Tinh bột";
        if (c === "rau củ") return "Rau củ";
