      function animateValue(id, start, end, duration, isCurrencyOrOptions) {
        let isCurrency = false;
        let isFloat = !Number.isInteger(parseFloat(end));
        let numEnd = parseFloat(end);
        let formatter = null;

        if (typeof isCurrencyOrOptions === "boolean") {
          isCurrency = isCurrencyOrOptions;
        } else if (typeof isCurrencyOrOptions === "object") {
          isCurrency = isCurrencyOrOptions.isCurrency || false;
          if (isCurrencyOrOptions.isFloat !== undefined)
            isFloat = isCurrencyOrOptions.isFloat;
          if (isCurrencyOrOptions.formatter)
            formatter = isCurrencyOrOptions.formatter;
        }

        const obj = document.getElementById(id);
        if (!obj) return;

        if (obj.dataset.targetValue === String(end)) {
          return;
        }
        obj.dataset.targetValue = String(end);

        if (obj.dataset.animationId) {
          cancelAnimationFrame(parseInt(obj.dataset.animationId));
        }
        let startTimestamp = null;
        const step = (timestamp) => {
          if (!startTimestamp) startTimestamp = timestamp;
          const progress = Math.min((timestamp - startTimestamp) / duration, 1);
          const easeOutQuart = 1 - Math.pow(1 - progress, 4);

          let currentCount;
          if (isFloat && !isCurrency && !formatter) {
            currentCount = (start + easeOutQuart * (numEnd - start)).toFixed(1);
          } else {
            currentCount = Math.floor(start + easeOutQuart * (numEnd - start));
          }

          if (formatter) {
            if (obj.tagName === "INPUT") obj.value = formatter(currentCount);
            else obj.innerText = formatter(currentCount);
          } else if (isCurrency) {
            if (obj.tagName === "INPUT")
              obj.value = formatCurrency(currentCount) + "đ";
            else obj.innerText = formatCurrency(currentCount) + "đ";
          } else {
            if (obj.tagName === "INPUT") obj.value = currentCount;
            else obj.innerText = currentCount;
          }

          if (progress < 1) {
            obj.dataset.animationId = window.requestAnimationFrame(step);
          } else {
            if (formatter) {
              if (obj.tagName === "INPUT") obj.value = formatter(numEnd);
              else obj.innerText = formatter(numEnd);
            } else if (isCurrency) {
              if (obj.tagName === "INPUT")
                obj.value = formatCurrency(numEnd) + "đ";
              else obj.innerText = formatCurrency(numEnd) + "đ";
            } else {
              if (obj.tagName === "INPUT") obj.value = numEnd;
              else obj.innerText = numEnd;
            }
            delete obj.dataset.animationId;
          }
        };
        obj.dataset.animationId = window.requestAnimationFrame(step);
      }

      function formatDateTime(dateString) {
        if (!dateString) return "";
        const d = new Date(dateString);
        return (
          d.toLocaleTimeString("vi-VN", {
            hour: "2-digit",
            minute: "2-digit",
          }) +
          " - " +
          d.toLocaleDateString("vi-VN", {
            day: "2-digit",
            month: "2-digit",
            year: "numeric",
          })
        );
      }

