      function saveToLocalAccounts(customer) {
        if (!customer) return;
        let saved = JSON.parse(
          localStorage.getItem("nutriadmin_local_accounts") || "[]",
        );
        const existingIndex = saved.findIndex(
          (c) => c.phone === customer.phone,
        );
        const minimalData = {
          phone: customer.phone,
          name: customer.name,
          password: customer.password,
        };
        if (existingIndex !== -1) {
          saved[existingIndex] = minimalData;
        } else {
          saved.push(minimalData);
        }
        localStorage.setItem(
          "nutriadmin_local_accounts",
          JSON.stringify(saved),
        );
      }

