      function handleEditProfile(e) {
        e.preventDefault();
        if (!currentUser) return;

        const newName = document
          .getElementById("edit-profile-name")
          .value.trim();
        if (!newName) {
          showToast("Vui lòng nhập tên hiển thị", "error");
          return;
        }

        const preview = document.getElementById("edit-profile-avatar-preview");
        let newAvatar = currentUser.avatar;
        if (!preview.classList.contains("hidden")) {
          newAvatar = preview.src;
        }

        currentUser.name = newName;
        currentUser.avatar = newAvatar;

        // Update in main lists to reflect on admin side
        let mainUser = purchasedCustomers.find(
          (c) => c.phone === currentUser.phone,
        );
        if (mainUser) {
          mainUser.name = newName;
          mainUser.avatar = newAvatar;
        } else {
          let potUser = potentialCustomers.find(
            (c) => c.phone === currentUser.phone,
          );
          if (potUser) {
            potUser.name = newName;
            potUser.avatar = newAvatar;
          }
        }

        localStorage.setItem(
          "nutriadmin_current_user",
          JSON.stringify(currentUser),
        );
        saveToLocalAccounts(currentUser);

        // Update admin lists rendering if applicable
        if (typeof renderPurchasedCustomers === "function")
          renderPurchasedCustomers();
        if (typeof renderPotentialCustomers === "function")
          renderPotentialCustomers();

        closeEditProfileModal();
        renderCustomerProfile();
        showToast("Cập nhật hồ sơ thành công", "success");
      }

      function toggleBmiEditor() {
        const display = document.getElementById("bmi-display");
        const editor = document.getElementById("bmi-editor");
        if (editor.classList.contains("hidden")) {
          display.classList.add("hidden");
          editor.classList.remove("hidden");
          document.getElementById("input-height").value =
            currentUser.height || "";
          document.getElementById("input-weight").value =
            currentUser.weight || "";
        } else {
          editor.classList.add("hidden");
          display.classList.remove("hidden");
        }
      }

      function saveBmiInfo() {
        if (!currentUser) return;
        const h = document.getElementById("input-height").value;
        const w = document.getElementById("input-weight").value;
        if (h && w) {
          currentUser.height = parseFloat(h);
          currentUser.weight = parseFloat(w);

          let pointsAdded = 0;
          const today = new Date();
          const todayStr = today.toISOString().split("T")[0];
          let lastUpdate = currentUser.lastBmiUpdateDate;
          let shouldAddPoints = false;

          if (!lastUpdate) {
            shouldAddPoints = true;
          } else {
            const lastDate = new Date(lastUpdate);
            const diffTime = Math.abs(today - lastDate);
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            if (diffDays >= 2) {
              shouldAddPoints = true;
            }
          }

          if (shouldAddPoints) {
            currentUser.lastBmiUpdateDate = todayStr;
            currentUser.points = (currentUser.points || 0) + 5;
            currentUser.rank = getRankFromPoints(currentUser.points);
            pointsAdded = 5;
          }

          let mainUser = purchasedCustomers.find(
            (c) => c.phone === currentUser.phone,
          );
          if (mainUser) {
            mainUser.height = currentUser.height;
            mainUser.weight = currentUser.weight;
            if (shouldAddPoints) {
              mainUser.points = currentUser.points;
              mainUser.rank = currentUser.rank;
              mainUser.lastBmiUpdateDate = todayStr;
            }
          } else {
            let potUser = potentialCustomers.find(
              (c) => c.phone === currentUser.phone,
            );
            if (potUser) {
              potUser.height = currentUser.height;
              potUser.weight = currentUser.weight;
              if (shouldAddPoints) {
                potUser.points = currentUser.points;
                potUser.rank = currentUser.rank;
                potUser.lastBmiUpdateDate = todayStr;
              }
            }
          }

          localStorage.setItem(
            "nutriadmin_current_user",
            JSON.stringify(currentUser),
          );

          toggleBmiEditor();
          renderCustomerProfile();
          showToast(
            pointsAdded > 0
              ? `Cập nhật thành công! +${pointsAdded} điểm`
              : "Cập nhật chỉ số cơ thể OK!",
            "success",
          );
        } else {
          showToast("Vui lòng nhập chiều cao và cân nặng", "error");
        }
      }

