      function updateMascotScheduleSlot(index, field, value) {
        if (field === "start" || field === "end") {
          tempMascotSchedule[index][field] = parseTimeFromInput(value);
        } else {
          tempMascotSchedule[index][field] = value;
        }

        // Update label
        const startStr = formatTimeForInput(tempMascotSchedule[index].start);
        const endStr = formatTimeForInput(tempMascotSchedule[index].end);
        tempMascotSchedule[index].label = `${startStr} - ${endStr}`;
      }

      function addMascotScheduleSlot() {
        const lastSlot =
          tempMascotSchedule.length > 0
            ? tempMascotSchedule[tempMascotSchedule.length - 1]
            : { end: 0 };
        const start = lastSlot.end;
        const end = (start + 1) % 24;

        tempMascotSchedule.push({
          start: start,
          end: end,
          id: "vui_ve",
          label: `${formatTimeForInput(start)} - ${formatTimeForInput(end)}`,
        });

        renderMascotScheduleList();
      }

      function removeMascotScheduleSlot(index) {
        tempMascotSchedule.splice(index, 1);
        renderMascotScheduleList();
      }

