      window.getStreakDays = getStreakDays;

      function isSameCalendarWeek(timestamp1, timestamp2) {
        if (!timestamp1 || !timestamp2) return false;
        const d1 = new Date(timestamp1);
        const d2 = new Date(timestamp2);

        // Find Monday of the week for d1
        const day1 = d1.getDay();
        const diff1 = d1.getDate() - day1 + (day1 === 0 ? -6 : 1);
        const mon1 = new Date(d1.setDate(diff1));
        mon1.setHours(0, 0, 0, 0);

        // Find Monday of the week for d2
        const day2 = d2.getDay();
        const diff2 = d2.getDate() - day2 + (day2 === 0 ? -6 : 1);
        const mon2 = new Date(d2.setDate(diff2));
        mon2.setHours(0, 0, 0, 0);

        return mon1.getTime() === mon2.getTime();
      }

      function getKcalForOrderItem(item) {
        if (!item) return 0;
        if (typeof item.kcal === "number" && item.kcal > 0) return item.kcal;
        if (typeof item.calories === "number" && item.calories > 0)
          return item.calories;
        // Search in dishes
        if (typeof dishes !== "undefined" && Array.isArray(dishes)) {
          const dish = dishes.find((d) => d.id == item.dishId);
          if (dish) {
            const sizeKey = item.sizeKey || "balance";
            if (
              dish.sizes &&
              dish.sizes[sizeKey] &&
              typeof dish.sizes[sizeKey].kcal === "number"
            ) {
              return dish.sizes[sizeKey].kcal;
            }
            if (dish.sizes) {
              for (let sk in dish.sizes) {
                if (dish.sizes[sk] && typeof dish.sizes[sk].kcal === "number") {
                  return dish.sizes[sk].kcal;
                }
              }
            }
          }
        }
        // Fallbacks
        const sk = item.sizeKey || "";
        if (
          sk === "power" ||
          (item.sizeLabel && item.sizeLabel.includes("Power"))
        )
          return 800;
        if (
          sk === "lean" ||
          (item.sizeLabel && item.sizeLabel.includes("Lean"))
        )
          return 450;
        return 600; // balance
      }

      function getMacrosForOrderItem(item) {
        let macros = { protein: 0, carbs: 0, fat: 0 };
        if (!item) return macros;
        if (typeof dishes !== "undefined" && Array.isArray(dishes)) {
          const dish = dishes.find((d) => d.id == item.dishId);
          if (dish) {
            const sizeKey = item.sizeKey || "balance";
            if (dish.sizes && dish.sizes[sizeKey]) {
              const sz = dish.sizes[sizeKey];
              macros.protein = (sz.protein || 0) * (item.qty || 1);
              macros.carbs = (sz.carbs || 0) * (item.qty || 1);
              macros.fat = (sz.fat || 0) * (item.qty || 1);
              return macros;
            }
            if (dish.sizes) {
              for (let sk in dish.sizes) {
                if (dish.sizes[sk]) {
                  const sz = dish.sizes[sk];
                  macros.protein = (sz.protein || 0) * (item.qty || 1);
                  macros.carbs = (sz.carbs || 0) * (item.qty || 1);
                  macros.fat = (sz.fat || 0) * (item.qty || 1);
                  return macros;
                }
              }
            }
          }
        }
        return macros;
      }

      function getOrderKcal(order) {
        if (!order || !order.items || !Array.isArray(order.items)) return 0;
        let sum = 0;
        order.items.forEach((item) => {
          sum += getKcalForOrderItem(item) * (item.qty || 1);
        });
        return sum;
      }

      function animateCircularProgress(circleId, pctId, targetPct) {
        const circle = document.getElementById(circleId);
        const pctText = document.getElementById(pctId);
        if (!circle || !pctText) return;

        circle.style.transition = "none";
        circle.style.strokeDashoffset = "150.7";
        pctText.textContent = "0%";

        circle.getBoundingClientRect(); // Force reflow

        circle.style.transition =
          "stroke-dashoffset 1.2s cubic-bezier(0.34, 1.56, 0.64, 1)";
        const targetOffset = 150.7 - (150.7 * Math.min(targetPct, 100)) / 100;
        circle.style.strokeDashoffset = targetOffset;

        let currentPct = 0;
        const startTime = performance.now();
        const duration = 1200;

        function animateText(now) {
          const elapsed = now - startTime;
          const progress = Math.min(elapsed / duration, 1);
          const easeProgress = progress * (2 - progress); // easeOutQuad
          currentPct = Math.round(targetPct * easeProgress);
          pctText.textContent = currentPct + "%";

          if (progress < 1) {
            requestAnimationFrame(animateText);
          } else {
            pctText.textContent = targetPct + "%";
          }
        }
        requestAnimationFrame(animateText);
      }

      function updateNutritionDashboard(isFirstLoad = false) {
        if (!currentUser) return;

        const daysSeq = [
          "bar-t2",
          "bar-t3",
          "bar-t4",
          "bar-t5",
          "bar-t6",
          "bar-t7",
          "bar-cn",
        ];
        const dayIds = [
          "bar-cn",
          "bar-t2",
          "bar-t3",
          "bar-t4",
          "bar-t5",
          "bar-t6",
          "bar-t7",
        ];
        const todayIndex = new Date().getDay(); // 0 is CN, 1 is T2, etc.
        const todayIndexInSeq = todayIndex === 0 ? 6 : todayIndex - 1;
        const todayId = dayIds[todayIndex];

        const defaultDemoBases = {
          "bar-t2": 700,
          "bar-t3": 900,
          "bar-t4": 1200,
          "bar-t5": 1200,
          "bar-t6": 1000,
          "bar-t7": 0,
          "bar-cn": 0,
        };

        const now = Date.now();

        // 1. Calculate and set data-base and data-extra for each bar
        daysSeq.forEach((dayId, i) => {
          const bar = document.getElementById(dayId);
          if (!bar) return;

          let base = 0;
          if (i === todayIndexInSeq) {
            // Today starts at 0 by default
            base = 0;
          } else if (i > todayIndexInSeq) {
            // Future days are 0 by default
            base = 0;
          } else {
            // Past days keep their default demo base
            base = 0;
          }

          // Add completed package orders of current week for this day of the week
          if (typeof orders !== "undefined" && Array.isArray(orders)) {
            const userOrders = orders.filter(
              (o) =>
                o.phone === currentUser.phone &&
                o.isPackageOrder &&
                o.status === "completed" &&
                isSameCalendarWeek(o.timestamp, now),
            );

            userOrders.forEach((o) => {
              const oDayIndex = new Date(o.timestamp).getDay();
              const oDayId = dayIds[oDayIndex];
              if (oDayId === dayId) {
                base += getOrderKcal(o);
              }
            });
          }

          // Set base
          bar.setAttribute("data-base", base);

          // Calculate extra calories from extra foods logged
          let extra = 0;
          if (window.extraFoodsData && window.extraFoodsData[dayId]) {
            window.extraFoodsData[dayId].forEach((item) => {
              extra += item.kcal || 0;
            });
          }
          bar.setAttribute("data-extra", extra);
        });

        // 2. Update heights and tooltips for all bars based on targetCal
        const targetCal =
          (typeof currentUser !== "undefined" &&
            currentUser &&
            currentUser.targetCal) ||
          (window.lastAnalysisResult && window.lastAnalysisResult.targetCal) ||
          1500;
        const maxScale = targetCal / 0.75; // 75% is the target line

        daysSeq.forEach((dayId, i) => {
          const bar = document.getElementById(dayId);
          if (!bar) return;

          const base = parseInt(bar.getAttribute("data-base")) || 0;
          const extra = parseInt(bar.getAttribute("data-extra")) || 0;
          const total = base + extra;

          let hPercent = Math.min((total / maxScale) * 100, 100);
          if (base === 0 && hPercent < 15 && hPercent > 0) {
            hPercent = Math.max(hPercent, 30);
          } else if (base === 0 && total === 0) {
            hPercent = 0; // Empty bar if 0 calo
          }

          if (isFirstLoad) {
            bar.style.transition = "none";
            bar.style.height = "0%";
            bar.getBoundingClientRect(); // force reflow
            bar.style.transition =
              "height 0.8s cubic-bezier(0.34, 1.56, 0.64, 1)";
            setTimeout(() => {
              bar.style.height = hPercent + "%";
            }, i * 120);
          } else {
            bar.style.transition = "height 0.5s ease-in-out";
            bar.style.height = hPercent + "%";
          }

          // Update tooltip
          const tooltip = bar.querySelector(".bar-tooltip");
          if (tooltip) {
            if (base === 0 && total > 0) {
              tooltip.innerHTML = `${total} <span class="text-[8px] font-normal text-slate-400 block -mt-1">(tự do)</span>`;
              tooltip.classList.remove("text-amber-600");
              tooltip.classList.add("text-slate-500");
            } else if (total === 0) {
              tooltip.textContent = "0 kcal";
            } else {
              tooltip.textContent = total;
            }
          }

          // Update inner bar visual segments (base vs extra)
          const extraDiv = bar.querySelector(".bar-extra");
          const baseDiv = bar.querySelector(".bar-base");

          if (extraDiv && baseDiv) {
            if (extra > 0) {
              extraDiv.classList.remove("hidden");
              const actualTotalForRatio = total || 1;
              const extraPercent = (extra / actualTotalForRatio) * 100;
              const basePercent = (base / actualTotalForRatio) * 100;

              if (base === 0) {
                extraDiv.style.height = "100%";
                baseDiv.classList.add("hidden");
              } else {
                baseDiv.classList.remove("hidden");
                baseDiv.classList.remove("rounded-t");
                extraDiv.style.height = extraPercent + "%";
                baseDiv.style.height = basePercent + "%";
              }
            } else {
              extraDiv.classList.add("hidden");
              baseDiv.classList.remove("hidden");
              baseDiv.classList.add("rounded-t");
              baseDiv.style.height = "100%";
              if (total === 0) {
                baseDiv.classList.add("hidden"); // hide completely if 0
              }
            }
          }
        });

        // 3. Update "Dinh dưỡng hôm nay" (Today's nutrition) widgets
        const todayBar = document.getElementById(todayId);
        if (todayBar) {
          const todayBase = parseInt(todayBar.getAttribute("data-base")) || 0;
          const todayExtra = parseInt(todayBar.getAttribute("data-extra")) || 0;
          const todayTotal = todayBase + todayExtra;

          // Update Calo displays
          const caloDisplay = document.getElementById("dash-calo");
          if (caloDisplay) {
            caloDisplay.innerHTML = `${todayTotal}<span class="text-[9px] text-slate-400 font-normal" id="dash-calo-target">/${targetCal} kcal</span>`;
          }

          const pctCal = Math.round((todayTotal / targetCal) * 100);
          animateCircularProgress("dash-calo-circle", "dash-calo-pct", pctCal);

          // 4. Update macronutrients (Protein, Carbs, Fat) dynamically
          const targetPro =
            (typeof currentUser !== "undefined" &&
              currentUser &&
              currentUser.targetProtein) ||
            (window.lastAnalysisResult && window.lastAnalysisResult.protein) ||
            120;
          const targetCarb =
            (typeof currentUser !== "undefined" &&
              currentUser &&
              currentUser.targetCarbs) ||
            (window.lastAnalysisResult && window.lastAnalysisResult.carbs) ||
            150;
          const targetFat =
            (typeof currentUser !== "undefined" &&
              currentUser &&
              currentUser.targetFat) ||
            (window.lastAnalysisResult && window.lastAnalysisResult.fat) ||
            50;

          // Sum today's completed package orders macros
          let todayPro = 0;
          let todayCarb = 0;
          let todayFat = 0;

          if (typeof orders !== "undefined" && Array.isArray(orders)) {
            const todayOrders = orders.filter(
              (o) =>
                o.phone === currentUser.phone &&
                o.isPackageOrder &&
                o.status === "completed" &&
                isSameCalendarWeek(o.timestamp, now) &&
                dayIds[new Date(o.timestamp).getDay()] === todayId,
            );

            todayOrders.forEach((o) => {
              if (o.items) {
                o.items.forEach((item) => {
                  const m = getMacrosForOrderItem(item);
                  todayPro += m.protein;
                  todayCarb += m.carbs;
                  todayFat += m.fat;
                });
              }
            });
          }

          // Cập nhật Protein
          const proDisplay = document.getElementById("dash-pro");
          if (proDisplay) {
            proDisplay.innerHTML = `${todayPro}<span class="text-[9px] text-slate-400 font-normal" id="dash-pro-target">/${targetPro}g</span>`;
          }
          const pctPro = Math.round((todayPro / targetPro) * 100);
          animateCircularProgress("dash-pro-circle", "dash-pro-pct", pctPro);

          // Cập nhật Carbs
          const carbDisplay = document.getElementById("dash-carb");
          if (carbDisplay) {
            carbDisplay.innerHTML = `${todayCarb}<span class="text-[9px] text-slate-400 font-normal" id="dash-carb-target">/${targetCarb}g</span>`;
          }
          const pctCarb = Math.round((todayCarb / targetCarb) * 100);
          animateCircularProgress("dash-carb-circle", "dash-carb-pct", pctCarb);

          // Cập nhật Fat
          const fatDisplay = document.getElementById("dash-fat");
          if (fatDisplay) {
            fatDisplay.innerHTML = `${todayFat}<span class="text-[9px] text-slate-400 font-normal" id="dash-fat-target">/${targetFat}g</span>`;
          }
          const pctFat = Math.round((todayFat / targetFat) * 100);
          animateCircularProgress("dash-fat-circle", "dash-fat-pct", pctFat);

          // Calorie Warning Check
          if (todayTotal > targetCal) {
            const todayStr = new Date().toISOString().split("T")[0];
            const warnedKey = `calorie_warned_${currentUser.phone}_${todayStr}`;
            if (!localStorage.getItem(warnedKey)) {
              setTimeout(() => {
                showCalorieWarningModal(todayTotal, targetCal);
                localStorage.setItem(warnedKey, "true");
              }, 1500); // Wait a bit after load to show popup
            }
          }
        }
      }

      function showCalorieWarningModal(current, target) {
        const modal = document.getElementById("calorie-warning-modal");
        const content = document.getElementById(
          "calorie-warning-modal-content",
        );
        const targetEl = document.getElementById("calorie-warning-target");
        const img = document.getElementById("calorie-warning-mascot-img");

        if (!modal || !content) return;

        if (targetEl) targetEl.innerText = `${target} kcal`;
        if (img) img.src = "/mascots/ngac_nhien.png";

        modal.classList.remove("hidden");
        modal.classList.add("flex");

        // Force reflow
        modal.offsetHeight;

        modal.classList.remove("opacity-0");
        content.classList.remove("scale-95");
      }

      function closeCalorieWarningModal() {
        const modal = document.getElementById("calorie-warning-modal");
        const content = document.getElementById(
          "calorie-warning-modal-content",
        );

        if (!modal || !content) return;

        modal.classList.add("opacity-0");
        content.classList.add("scale-95");

        setTimeout(() => {
          modal.classList.add("hidden");
          modal.classList.remove("flex");
        }, 300);
      }

      window.closeCalorieWarningModal = closeCalorieWarningModal;

      function updateShareRewardBadge() {
        if (!currentUser) return;

        // Clean and filter history for current week
        const now = Date.now();
        currentUser.shareHistory = (currentUser.shareHistory || []).filter(
          (ts) => isSameCalendarWeek(ts, now),
        );

        const count = currentUser.shareHistory.length;
        const textEl = document.getElementById("share-reward-text");
        const badgeEl = document.getElementById("share-reward-badge");

        if (textEl && badgeEl) {
          if (count >= 2) {
            badgeEl.className =
              "bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl p-3 flex items-start gap-2.5 transition-all";
            textEl.innerHTML = `Bạn đã nhận đủ <span class="font-bold text-emerald-600 dark:text-emerald-400">2/2 lần</span> điểm thưởng tuần này. Bạn vẫn có thể tiếp tục chia sẻ để khoe thành tích!`;
          } else {
            badgeEl.className =
              "bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-900/50 rounded-2xl p-3 flex items-start gap-2.5 transition-all";
            const remaining = 2 - count;
            textEl.innerHTML = `Nhận ngay <span class="font-bold text-orange-600 dark:text-orange-400">+20 điểm xếp hạng</span> khi chia sẻ thành tích ăn uống lành mạnh lên mạng xã hội! Bạn đã nhận <span class="font-bold text-emerald-600 dark:text-emerald-400">${count}/2 lần</span> tuần này (còn ${remaining} lần).`;
          }
        }
      }

      function getFallbackWrapupAdvice(
        goal,
        weight,
        targetWeight,
        avgActualDailyCal,
        targetCal,
        tdee,
        predictedWeight,
        percentage,
      ) {
        let encouragement = "";
        let advice = "";

        if (goal === "loss") {
          if (avgActualDailyCal < tdee) {
            encouragement =
              "Tuyệt vời! Bạn đang duy trì thâm hụt calo rất tốt để hướng tới mục tiêu giảm cân.";
            advice = `Với mức tiêu thụ trung bình là ${avgActualDailyCal} kcal/ngày (thấp hơn TDEE là ${tdee} kcal), bạn đang đi đúng hướng. Hãy tiếp tục duy trì thực đơn lành mạnh từ Nuri Kitchen để đạt cân nặng dự kiến là ${predictedWeight.toFixed(1)}kg nhé.`;
          } else {
            encouragement =
              "Cố lên bạn nhé! Hành trình vạn dặm luôn bắt đầu từ những bước đi đầu tiên.";
            advice = `Lượng calo thực tế (${avgActualDailyCal} kcal/ngày) hiện đang cao hơn mức tiêu thụ TDEE (${tdee} kcal/ngày). Để đạt mục tiêu giảm cân hiệu quả, bạn nên tập trung sử dụng đúng các món ăn trong thực đơn Nuri Kitchen và hạn chế ăn thêm món phụ ngoài kế hoạch.`;
          }
        } else if (goal === "gain") {
          if (avgActualDailyCal > tdee) {
            encouragement =
              "Quá tốt! Bạn đang nạp thặng dư calo ổn định để hỗ trợ tăng cân lành mạnh.";
            advice = `Lượng calo trung bình ${avgActualDailyCal} kcal/ngày cao hơn TDEE (${tdee} kcal) giúp cơ thể có đủ dưỡng chất để tăng cân an toàn. Hãy giữ vững phong độ ăn uống khoa học cùng Nuri Kitchen.`;
          } else {
            encouragement =
              "Hãy cố gắng ăn uống đầy đủ hơn nhé! Cơ thể bạn đang cần thêm năng lượng.";
            advice = `Lượng calo thực tế (${avgActualDailyCal} kcal/ngày) hiện đang thấp hơn hoặc bằng TDEE (${tdee} kcal/ngày). Để tăng cân thành công, bạn cần tăng lượng calo nạp vào qua các bữa ăn bổ dưỡng và dùng thêm các món ăn nhẹ giàu protein từ thực đơn của Nuri Kitchen.`;
          }
        } else if (goal === "recomp") {
          encouragement =
            "Rất ấn tượng! Bạn đang duy trì lối sống cực kỳ lành mạnh để tối ưu cơ bắp và giảm mỡ thừa.";
          advice = `Mức tiêu thụ trung bình ${avgActualDailyCal} kcal/ngày sát với mục tiêu (${targetCal} kcal/ngày) giúp quá trình tái cấu trúc cơ thể diễn ra hiệu quả nhất. Hãy tiếp tục tin tưởng thực đơn cân đối protein của Nuri Kitchen!`;
        } else {
          encouragement =
            "Tuyệt vời! Bạn đang kiểm soát năng lượng nạp vào rất tốt để duy trì vóc dáng ổn định.";
          advice = `Thực đơn cân bằng từ Nuri Kitchen cùng lối sống năng động giúp bạn duy trì năng lượng lý tưởng ở mức ${avgActualDailyCal} kcal/ngày. Đây là chìa khóa để giữ vững vóc dáng săn chắc và nâng cao sức đề kháng toàn diện.`;
        }

        return { encouragement, advice };
      }

      async function openWrapupModal() {
        if (!currentUser) {
          showToast("Vui lòng đăng nhập để xem báo cáo!", "warning");
          return;
        }

        const modal = document.getElementById("wrapup-modal");
        const content = document.getElementById("wrapup-modal-content");
        if (!modal || !content) return;

        // Start calculating and API request immediately
        const analysisPromise = (async () => {
          const weight =
            currentUser.weight ||
            (window.lastAnalysisResult && window.lastAnalysisResult.weight) ||
            60;
          const height =
            currentUser.height ||
            (window.lastAnalysisResult && window.lastAnalysisResult.height) ||
            165;
          const targetWeight =
            currentUser.targetWeight ||
            (window.lastAnalysisResult &&
              window.lastAnalysisResult.targetWeight) ||
            (currentUser.goal === "loss" ? weight - 3 : weight + 3);
          const goal =
            currentUser.goal ||
            (window.lastAnalysisResult && window.lastAnalysisResult.goal) ||
            "loss";
          const duration =
            currentUser.duration ||
            (window.lastAnalysisResult && window.lastAnalysisResult.duration) ||
            4;
          const targetCal =
            currentUser.targetCal ||
            (window.lastAnalysisResult &&
              window.lastAnalysisResult.targetCal) ||
            1500;
          const tdee =
            currentUser.tdee ||
            (window.lastAnalysisResult && window.lastAnalysisResult.tdee) ||
            2000;
          const age = currentUser.age || 25;
          const gender = currentUser.gender || "female";

          let weeklyMenuCal = 0;
          let menuDaysCount = 0;
          if (currentUser.weeklyMenu) {
            const days = [
              "monday",
              "tuesday",
              "wednesday",
              "thursday",
              "friday",
              "saturday",
              "sunday",
            ];
            days.forEach((day) => {
              const m = currentUser.weeklyMenu[day];
              if (m) {
                if (m.meal1?.dishId) {
                  weeklyMenuCal += getKcalForOrderItem(m.meal1);
                  menuDaysCount++;
                }
                if (m.meal2?.dishId) {
                  weeklyMenuCal += getKcalForOrderItem(m.meal2);
                }
              }
            });
          }
          const avgPlannedDailyCal =
            menuDaysCount > 0 ? Math.round(weeklyMenuCal / 7) : 1100;

          const now = Date.now();
          const pkgStartDate = currentUser.startDate
            ? new Date(currentUser.startDate)
            : null;
          let earliestOrderTimestamp = null;
          if (typeof orders !== "undefined" && Array.isArray(orders)) {
            const userPackageOrders = orders.filter(
              (o) =>
                o.phone === currentUser.phone &&
                o.isPackageOrder &&
                o.status === "completed",
            );
            if (userPackageOrders.length > 0) {
              const timestamps = userPackageOrders.map((o) =>
                new Date(o.timestamp).getTime(),
              );
              earliestOrderTimestamp = new Date(Math.min(...timestamps));
            }
          }
          const startDate =
            pkgStartDate ||
            earliestOrderTimestamp ||
            new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

          const defaultDemoBases = {
            "bar-t2": 700,
            "bar-t3": 900,
            "bar-t4": 1200,
            "bar-t5": 1200,
            "bar-t6": 1000,
            "bar-t7": 0,
            "bar-cn": 0,
          };
          const dayIdsByGetDay = [
            "bar-cn",
            "bar-t2",
            "bar-t3",
            "bar-t4",
            "bar-t5",
            "bar-t6",
            "bar-t7",
          ];

          let totalKcalFromStart = 0;
          let totalPassedDays = 0;

          const tempDate = new Date(
            startDate.getFullYear(),
            startDate.getMonth(),
            startDate.getDate(),
          );
          const todayDate = new Date();
          todayDate.setHours(23, 59, 59, 999); // ensure today is fully covered

          while (tempDate.getTime() <= todayDate.getTime()) {
            totalPassedDays++;
            const dayOfWeekIndex = tempDate.getDay();
            const dayId = dayIdsByGetDay[dayOfWeekIndex];

            let dayBase = 0;
            let orderOnThisDay = null;
            if (typeof orders !== "undefined" && Array.isArray(orders)) {
              orderOnThisDay = orders.find(
                (o) =>
                  o.phone === currentUser.phone &&
                  o.isPackageOrder &&
                  o.status === "completed" &&
                  new Date(o.timestamp).toDateString() ===
                    tempDate.toDateString(),
              );
            }

            if (orderOnThisDay) {
              dayBase = getOrderKcal(orderOnThisDay);
            } else {
              dayBase = 0;
            }

            totalKcalFromStart += dayBase;

            if (isSameCalendarWeek(tempDate.getTime(), now)) {
              if (window.extraFoodsData && window.extraFoodsData[dayId]) {
                window.extraFoodsData[dayId].forEach((item) => {
                  totalKcalFromStart += item.kcal || 0;
                });
              }
            }

            tempDate.setDate(tempDate.getDate() + 1);
          }

          if (totalPassedDays === 0) totalPassedDays = 1;
          const avgActualDailyCal = Math.round(
            totalKcalFromStart / totalPassedDays,
          );

          const totalDaysOfPackage = duration * 7;
          const remainingDays = Math.max(
            0,
            totalDaysOfPackage - totalPassedDays,
          );
          const totalProjectedKcal =
            totalKcalFromStart + remainingDays * targetCal;
          const totalExpendedOverDuration = totalDaysOfPackage * tdee;

          const netCalDiff = totalProjectedKcal - totalExpendedOverDuration;
          const netWeightChange = netCalDiff / 7700; // negative means loss, positive means gain

          let predictedWeight = weight + netWeightChange;
          if (predictedWeight < 35) {
            predictedWeight = 35;
          }

          let percentage = 0;
          let weightChangeStr = "";

          if (goal === "loss") {
            const achievedLoss = -netWeightChange; // positive if lost weight
            const targetLoss = weight - targetWeight;
            if (targetLoss > 0) {
              percentage = Math.min(
                100,
                Math.max(0, Math.round((achievedLoss / targetLoss) * 100)),
              );
            } else {
              percentage = achievedLoss > 0 ? 100 : 0;
            }
            weightChangeStr =
              netWeightChange <= 0
                ? `giảm được ${Math.abs(netWeightChange).toFixed(1)}kg`
                : `tăng ${netWeightChange.toFixed(1)}kg (dư calo)`;
          } else if (goal === "gain") {
            const achievedGain = netWeightChange; // positive if gained weight
            const targetGain = targetWeight - weight;
            if (targetGain > 0) {
              percentage = Math.min(
                100,
                Math.max(0, Math.round((achievedGain / targetGain) * 100)),
              );
            } else {
              percentage = achievedGain > 0 ? 100 : 0;
            }
            weightChangeStr =
              netWeightChange >= 0
                ? `tăng được ${netWeightChange.toFixed(1)}kg`
                : `giảm ${Math.abs(netWeightChange).toFixed(1)}kg (thâm hụt)`;
          } else {
            percentage =
              100 -
              Math.min(
                100,
                Math.round(
                  (Math.abs(avgActualDailyCal - targetCal) / targetCal) * 100,
                ),
              );
            weightChangeStr =
              Math.abs(netWeightChange) < 0.5
                ? "giữ cân ổn định"
                : netWeightChange >= 0
                  ? `tăng nhẹ ${netWeightChange.toFixed(1)}kg`
                  : `giảm nhẹ ${Math.abs(netWeightChange).toFixed(1)}kg`;
          }

          let encouragement = "";
          let advice = "";

          const prompt = `Bạn là chuyên gia dinh dưỡng Nuri, đại diện cho Nuri Kitchen. Hãy viết báo cáo tổng kết hành trình ăn uống lành mạnh bằng Tiếng Việt cho khách hàng ${currentUser.name}:
- Tuổi: ${age}, Giới tính: ${gender === "male" ? "Nam" : "Nữ"}, Chiều cao: ${height}cm.
- Cân nặng hiện tại: ${weight}kg, Cân nặng mục tiêu: ${targetWeight}kg, Mục tiêu: ${goal === "loss" ? "Giảm cân" : goal === "gain" ? "Tăng cân" : goal === "recomp" ? "Tăng cơ giảm mỡ" : "Duy trì vóc dáng"}.
- Kcal tiêu thụ thực tế trung bình hàng ngày: ${avgActualDailyCal} kcal (TDEE: ${tdee} kcal, Kcal mục tiêu: ${targetCal} kcal, Kcal thực đơn gói trung bình: ${avgPlannedDailyCal} kcal).
- Kết quả dự đoán: Cân nặng dự kiến sau ${duration} tuần là ${predictedWeight.toFixed(1)}kg (${weightChangeStr}), đạt ${percentage}% mục tiêu vóc dáng.

Hãy tạo ra:
1. Một câu khen ngợi hoặc động viên chân thành, ấm áp (1-2 câu).
2. Lời tư vấn dinh dưỡng cá nhân sâu sắc, dễ hiểu (2-3 câu). Đánh giá trực tiếp mối tương quan giữa lượng kcal thực tế tiêu thụ (${avgActualDailyCal} kcal) với kcal mục tiêu (${targetCal} kcal), tầm quan trọng của thực đơn gói Nuri Kitchen đang cung cấp và đưa ra giải pháp cụ thể giúp khách hàng hoàn thành mục tiêu.

Yêu cầu trả về đúng định dạng JSON thô (không bọc trong ký hiệu markdown \`\`\`json) với cấu trúc:
{
  "encouragement": "câu khen ngợi/động viên",
  "advice": "lời tư vấn dinh dưỡng cá nhân"
}`;

          try {
            const aiText = await fetchGeminiAPI(prompt, true);
            let cleaned = aiText ? aiText.trim() : "";
            if (cleaned.startsWith("```json")) {
              cleaned = cleaned.substring(7);
            }
            if (cleaned.endsWith("```")) {
              cleaned = cleaned.substring(0, cleaned.length - 3);
            }
            const parsed = JSON.parse(cleaned.trim());
            encouragement = parsed.encouragement || "";
            advice = parsed.advice || "";
          } catch (err) {
            const fallback = getFallbackWrapupAdvice(
              goal,
              weight,
              targetWeight,
              avgActualDailyCal,
              targetCal,
              tdee,
              predictedWeight,
              percentage,
            );
            encouragement = fallback.encouragement;
            advice = fallback.advice;
          }

          if (!encouragement || !advice) {
            const fallback = getFallbackWrapupAdvice(
              goal,
              weight,
              targetWeight,
              avgActualDailyCal,
              targetCal,
              tdee,
              predictedWeight,
              percentage,
            );
            encouragement = encouragement || fallback.encouragement;
            advice = advice || fallback.advice;
          }

          let goalText = "Duy trì vóc dáng";
          let goalIcon =
            '<i class="fa-solid fa-heart-pulse text-emerald-400"></i>';
          if (goal === "loss") {
            goalText = "Giảm cân";
            goalIcon = '<i class="fa-solid fa-weight-scale text-rose-400"></i>';
          } else if (goal === "gain") {
            goalText = "Tăng cân";
            goalIcon =
              '<i class="fa-solid fa-circle-arrow-up text-blue-400"></i>';
          } else if (goal === "recomp") {
            goalText = "Tăng cơ giảm mỡ";
            goalIcon = '<i class="fa-solid fa-dumbbell text-amber-400"></i>';
          }

          return {
            weight,
            predictedWeight,
            weightChangeStr,
            percentage,
            encouragement,
            advice,
            goalText,
            goalIcon,
            tdee,
            targetCal,
            avgPlannedDailyCal,
            avgActualDailyCal,
            duration,
          };
        })();

        // Call the mascot analyzing overlay passing the promise
        showAnalyzingPopup(
          async () => {
            try {
              const result = await analysisPromise;

              const contentBody = document.getElementById(
                "wrapup-modal-body-content",
              );
              if (contentBody) {
                contentBody.innerHTML = `
                <div class="text-center mb-6">
                  <div class="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-tr from-amber-400 to-yellow-500 rounded-full shadow-lg mb-3 ring-4 ring-amber-500/30 animate-bounce">
                    <i class="fa-solid fa-medal text-3xl text-emerald-950"></i>
                  </div>
                  <h2 class="text-2xl font-extrabold text-white leading-tight">Báo Cáo Tổng Kết</h2>
                  <p class="text-emerald-300 text-xs mt-1">Phân tích chuyên sâu từ Nuri Kitchen</p>
                </div>

                <!-- Profile Info Cards -->
                <div class="grid grid-cols-2 gap-2 mb-4">
                  <div class="bg-white/5 backdrop-blur border border-white/10 rounded-xl p-2.5">
                    <span class="text-[10px] text-emerald-300 block uppercase font-bold tracking-wider mb-0.5">Mục tiêu</span>
                    <span class="text-xs font-bold flex items-center gap-1.5">${result.goalIcon} ${result.goalText}</span>
                  </div>
                  <div class="bg-white/5 backdrop-blur border border-white/10 rounded-xl p-2.5">
                    <span class="text-[10px] text-emerald-300 block uppercase font-bold tracking-wider mb-0.5">Cân nặng gốc</span>
                    <span class="text-xs font-bold"><i class="fa-solid fa-user-tag text-emerald-400 mr-1"></i> ${result.weight} kg</span>
                  </div>
                </div>

                <!-- Metrics Comparison Table -->
                <div class="bg-white/5 border border-white/10 rounded-2xl p-4 mb-4">
                  <h3 class="text-xs font-bold text-emerald-200 uppercase tracking-wider mb-3 flex items-center gap-2">
                    <i class="fa-solid fa-chart-bar"></i> Chỉ số Calorie hàng ngày
                  </h3>
                  <div class="space-y-2.5 text-xs">
                    <div class="flex justify-between items-center">
                      <span class="text-slate-300 flex items-center gap-1.5">
                        <span class="w-2 h-2 rounded-full bg-blue-400"></span> Tiêu hao cơ thể (TDEE)
                      </span>
                      <span class="font-bold text-slate-100">${result.tdee} kcal</span>
                    </div>
                    <div class="flex justify-between items-center">
                      <span class="text-slate-300 flex items-center gap-1.5">
                        <span class="w-2 h-2 rounded-full bg-emerald-400"></span> Calo mục tiêu phân tích
                      </span>
                      <span class="font-bold text-emerald-300">${result.targetCal} kcal</span>
                    </div>
                    <div class="flex justify-between items-center border-t border-white/5 pt-2">
                      <span class="text-slate-300 flex items-center gap-1.5">
                        <span class="w-2 h-2 rounded-full bg-amber-400"></span> Thực đơn gói (Kế hoạch)
                      </span>
                      <span class="font-bold text-amber-300">${result.avgPlannedDailyCal} kcal</span>
                    </div>
                    <div class="flex justify-between items-center">
                      <span class="text-slate-300 flex items-center gap-1.5">
                        <span class="w-2 h-2 rounded-full bg-rose-400"></span> Calo thực tế (Gói + Tự do)
                      </span>
                      <span class="font-bold text-rose-300">${result.avgActualDailyCal} kcal</span>
                    </div>
                  </div>
                </div>

                <!-- Weight Forecast and Goal Badge -->
                <div class="bg-gradient-to-r from-emerald-900/40 to-teal-900/40 border border-emerald-500/30 rounded-2xl p-4 mb-4 text-center">
                  <p class="text-[10px] text-emerald-300 uppercase tracking-widest font-black mb-1">Dự báo cân nặng tương lai</p>
                  <div class="text-lg font-black text-white mb-2">
                    Sau ${result.duration} tuần: <span class="text-2xl text-yellow-300">${result.predictedWeight.toFixed(1)}</span> kg 
                    <span class="text-xs font-normal block text-emerald-200 mt-0.5">(${result.weightChangeStr})</span>
                  </div>
                  
                  <!-- Progress bar -->
                  <div class="mt-3">
                    <div class="flex justify-between text-[10px] text-emerald-300 font-semibold mb-1">
                      <span>Tiến độ mục tiêu</span>
                      <span class="font-bold text-yellow-300">${result.percentage}% đạt được</span>
                    </div>
                    <div class="w-full bg-emerald-950 rounded-full h-2.5 overflow-hidden border border-emerald-800">
                      <div class="bg-gradient-to-r from-amber-400 to-yellow-500 h-full rounded-full shadow-[0_0_8px_rgba(251,191,36,0.5)] transition-all duration-1000" style="width: ${result.percentage}%"></div>
                    </div>
                  </div>
                </div>

                <!-- Encouragement & Advice cards -->
                <div class="space-y-3 mb-6 text-left">
                  <div class="bg-emerald-900/30 border border-emerald-800/40 rounded-xl p-3">
                    <p class="text-xs italic text-yellow-100 leading-relaxed font-medium text-center">
                      <i class="fa-solid fa-quote-left text-amber-400 mr-1 opacity-60"></i>
                      ${result.encouragement}
                      <i class="fa-solid fa-quote-right text-amber-400 ml-1 opacity-60"></i>
                    </p>
                  </div>
                  <div class="bg-teal-900/30 border border-teal-800/40 rounded-xl p-3.5">
                    <p class="text-[11px] uppercase tracking-wider text-teal-300 font-bold mb-1 flex items-center gap-1.5">
                      <i class="fa-solid fa-user-doctor"></i> Tư vấn từ Nuri
                    </p>
                    <p class="text-xs text-slate-200 leading-relaxed font-medium">
                      ${result.advice}
                    </p>
                  </div>
                </div>

                <!-- Buttons -->
                <div class="flex flex-col gap-2">
                  <button onclick="closeWrapupModal(); triggerConfetti();" class="w-full bg-gradient-to-r from-amber-400 to-yellow-500 hover:from-amber-500 hover:to-yellow-600 text-[#043F2E] font-black py-3 rounded-xl transition-all shadow-[0_4px_15px_rgba(251,191,36,0.3)] hover:scale-[1.02] active:scale-[0.98]">
                    Tiếp tục duy trì 🔥
                  </button>
                  <button onclick="closeWrapupModal()" class="w-full text-emerald-400 hover:text-emerald-300 text-xs font-bold py-1.5 transition-colors">
                    Đóng báo cáo
                  </button>
                </div>
              `;
              }

              // Show the modal
              modal.classList.remove("pointer-events-none");
              modal.classList.remove("opacity-0");
              modal.classList.add("opacity-100");
              content.classList.remove("scale-95");
              content.classList.add("scale-100");
            } catch (err) {
              console.error("Error executing report opening:", err);
              showToast("Có lỗi xảy ra khi tải báo cáo!", "error");
            }
          },
          "Nuri đang phân tích số liệu hành trình...",
          analysisPromise,
        );
      }

      window.openWrapupModal = openWrapupModal;

      function closeWrapupModal() {
        const modal = document.getElementById("wrapup-modal");
        const content = document.getElementById("wrapup-modal-content");
        if (modal && content) {
          modal.classList.remove("opacity-100");
          modal.classList.add("opacity-0");
          content.classList.remove("scale-100");
          content.classList.add("scale-95");

          setTimeout(() => {
            modal.classList.add("pointer-events-none");
          }, 300);
        }
      }
      window.closeWrapupModal = closeWrapupModal;

      function copyShareContent() {
        const textarea = document.getElementById("share-text-content");
        if (!textarea) return;

        textarea.select();
        textarea.setSelectionRange(0, 99999); // For mobile devices

        try {
          navigator.clipboard
            .writeText(textarea.value)
            .then(() => {
              showCopySuccessFeedback();
            })
            .catch(() => {
              // Fallback for some browsers / iframe environment
              document.execCommand("copy");
              showCopySuccessFeedback();
            });
        } catch (err) {
          // Fallback
          document.execCommand("copy");
          showCopySuccessFeedback();
        }
      }

      function showCopySuccessFeedback() {
        showToast("Đã sao chép nội dung chia sẻ thành công!", "success");
        const btnText = document.getElementById("copy-btn-text");
        if (btnText) {
          const originalText = btnText.innerText;
          btnText.innerText = "Đã sao chép!";
          setTimeout(() => {
            btnText.innerText = originalText;
          }, 2000);
        }
      }

      function shareSocial(platform) {
        const textarea = document.getElementById("share-text-content");
        const content = textarea ? textarea.value : "";

        // Auto copy content to clipboard so user can paste it on the social platform easily
        try {
          navigator.clipboard.writeText(content).catch(() => {});
        } catch (e) {}

        const appUrl = window.location.href;
        let shareUrl = "";

        switch (platform) {
          case "facebook":
            // Facebook share dialog
            shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(appUrl)}&quote=${encodeURIComponent(content)}`;
            break;
          case "twitter":
            // Twitter intent tweet (supports pre-filled text!)
            shareUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(content)}&url=${encodeURIComponent(appUrl)}`;
            break;
          case "zalo":
            // Zalo sharing link
            shareUrl = `https://sp.zalo.me/share_to_zalo?url=${encodeURIComponent(appUrl)}`;
            break;
        }

        if (shareUrl) {
          // Open share link in a new window/tab
          window.open(shareUrl, "_blank", "noopener,noreferrer");
          showToast(
            `Đang chuyển hướng sang ${platform === "twitter" ? "X/Twitter" : platform.toUpperCase()}...`,
            "success",
          );

          // Reward points if under weekly limit
          if (currentUser) {
            const now = Date.now();
            currentUser.shareHistory = (currentUser.shareHistory || []).filter(
              (ts) => isSameCalendarWeek(ts, now),
            );

            if (currentUser.shareHistory.length < 2) {
              currentUser.shareHistory.push(now);
              currentUser.points = (currentUser.points || 0) + 20;
              currentUser.rank = getRankFromPoints(currentUser.points);

              // Update in global customers arrays
              let mainUser = purchasedCustomers.find(
                (c) => c.phone === currentUser.phone,
              );
              if (mainUser) {
                mainUser.points = currentUser.points;
                mainUser.rank = currentUser.rank;
                mainUser.shareHistory = currentUser.shareHistory;
              } else {
                let potUser = potentialCustomers.find(
                  (c) => c.phone === currentUser.phone,
                );
                if (potUser) {
                  potUser.points = currentUser.points;
                  potUser.rank = currentUser.rank;
                  potUser.shareHistory = currentUser.shareHistory;
                }
              }

              // Update local storage
              localStorage.setItem(
                "nutriadmin_current_user",
                JSON.stringify(currentUser),
              );

              // Sync up customers data
              localStorage.setItem(
                "nutriadmin_purchased_customers",
                JSON.stringify(purchasedCustomers),
              );
              localStorage.setItem(
                "nutriadmin_potential_customers",
                JSON.stringify(potentialCustomers),
              );

              // Sync to server
              if (typeof syncStateToServer === "function") syncStateToServer();

              // Refresh modal badge, profile values, and celebrate
              updateShareRewardBadge();
              renderCustomerProfile();
              triggerConfetti();

              setTimeout(() => {
                showToast(
                  `Khoe thành công! Bạn nhận được +20 điểm xếp hạng (Lần ${currentUser.shareHistory.length}/2 tuần này)`,
                  "success",
                );
              }, 1200);
            } else {
              setTimeout(() => {
                showToast(
                  "Bạn đã đạt giới hạn nhận điểm tuần này (tối đa 2 lần/tuần).",
                  "info",
                );
              }, 1200);
            }
          }
        }
      }

      function renderCustomerProfile() {
        try {
          if (!currentUser) return;

          // Re-fetch current user from main data to get latest updates
          const freshUser =
            purchasedCustomers.find((c) => c.phone === currentUser.phone) ||
            potentialCustomers.find((c) => c.phone === currentUser.phone);
          if (freshUser) currentUser = freshUser;

          document.getElementById("profile-name").innerText = currentUser.name;
          document.getElementById("profile-phone").innerText =
            "Thông tin cá nhân";
          const mascotTitle = document.getElementById("mascot-schedule-title");
          if (mascotTitle)
            mascotTitle.innerText =
              "Lịch trình hôm nay của " + currentUser.name;

          // Update streak display
          const streakDays = getStreakDays();
          const streakTitleEl = document.getElementById("profile-streak-title");
          if (streakTitleEl) {
            streakTitleEl.innerText = `Chuỗi duy trì: ${streakDays} ngày`;
          }

          if (currentUser.avatar) {
            document.getElementById("profile-avatar-img").src =
              currentUser.avatar;
            document
              .getElementById("profile-avatar-img")
              .classList.remove("hidden");
            document
              .getElementById("profile-avatar-placeholder")
              .classList.add("hidden");
          } else {
            document
              .getElementById("profile-avatar-img")
              .classList.add("hidden");
            document
              .getElementById("profile-avatar-placeholder")
              .classList.remove("hidden");
          }

          let points = currentUser.points || 0;
          let rank = "Hạt mầm";
          let nextRank = "Mầm cây";
          let progress = 0;
          let hintText = "";

          let rankAgeId = "hat_mam";
          let nextRankAgeId = "mam_cay";

          if (points <= 1000) {
            rank = "Hạt mầm";
            nextRank = "Mầm cây";
            progress = (points / 1000) * 100;
            hintText = `${points}/1000 điểm`;
            rankAgeId = "hat_mam";
            nextRankAgeId = "mam_cay";
          } else if (points <= 2000) {
            rank = "Mầm cây";
            nextRank = "Cây non";
            progress = ((points - 1000) / 1000) * 100;
            hintText = `${points}/2000 điểm`;
            rankAgeId = "mam_cay";
            nextRankAgeId = "cay_non";
          } else if (points <= 4000) {
            rank = "Cây non";
            nextRank = "Cây sự sống";
            progress = ((points - 2000) / 2000) * 100;
            hintText = `${points}/4000 điểm`;
            rankAgeId = "cay_non";
            nextRankAgeId = "cay_lon";
          } else {
            rank = "Cây sự sống";
            nextRank = "MAX";
            progress = 100;
            hintText = `${points} điểm`;
            rankAgeId = "cay_lon";
            nextRankAgeId = "cay_lon";
          }

          window.currentRankAgeId = rankAgeId;
          window.nextRankAgeId = nextRankAgeId;

          document.getElementById("profile-points").innerText = points;
          document.getElementById("profile-rank").innerText = rank;
          document.getElementById("current-rank-label").innerText = rank;
          document.getElementById("next-rank-label").innerText =
            nextRank === "MAX" ? "Cây sự sống" : nextRank;
          document.getElementById("rank-progress-bar").style.width =
            `${progress}%`;
          document.getElementById("rank-hint-text").innerText = hintText;

          // Mascot Evolution Detection
          if (
            typeof window.lastKnownRank !== "undefined" &&
            window.lastKnownRank !== rank
          ) {
            const ranksOrder = ["Hạt mầm", "Mầm cây", "Cây non", "Cây sự sống"];
            const oldIdx = ranksOrder.indexOf(window.lastKnownRank);
            const newIdx = ranksOrder.indexOf(rank);
            if (newIdx > oldIdx) {
              if (typeof triggerMascotEvolution === "function") {
                triggerMascotEvolution(window.lastKnownRank, rank);
              }
            }
          }
          window.lastKnownRank = rank;

          // Render Daily Quests List
          const questsContainer = document.getElementById("daily-quests-list");
          if (questsContainer) {
            const todayStr = new Date().toISOString().split("T")[0];
            const hasCheckedIn = currentUser.lastCheckInDate === todayStr;

            let hasLoggedWeightThisWeek = false;
            const nowTs = Date.now();
            const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

            if (currentUser.lastBodyUpdateRewardTime && (nowTs - currentUser.lastBodyUpdateRewardTime < SEVEN_DAYS_MS)) {
              hasLoggedWeightThisWeek = true;
            } else if (currentUser.lastBmiUpdateDate) {
              hasLoggedWeightThisWeek = isSameCalendarWeek(
                new Date(currentUser.lastBmiUpdateDate).getTime(),
                nowTs,
              );
            }

            let hasSharedThisWeek = false;
            if (currentUser.lastShareRewardTime && (nowTs - currentUser.lastShareRewardTime < SEVEN_DAYS_MS)) {
              hasSharedThisWeek = true;
            } else {
              const filteredShareHistory = (
                currentUser.shareHistory || []
              ).filter((ts) => isSameCalendarWeek(ts, nowTs));
              if (filteredShareHistory.length > 0) {
                hasSharedThisWeek = true;
              }
            }


            questsContainer.innerHTML = `
            <!-- Quest 1: Điểm danh (1 ngày, +5đ) -->
            <div class="flex items-center justify-between p-3.5 rounded-2xl transition-all ${hasCheckedIn ? "bg-slate-100/80 border border-slate-200 opacity-50 grayscale-[20%] pointer-events-none select-none shadow-none" : "bg-emerald-50/25 border border-emerald-100/50 hover:bg-emerald-50/40 shadow-sm"}">
              <div class="flex items-center gap-3">
                <div class="w-9 h-9 rounded-full flex items-center justify-center ${hasCheckedIn ? "bg-emerald-100 text-emerald-600 shadow-sm" : "bg-slate-100 text-slate-400"}">
                  <i class="fa-solid ${hasCheckedIn ? "fa-check text-base font-black" : "fa-calendar-check text-sm"}"></i>
                </div>
                <div>
                  <p class="text-xs md:text-sm font-bold ${hasCheckedIn ? "text-slate-500 flex items-center gap-1.5" : "text-slate-700"}">
                    ${hasCheckedIn ? '<i class="fa-solid fa-circle-check text-emerald-500"></i>' : ''}Điểm danh hôm nay
                  </p>
                  <p class="text-[11px] ${hasCheckedIn ? "text-slate-400 font-medium" : "text-emerald-600 font-bold"}">+5 điểm${hasCheckedIn ? " (Đã nhận)" : ""}</p>
                </div>
              </div>
              ${
                hasCheckedIn
                  ? `
                <span class="text-[11px] font-extrabold text-emerald-700 bg-emerald-100/90 border border-emerald-200 px-3 py-1 rounded-xl flex items-center gap-1.5 shadow-xs"><i class="fa-solid fa-check text-xs font-black"></i> Đã hoàn thành</span>
              `
                  : `
                <button onclick="triggerQuestCheckIn()" class="text-[11px] font-bold bg-emerald-500 hover:bg-emerald-600 text-white px-3.5 py-1.5 rounded-xl shadow-sm transition-all hover:scale-105 active:scale-95 cursor-pointer">Điểm danh</button>
              `
              }
            </div>

            <!-- Quest 2: Ghi nhận cân nặng (7 ngày, +10đ) -->
            <div class="flex items-center justify-between p-3.5 rounded-2xl transition-all ${hasLoggedWeightThisWeek ? "bg-slate-100/80 border border-slate-200 opacity-50 grayscale-[20%] pointer-events-none select-none shadow-none" : "bg-emerald-50/25 border border-emerald-100/50 hover:bg-emerald-50/40 shadow-sm"}">
              <div class="flex items-center gap-3">
                <div class="w-9 h-9 rounded-full flex items-center justify-center ${hasLoggedWeightThisWeek ? "bg-emerald-100 text-emerald-600 shadow-sm" : "bg-slate-100 text-slate-400"}">
                  <i class="fa-solid ${hasLoggedWeightThisWeek ? "fa-check text-base font-black" : "fa-weight-scale text-sm"}"></i>
                </div>
                <div>
                  <p class="text-xs md:text-sm font-bold ${hasLoggedWeightThisWeek ? "text-slate-500 flex items-center gap-1.5" : "text-slate-700"}">
                    ${hasLoggedWeightThisWeek ? '<i class="fa-solid fa-circle-check text-emerald-500"></i>' : ''}Ghi nhận cân nặng tuần này
                  </p>
                  <p class="text-[11px] ${hasLoggedWeightThisWeek ? "text-slate-400 font-medium" : "text-emerald-600 font-bold"}">+10 điểm${hasLoggedWeightThisWeek ? " (Đã nhận)" : ""}</p>
                </div>
              </div>
              ${
                hasLoggedWeightThisWeek
                  ? `
                <span class="text-[11px] font-extrabold text-emerald-700 bg-emerald-100/90 border border-emerald-200 px-3 py-1 rounded-xl flex items-center gap-1.5 shadow-xs"><i class="fa-solid fa-check text-xs font-black"></i> Đã hoàn thành</span>
              `
                  : `
                <button onclick="triggerQuestWeight()" class="text-[11px] font-bold bg-emerald-500 hover:bg-emerald-600 text-white px-3.5 py-1.5 rounded-xl shadow-sm transition-all hover:scale-105 active:scale-95 cursor-pointer">Cập nhật</button>
              `
              }
            </div>

            <!-- Quest 3: Chia sẻ thành tích (7 ngày, +20đ) -->
            <div class="flex items-center justify-between p-3.5 rounded-2xl transition-all ${hasSharedThisWeek ? "bg-slate-100/80 border border-slate-200 opacity-50 grayscale-[20%] pointer-events-none select-none shadow-none" : "bg-emerald-50/25 border border-emerald-100/50 hover:bg-emerald-50/40 shadow-sm"}">
              <div class="flex items-center gap-3">
                <div class="w-9 h-9 rounded-full flex items-center justify-center ${hasSharedThisWeek ? "bg-emerald-100 text-emerald-600 shadow-sm" : "bg-slate-100 text-slate-400"}">
                  <i class="fa-solid ${hasSharedThisWeek ? "fa-check text-base font-black" : "fa-share-nodes text-sm"}"></i>
                </div>
                <div>
                  <p class="text-xs md:text-sm font-bold ${hasSharedThisWeek ? "text-slate-500 flex items-center gap-1.5" : "text-slate-700"}">
                    ${hasSharedThisWeek ? '<i class="fa-solid fa-circle-check text-emerald-500"></i>' : ''}Chia sẻ thành tích tuần này
                  </p>
                  <p class="text-[11px] ${hasSharedThisWeek ? "text-slate-400 font-medium" : "text-emerald-600 font-bold"}">+20 điểm${hasSharedThisWeek ? " (Đã nhận)" : ""}</p>
                </div>
              </div>
              ${
                hasSharedThisWeek
                  ? `
                <span class="text-[11px] font-extrabold text-emerald-700 bg-emerald-100/90 border border-emerald-200 px-3 py-1 rounded-xl flex items-center gap-1.5 shadow-xs"><i class="fa-solid fa-check text-xs font-black"></i> Đã hoàn thành</span>
              `
                  : `
                <button onclick="triggerQuestShare()" class="text-[11px] font-bold bg-emerald-500 hover:bg-emerald-600 text-white px-3.5 py-1.5 rounded-xl shadow-sm transition-all hover:scale-105 active:scale-95 cursor-pointer">Chia sẻ</button>
              `
              }
            </div>
          `;
          }

          // Daily tip
          const tips = [
            "Uống 1 cốc nước ấm vào buổi sáng để thanh lọc cơ thể.",
            "Bổ sung many rau xanh vào bữa ăn để tăng cường chất xơ.",
            "Ngủ đủ 7-8 tiếng mỗi ngày giúp cơ thể phục hồi tốt hơn.",
            "Nhai kỹ thức ăn giúp cải thiện hệ tiêu hóa.",
            "Hạn chế đồ uống có đường và nước có ga.",
            "Tập thể dục 30 phút mỗi ngày giúp tăng sức đề kháng.",
            "Ăn một nắm hạt mỗi ngày bổ sung chất béo tốt cho não bộ.",
          ];
          const tipIndex =
            (new Date().getDate() +
              (currentUser.id
                ? parseInt(currentUser.id.toString().slice(-1))
                : 0)) %
            tips.length;
          document.getElementById("daily-tip").innerText = tips[tipIndex];

          // BMI
          let h = currentUser.height || 0;
          let w = currentUser.weight || 0;
          document.getElementById("profile-height").innerText = h ? h : "--";
          document.getElementById("profile-weight").innerText = w ? w : "--";
          if (h && w) {
            let hm = h / 100;
            let bmi = (w / (hm * hm)).toFixed(1);
            document.getElementById("profile-bmi").innerText = bmi;
            let status = "";
            let bg = "";
            if (bmi < 18.5) {
              status = "Gầy";
              bg = "bg-blue-100 text-blue-700";
            } else if (bmi < 24.9) {
              status = "Bình thường";
              bg = "bg-emerald-100 text-emerald-700";
            } else if (bmi < 29.9) {
              status = "Thừa cân";
              bg = "bg-amber-100 text-amber-700";
            } else {
              status = "Béo phì";
              bg = "bg-red-100 text-red-700";
            }

            const statusEl = document.getElementById("profile-bmi-status");
            statusEl.innerText = status;
            statusEl.className = `px-2 py-1 rounded-md text-xs font-bold ${bg}`;
          } else {
            document.getElementById("profile-bmi").innerText = "--";
            document.getElementById("profile-bmi-status").innerText =
              "Chưa có dữ liệu";
            document.getElementById("profile-bmi-status").className =
              "px-2 py-1 rounded-md bg-slate-200 text-slate-600 text-xs font-bold";
          }
        } catch (e) {
          console.error("renderCustomerProfile error:", e);
        }

        // Subscription
        const subContainer = document.getElementById("profile-subscription");
        let pkgDays = 0;
        if (currentUser.package) {
          const match = String(currentUser.package).match(/\d+/);
          if (match) {
            pkgDays = parseInt(match[0]);
          }
        }

        if (!currentUser.package) {
          subContainer.innerHTML = `
                        <div class="text-center py-4">
                            <p class="text-slate-500 mb-3 text-sm">Bạn chưa đăng ký gói ăn nào.</p>
                            <button onclick="switchView('landing')" class="bg-emerald-100 hover:bg-emerald-200 text-emerald-700 font-semibold px-4 py-2 rounded-lg text-sm transition-colors">Xem các gói ăn</button>
                        </div>
                    `;
        } else {
          const settingsStr = localStorage.getItem("nutriadmin_settings");
          let pkgTexts = {};
          if (settingsStr) {
            try {
              const settings = JSON.parse(settingsStr);
              pkgTexts = settings.packagesText || {};
            } catch (e) {}
          }

          let packageName = `Gói đăng ký`;
          const pkgValStr = String(currentUser.package || "");
          const pLower = pkgValStr.toLowerCase();

          if (
            pLower.includes("trải nghiệm") ||
            pLower.includes("trai nghiem") ||
            pLower === "7" ||
            pLower === "5" ||
            pLower.includes("target_7") ||
            pLower.includes("target_5")
          ) {
            packageName =
              "Gói " + (pkgTexts["front-pkg4-subtitle"] || "Trải Nghiệm");
          } else if (
            pLower.includes("chuyển đổi") ||
            pLower.includes("chuyen doi") ||
            pLower.includes("duy trì") ||
            pLower.includes("duy tri") ||
            pLower === "14" ||
            pLower === "10" ||
            pLower.includes("target_14") ||
            pLower.includes("target_10")
          ) {
            packageName =
              "Gói " + (pkgTexts["front-pkg5-subtitle"] || "Duy Trì");
          } else if (
            pLower.includes("bứt phá") ||
            pLower.includes("but pha") ||
            pLower === "30" ||
            pLower === "28" ||
            pLower === "20" ||
            pLower.includes("target_30") ||
            pLower.includes("target_20")
          ) {
            packageName =
              "Gói " + (pkgTexts["front-pkg6-subtitle"] || "Bứt Phá");
          } else {
            // strip any parenthesis or duration numbers to just show package name
            packageName = `Gói ${currentUser.package
              .replace(/\s*\(\d+\s*Ngày\)/i, "")
              .replace(/\d+\s*Ngày/i, "")
              .trim()}`;
          }

          let pkgDurationDays = 7;
          if (
            pLower.includes("trải nghiệm") ||
            pLower.includes("trai nghiem") ||
            pLower === "7" ||
            pLower === "5" ||
            pLower.includes("target_7") ||
            pLower.includes("target_5")
          ) {
            pkgDurationDays = 7;
          } else if (
            pLower.includes("chuyển đổi") ||
            pLower.includes("chuyen doi") ||
            pLower.includes("duy trì") ||
            pLower.includes("duy tri") ||
            pLower === "14" ||
            pLower === "10" ||
            pLower.includes("target_14") ||
            pLower.includes("target_10")
          ) {
            pkgDurationDays = 14;
          } else if (
            pLower.includes("bứt phá") ||
            pLower.includes("but pha") ||
            pLower === "30" ||
            pLower === "28" ||
            pLower === "20" ||
            pLower.includes("target_30") ||
            pLower.includes("target_20")
          ) {
            pkgDurationDays = 28;
          } else {
            pkgDurationDays = pkgDays > 0 ? pkgDays : 7;
          }

          let packageDatesHtml = `
            <div class="mt-2 text-xs text-slate-500 space-y-1 font-medium bg-slate-50 border border-slate-100 p-2.5 rounded-lg">
              <div class="flex items-center gap-1.5">
                <i class="fa-regular fa-calendar-check text-slate-400"></i>
                <span>Bắt đầu: <strong class="text-slate-600">Chưa kích hoạt</strong></span>
              </div>
              <div class="flex items-center gap-1.5">
                <i class="fa-regular fa-calendar-xmark text-slate-400"></i>
                <span>Kết thúc: <strong class="text-slate-600">Chưa kích hoạt</strong></span>
              </div>
            </div>
          `;

          let warningHtml = "";

          if (currentUser.startDate && pkgDurationDays > 0) {
            const sDate = new Date(currentUser.startDate);
            const eDate = new Date(
              sDate.getTime() + pkgDurationDays * 24 * 60 * 60 * 1000,
            );
            const sStr = sDate.toLocaleDateString("vi-VN");
            const eStr = eDate.toLocaleDateString("vi-VN");
            packageDatesHtml = `
              <div class="mt-2 text-xs text-slate-500 space-y-1.5 font-medium bg-slate-50 border border-slate-100 p-2.5 rounded-lg">
                <div class="flex items-center gap-1.5">
                  <i class="fa-regular fa-calendar-check text-emerald-600 font-bold"></i>
                  <span>Bắt đầu: <strong class="text-slate-700">${sStr}</strong></span>
                </div>
                <div class="flex items-center gap-1.5">
                  <i class="fa-regular fa-calendar-xmark text-rose-500 font-bold"></i>
                  <span>Kết thúc: <strong class="text-slate-700">${eStr}</strong></span>
                </div>
              </div>
            `;

            // Calculate remaining days
            const today = new Date();
            const todayStart = new Date(
              today.getFullYear(),
              today.getMonth(),
              today.getDate(),
            );
            const eDateStart = new Date(
              eDate.getFullYear(),
              eDate.getMonth(),
              eDate.getDate(),
            );
            const diffDays = Math.ceil(
              (eDateStart.getTime() - todayStart.getTime()) /
                (1000 * 60 * 60 * 24),
            );

            if (diffDays <= 2) {
              warningHtml = `
                <div class="flex-1 md:max-w-xs bg-rose-50 border border-rose-200 rounded-xl p-3 flex flex-col gap-3 animate-pulse shadow-sm self-stretch">
                  <div class="flex items-center gap-3">
                    <div class="w-24 h-24 shrink-0 flex items-center justify-center bg-white rounded-lg border border-rose-100 p-0.5">
                      <div id="profile-warning-mascot-svg" class="w-full h-full flex items-center justify-center [&_svg]:w-24 [&_svg]:h-24 [&_svg]:drop-shadow-none"></div>
                      <img id="profile-warning-mascot-img" class="w-full h-full object-contain hidden" alt="Mascot Ngạc Nhiên" />
                    </div>
                    <div class="flex-1">
                      <p class="text-[10px] text-rose-700 font-bold mb-0.5 flex items-center gap-1 uppercase tracking-wider">
                        <i class="fa-solid fa-triangle-exclamation"></i> Nhắc nhở gia hạn
                      </p>
                      <p class="text-[11px] text-rose-600 font-semibold leading-normal">
                        Bạn cần đăng ký gia hạn gói trước ngày <span class="underline text-rose-700 font-bold">${eStr}</span> để tiếp tục.
                      </p>
                    </div>
                  </div>
                  <button onclick="openWrapupModal()" class="w-full relative z-10 bg-white hover:bg-slate-50 text-slate-600 font-bold py-1.5 rounded-lg text-xs border border-slate-200 transition-colors flex items-center justify-center gap-2">
                    <i class="fa-solid fa-medal text-amber-500"></i> Xem Báo cáo Tổng kết
                  </button>
                </div>
              `;
            } else {
              // Add a button for Wrapup Report even if not expiring
              warningHtml = `
                <div class="flex-1 flex flex-col justify-center">
                  <button onclick="openWrapupModal()" class="w-full max-w-[200px] ml-auto relative z-10 bg-white hover:bg-slate-50 text-slate-600 font-bold py-2 rounded-lg text-xs border border-slate-200 transition-colors flex items-center justify-center gap-2 shadow-sm">
                    <i class="fa-solid fa-medal text-amber-500"></i> Báo cáo Tổng kết
                  </button>
                </div>
              `;
            }
          }

          let todayMenuHtml = "";
          if (currentUser.weeklyMenu) {
            const dayIndex = new Date().getDay();
            const currentDayKey =
              dayIndex === 0 ? "sunday" : weekDays[dayIndex - 1].key;
            const selectedDayMenu = currentUser.weeklyMenu[currentDayKey];

            if (
              selectedDayMenu &&
              (selectedDayMenu.meal1?.dishId || selectedDayMenu.meal2?.dishId)
            ) {
              let meals = [];
              if (selectedDayMenu.meal1?.dishId) {
                const dish = dishes.find(
                  (x) => x.id == selectedDayMenu.meal1.dishId,
                );
                if (dish) {
                  meals.push({
                    dish: dish,
                    size: selectedDayMenu.meal1.size || "balance",
                    label: "Bữa 1",
                  });
                }
              }
              if (selectedDayMenu.meal2?.dishId) {
                const dish = dishes.find(
                  (x) => x.id == selectedDayMenu.meal2.dishId,
                );
                if (dish) {
                  meals.push({
                    dish: dish,
                    size: selectedDayMenu.meal2.size || "balance",
                    label: "Bữa 2",
                  });
                }
              }

              if (meals.length > 0) {
                todayMenuHtml = `
                                    <div class="mt-4 mb-4">
                                        <p class="text-sm font-bold text-slate-700 mb-2">Thực đơn hôm nay của bạn:</p>
                                        <div class="flex flex-col gap-3">
                                            ${meals
                                              .map((m) => {
                                                const sizeData =
                                                  m.dish.sizes &&
                                                  m.dish.sizes[m.size]
                                                    ? m.dish.sizes[m.size]
                                                    : {
                                                        kcal: 0,
                                                        protein: 0,
                                                        carbs: 0,
                                                        fat: 0,
                                                      };
                                                const sizeLabel =
                                                  m.size === "balance"
                                                    ? "Standard"
                                                    : "Large";
                                                return `
                                                <div class="flex bg-white border border-slate-100 rounded-xl overflow-hidden shadow-sm">
                                                    <img src="${m.dish.image}" class="w-24 h-24 object-cover shrink-0" alt="${m.dish.name}">
                                                    <div class="p-3 flex-1 flex flex-col justify-center">
                                                        <div class="flex justify-between items-start mb-1">
                                                            <span class="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded uppercase tracking-wider">${m.label}</span>
                                                            <span class="text-[10px] font-bold text-slate-500 border border-slate-200 px-1.5 py-0.5 rounded">${sizeLabel}</span>
                                                        </div>
                                                        <p class="text-sm font-semibold text-slate-800 line-clamp-1 mb-1.5" title="${m.dish.name}">${m.dish.name}</p>
                                                        <div class="flex gap-2 text-[10px] text-slate-500 font-medium">
                                                            <span><i class="fa-solid fa-fire text-orange-500 mr-0.5"></i>${sizeData?.kcal}kcal</span>
                                                            <span><i class="fa-solid fa-dumbbell text-blue-500 mr-0.5"></i>${sizeData?.protein}g P</span>
                                                            <span><i class="fa-solid fa-wheat-awn text-yellow-600 mr-0.5"></i>${sizeData?.carbs}g C</span>
                                                            <span><i class="fa-solid fa-droplet text-rose-500 mr-0.5"></i>${sizeData?.fat || 0}g F</span>
                                                        </div>
                                                    </div>
                                                </div>
                                                `;
                                              })
                                              .join("")}
                                        </div>
                                    </div>
                                `;
              }
            }
          }
          if (!todayMenuHtml) {
            todayMenuHtml = `<div class="mt-4 mb-4 p-3 bg-slate-50 border border-slate-100 rounded-xl text-center text-sm text-slate-500">Bạn chưa chọn món cho hôm nay.</div>`;
          }

          subContainer.innerHTML = `
                        <div class="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                            <div class="flex-1 min-w-0">
                                <p class="font-bold text-slate-800 text-lg">${packageName}</p>
                                ${packageDatesHtml}
                            </div>
                            ${warningHtml}
                            <span class="bg-emerald-100 text-emerald-700 text-xs font-bold px-2 py-1 rounded-md mt-1 shrink-0 self-start md:self-auto">ACTIVE</span>
                        </div>
                        ${todayMenuHtml}
                        ${currentUser.renewalPending ? `<div class="mt-3 p-3 bg-amber-50 border border-amber-200 rounded-xl text-amber-800 text-xs font-bold flex items-center justify-between gap-2 shadow-sm"><div class="flex items-center gap-2"><i class="fa-solid fa-clock-rotate-left text-amber-600 text-sm animate-spin"></i><span>Chờ Nuri xác nhận thanh toán và gia hạn gói cho bạn nhé</span></div><button onclick="openRenewSubscriptionModal()" class="text-indigo-600 hover:underline shrink-0 text-[11px]">Xem QR</button></div>` : ""}
                        <div class="mt-2 space-y-3">
                            <button onclick="openCustomerMenuModal(${currentUser.id})" class="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-semibold py-2.5 rounded-xl text-sm transition-colors flex justify-center items-center gap-2">
                                <i class="fa-solid fa-utensils"></i> Chọn lại menu tuần
                            </button>
                            <button id="btn-order-outside-pkg" onclick="window.openPlatformSelectorModal()" class="w-full bg-orange-500 hover:bg-orange-600 text-white font-semibold py-2.5 rounded-xl text-sm transition-colors flex justify-center items-center gap-2 shadow-sm">
                                <i class="fa-solid fa-cart-shopping"></i> Đặt hàng ngoài gói đăng ký
                            </button>
                            <button onclick="openRenewSubscriptionModal()" class="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-2.5 rounded-xl text-sm transition-colors flex justify-center items-center gap-2 shadow-sm">
                                <i class="fa-solid fa-repeat"></i> Gia hạn gói ăn
                            </button>
                        </div>
                    `;
        }

        // Suggestions (Chỉ lấy Món theo công thức & Món mới mỗi tuần)
        const hiddenKeywordsSug = dishes
          .filter((d) => d.isActive === false)
          .map((d) => d.name)
          .filter(Boolean)
          .concat(
            dishes
              .flatMap((d) =>
                (d.methods || []).filter((m) => m.isHidden).map((m) => m.name),
              )
              .filter(Boolean),
          );
        const fixedLunchIds = (window.weeklyFixedDishes && window.weeklyFixedDishes.lunch) || [];
        const fixedDinnerIds = (window.weeklyFixedDishes && window.weeklyFixedDishes.dinner) || [];
        const suggestedDishes = [...dishes]
          .filter(
            (d) =>
              d.isActive !== false &&
              !d.isCustom &&
              (
                d.category === "complete" ||
                d.category === "weekly_special" ||
                d.isWeekly ||
                fixedLunchIds.some((id) => String(id) === String(d.id)) ||
                fixedDinnerIds.some((id) => String(id) === String(d.id))
              ) &&
              d.category !== "protein" &&
              d.category !== "carbs" &&
              d.category !== "veggies" &&
              d.category !== "sauce" &&
              !hiddenKeywordsSug.some(
                (kw) =>
                  d.name.includes(kw) ||
                  (d.ingredients && d.ingredients.includes(kw)),
              ),
          )
          .sort(() => 0.5 - Math.random())
          .slice(0, 4);
        const sugContainer = document.getElementById("profile-suggestions");
        if (sugContainer && suggestedDishes.length > 0) {
          sugContainer.innerHTML = `
                        <div class="flex justify-between items-end mb-3">
                            <h3 class="font-bold text-slate-800 flex items-center gap-2"><i class="fa-solid fa-sparkles text-amber-500"></i> Có thể bạn sẽ thích</h3>
                        </div>
                        <div class="flex gap-4 overflow-x-auto pb-4 snap-x -mx-6 px-6" style="scrollbar-width: none;">
                            ${suggestedDishes
                              .map(
                                (d) => `
                                <div class="min-w-[140px] max-w-[140px] bg-white border border-slate-100 rounded-2xl overflow-hidden shadow-sm snap-start shrink-0 group cursor-pointer" onclick="openCustomerMenuModal(${currentUser.id})">
                                    <div class="relative h-24 overflow-hidden">
                                        <img src="${d.image}" class="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" alt="${d.name}">
                                    </div>
                                    <div class="p-3">
                                        <p class="text-sm font-bold text-slate-800 line-clamp-2 leading-tight mb-1 group-hover:text-emerald-600 transition-colors">${d.name}</p>
                                        <p class="text-xs text-emerald-600 font-semibold">${d.calo} kcal</p>
                                    </div>
                                </div>
                            `,
                              )
                              .join("")}
                        </div>
                    `;
        }

        // Meal Calendar (Timeline)
        const timelineContainer = document.getElementById(
          "meal-timeline-container",
        );
        if (timelineContainer) {
          const dayConfigs = [
            { key: "monday", label: "Thứ 2" },
            { key: "tuesday", label: "Thứ 3" },
            { key: "wednesday", label: "Thứ 4" },
            { key: "thursday", label: "Thứ 5" },
            { key: "friday", label: "Thứ 6" },
            { key: "saturday", label: "Thứ 7" },
            { key: "sunday", label: "CN" },
          ];
          const todayIndex =
            new Date().getDay() === 0 ? 6 : new Date().getDay() - 1; // 0-6 (Mon-Sun)

          if (typeof ensureCustomerWeeklyMenuDefaults === "function") {
            ensureCustomerWeeklyMenuDefaults(currentUser);
          }
          const weeklyMenu = currentUser.weeklyMenu || {};
          const userOrders = (typeof orders !== "undefined" && Array.isArray(orders))
            ? orders.filter((o) => (o.phone === currentUser.phone || o.customerPhone === currentUser.phone))
            : [];

          let timelineHtml = dayConfigs
            .map((config, idx) => {
              const isToday = idx === todayIndex;
              const dayKey = config.key;
              const dayLabel = config.label;
              const dayMenu = weeklyMenu[dayKey] || {};

              // Extract Meals for Lunch (meal1) and Dinner (meal2)
              const meals = [];
              if (dayMenu.meal1 && dayMenu.meal1.dishId) {
                const dish = dishes.find((d) => d.id == dayMenu.meal1.dishId);
                if (dish) {
                  const sizeData = dish.sizes ? dish.sizes[dayMenu.meal1.size] : null;
                  meals.push({
                    type: "meal1",
                    mealLabel: "Bữa Trưa",
                    dish: dish,
                    sizeLabel: dayMenu.meal1.size === "power" ? "Power (L)" : dayMenu.meal1.size === "lean" ? "Lean (S)" : "Balance (M)",
                    kcal: sizeData ? sizeData.kcal : (dish.calo || 0),
                  });
                }
              }
              if (dayMenu.meal2 && dayMenu.meal2.dishId) {
                const dish = dishes.find((d) => d.id == dayMenu.meal2.dishId);
                if (dish) {
                  const sizeData = dish.sizes ? dish.sizes[dayMenu.meal2.size] : null;
                  meals.push({
                    type: "meal2",
                    mealLabel: "Bữa Tối",
                    dish: dish,
                    sizeLabel: dayMenu.meal2.size === "power" ? "Power (L)" : dayMenu.meal2.size === "lean" ? "Lean (S)" : "Balance (M)",
                    kcal: sizeData ? sizeData.kcal : (dish.calo || 0),
                  });
                }
              }

              // Check if order for this day has status "completed" (Đã giao) in admin order management
              const matchingOrder = userOrders.find((o) => {
                if (o.notes && o.notes.includes(dayLabel)) return true;
                if (o.dayKey === dayKey) return true;
                return false;
              });

              let statusDot = isToday
                ? '<div class="absolute -left-[5px] top-4 w-3 h-3 rounded-full bg-amber-500 border-2 border-white animate-ping"></div><div class="absolute -left-[5px] top-4 w-3 h-3 rounded-full bg-amber-500 border-2 border-white"></div>'
                : '<div class="absolute -left-[5px] top-4 w-3 h-3 rounded-full bg-slate-300 border-2 border-white"></div>';

              const mealsHtml = meals
                .map((m) => {
                  const isFavorite = localStorage.getItem(`fav_${m.dish.id}`) === "true";
                  const isMealDelivered = matchingOrder ? matchingOrder.status === "completed" : false;

                  if (isMealDelivered) {
                    return `
                      <div class="flex bg-slate-100/90 border border-slate-200 rounded-xl p-2.5 gap-3 items-center opacity-60 grayscale shadow-xs">
                        <img src="${m.dish.image}" class="w-11 h-11 object-cover rounded-lg shrink-0">
                        <div class="flex-1 min-w-0">
                          <div class="flex justify-between items-center">
                            <span class="text-[10px] font-bold text-slate-500 bg-slate-200 px-1.5 py-0.5 rounded">${m.mealLabel}</span>
                            <span class="text-[10px] font-extrabold text-emerald-700 bg-emerald-100 border border-emerald-200 px-2 py-0.5 rounded-md flex items-center gap-1">
                              <i class="fa-solid fa-check text-xs"></i> Đã giao
                            </span>
                          </div>
                          <p class="text-xs font-bold text-slate-700 truncate line-through mt-0.5">${m.dish.name}</p>
                          <p class="text-[10px] text-slate-500 font-semibold">${m.kcal} kcal • ${m.sizeLabel}</p>
                        </div>
                      </div>
                    `;
                  } else if (isToday) {
                    return `
                      <div class="flex bg-amber-50/70 border border-amber-200/80 rounded-xl p-2.5 gap-3 items-center shadow-xs">
                        <img src="${m.dish.image}" class="w-12 h-12 object-cover rounded-lg shadow-2xs shrink-0">
                        <div class="flex-1 min-w-0">
                          <div class="flex justify-between items-start">
                            <span class="text-[10px] font-bold text-amber-700 bg-amber-100/90 px-1.5 py-0.5 rounded">${m.mealLabel}</span>
                            <button onclick="toggleFavorite(${m.dish.id})" class="text-rose-500 hover:scale-110 transition-transform">
                              <i class="${isFavorite ? "fa-solid" : "fa-regular"} fa-heart"></i>
                            </button>
                          </div>
                          <p class="text-xs font-bold text-slate-800 truncate mt-0.5">${m.dish.name}</p>
                          <p class="text-[10px] text-amber-900 font-semibold">${m.kcal} kcal • ${m.sizeLabel}</p>
                        </div>
                      </div>
                    `;
                  } else {
                    return `
                      <div class="flex bg-white border border-slate-100 rounded-xl p-2.5 gap-3 items-center opacity-75 shadow-2xs">
                        <img src="${m.dish.image}" class="w-10 h-10 object-cover rounded-lg grayscale shrink-0">
                        <div class="flex-1 min-w-0">
                          <div class="flex justify-between items-center">
                            <span class="text-[10px] font-bold text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded">${m.mealLabel}</span>
                            <span class="text-[10px] text-slate-400">Dự kiến: ${m.type === "meal1" ? "11:00 - 12:00" : "17:30 - 18:30"}</span>
                          </div>
                          <p class="text-xs font-bold text-slate-700 truncate mt-0.5">${m.dish.name}</p>
                          <p class="text-[10px] text-slate-400">${m.kcal} kcal • ${m.sizeLabel}</p>
                        </div>
                      </div>
                    `;
                  }
                })
                .join("");

              return `
                <div class="relative pl-6 space-y-2">
                  ${statusDot}
                  <div class="mb-1">
                    <span class="text-xs font-bold ${isToday ? "text-amber-600" : "text-slate-600"}">${dayLabel} ${isToday ? "(Hôm nay)" : ""}</span>
                  </div>
                  <div class="space-y-2">
                    ${mealsHtml}
                  </div>
                </div>
              `;
            })
            .join("");

          timelineContainer.innerHTML = timelineHtml;
        }

        if (typeof updateNutritionDashboard === "function") {
          updateNutritionDashboard();
        }

        if (typeof updatePersonalMascot === "function") {
          updatePersonalMascot();
        }
        if (typeof updateProfileWarningMascot === "function") {
          updateProfileWarningMascot();
        }
        if (typeof window.updateOrderPlatformButtonsVisibility === "function") {
          window.updateOrderPlatformButtonsVisibility();
        }
      }

      setInterval(() => {
        if (
          typeof updatePersonalMascot === "function" &&
          document.getElementById("view-customer-profile") &&
          !document
            .getElementById("view-customer-profile")
            .classList.contains("hidden")
        ) {
          updatePersonalMascot();
        }
      }, 60000); // check every minute

      function updatePersonalMascot() {
        const mascotImg = document.getElementById("personal-mascot-img");
        const mascotImgSvg = document.getElementById("personal-mascot-img-svg");
        const mascotPrevImg = document.getElementById("personal-mascot-prev");
        const mascotPrevImgSvg = document.getElementById(
          "personal-mascot-prev-svg",
        );
        const mascotNextImg = document.getElementById("personal-mascot-next");
        const mascotNextImgSvg = document.getElementById(
          "personal-mascot-next-svg",
        );

        if (!mascotImg) return;

        const timePrevStr = document.getElementById("mascot-time-prev");
        const timeCurrStr = document.getElementById("mascot-time-curr");
        const timeNextStr = document.getElementById("mascot-time-next");

        const now = new Date();
        const time = now.getHours() + now.getMinutes() / 60;

        const defaultSchedule = [
          { start: 6, end: 7, id: "thuc_day", label: "06:00 - 07:00" },
          { start: 7, end: 7.5, id: "tap_the_duc", label: "07:00 - 07:30" },
          { start: 7.5, end: 8, id: "an", label: "07:30 - 08:00" },
          { start: 8, end: 11.5, id: "lam_viec", label: "08:00 - 11:30" },
          { start: 11.5, end: 12.5, id: "an", label: "11:30 - 12:30" },
          { start: 12.5, end: 13, id: "giai_tri", label: "12:30 - 13:00" },
          { start: 13, end: 17, id: "lam_viec", label: "13:00 - 17:00" },
          { start: 17, end: 18, id: "tap_the_duc", label: "17:00 - 18:00" },
          { start: 18, end: 19, id: "an", label: "18:00 - 19:00" },
          { start: 19, end: 22, id: "giai_tri", label: "19:00 - 22:00" },
          { start: 22, end: 6, id: "ngu", label: "22:00 - 06:00" },
        ];

        let mascotSchedule =
          currentUser &&
          currentUser.mascotSchedule &&
          currentUser.mascotSchedule.length > 0
            ? currentUser.mascotSchedule
            : defaultSchedule;

        if (mascotSchedule.length === 0) {
          mascotSchedule = [
            { start: 0, end: 24, id: "vui_ve", label: "Cả ngày" },
          ];
        }

        let currentIndex = 0;
        for (let i = 0; i < mascotSchedule.length; i++) {
          const s = mascotSchedule[i];
          if (s.start > s.end) {
            if (time >= s.start || time < s.end) {
              currentIndex = i;
              break;
            }
          } else {
            if (time >= s.start && time < s.end) {
              currentIndex = i;
              break;
            }
          }
        }

        const prevIndex =
          (currentIndex - 1 + mascotSchedule.length) % mascotSchedule.length;
        const nextIndex = (currentIndex + 1) % mascotSchedule.length;

        const currentSlot = mascotSchedule[currentIndex];
        const prevSlot = mascotSchedule[prevIndex];
        const nextSlot = mascotSchedule[nextIndex];

        if (timePrevStr) timePrevStr.innerText = prevSlot.label;
        if (timeCurrStr) timeCurrStr.innerText = currentSlot.label;
        if (timeNextStr) timeNextStr.innerText = nextSlot.label;

        if (window.personalMascotInterval)
          clearInterval(window.personalMascotInterval);

        // ALWAYS prefer activeMascotId if set, so user's manual selection (e.g. ngac_nhien) takes effect
        const currentSlotId = currentSlot.id;
        const currentSlotObj = { id: currentSlotId, label: currentSlot.label };

        function setupMascot(imgElement, svgElement, slot) {
          if (!imgElement) return null;
          let frames = [];
          if (
            typeof mascotLoadedSequences !== "undefined" &&
            mascotLoadedSequences[slot.id] &&
            mascotLoadedSequences[slot.id].length > 0
          ) {
            frames = mascotLoadedSequences[slot.id];
          } else if (
            typeof mascotLoadedSequences !== "undefined" &&
            mascotLoadedSequences["vui_ve"] &&
            mascotLoadedSequences["vui_ve"].length > 0
          ) {
            frames = mascotLoadedSequences["vui_ve"];
          }

          if (frames.length > 0) {
            if (svgElement) svgElement.classList.add("hidden");
            imgElement.classList.remove("hidden");
            imgElement.src = frames[0];
            return { type: "img", frames: frames };
          } else {
            imgElement.classList.add("hidden");
            if (svgElement) svgElement.classList.remove("hidden");
            return { type: "svg", expressionId: slot.id };
          }
        }

        const currObj = setupMascot(mascotImg, mascotImgSvg, currentSlotObj);
        const prevObj = setupMascot(mascotPrevImg, mascotPrevImgSvg, prevSlot);
        const nextObj = setupMascot(mascotNextImg, mascotNextImgSvg, nextSlot);

        let frameIdx = 0;
        const updateAllFrames = () => {
          // Current
          if (currObj) {
            if (currObj.type === "img") {
              mascotImg.src = currObj.frames[frameIdx % currObj.frames.length];
            } else if (
              currObj.type === "svg" &&
              typeof drawMascotSVG === "function"
            ) {
              let svgStr = drawMascotSVG(currObj.expressionId, frameIdx);
              svgStr = svgStr.replace(
                'class="w-40 h-40 filter drop-shadow-[0_0_20px_rgba(16,185,129,0.4)]"',
                'class="w-full h-full drop-shadow-xl"',
              );
              mascotImgSvg.innerHTML = svgStr;
            }
          }
          // Prev
          if (prevObj) {
            if (prevObj.type === "img") {
              mascotPrevImg.src =
                prevObj.frames[frameIdx % prevObj.frames.length];
            } else if (
              prevObj.type === "svg" &&
              typeof drawMascotSVG === "function"
            ) {
              let svgStr = drawMascotSVG(prevObj.expressionId, frameIdx);
              svgStr = svgStr.replace(
                'class="w-40 h-40 filter drop-shadow-[0_0_20px_rgba(16,185,129,0.4)]"',
                'class="w-full h-full opacity-50"',
              );
              mascotPrevImgSvg.innerHTML = svgStr;
            }
          }
          // Next
          if (nextObj) {
            if (nextObj.type === "img") {
              mascotNextImg.src =
                nextObj.frames[frameIdx % nextObj.frames.length];
            } else if (
              nextObj.type === "svg" &&
              typeof drawMascotSVG === "function"
            ) {
              let svgStr = drawMascotSVG(nextObj.expressionId, frameIdx);
              svgStr = svgStr.replace(
                'class="w-40 h-40 filter drop-shadow-[0_0_20px_rgba(16,185,129,0.4)]"',
                'class="w-full h-full opacity-50"',
              );
              mascotNextImgSvg.innerHTML = svgStr;
            }
          }
        };

        updateAllFrames();

        window.personalMascotInterval = setInterval(
          () => {
            frameIdx++;
            updateAllFrames();
          },
          1000 / (typeof mascotFps !== "undefined" ? mascotFps : 12),
        );
      }

      function updateProfileWarningMascot() {
        if (window.profileWarningMascotInterval) {
          clearInterval(window.profileWarningMascotInterval);
        }

        const warningSvg = document.getElementById(
          "profile-warning-mascot-svg",
        );
        const warningImg = document.getElementById(
          "profile-warning-mascot-img",
        );

        if (warningSvg && warningImg) {
          let frames = [];
          if (
            typeof mascotLoadedSequences !== "undefined" &&
            mascotLoadedSequences["ngac_nhien"] &&
            mascotLoadedSequences["ngac_nhien"].length > 0
          ) {
            frames = mascotLoadedSequences["ngac_nhien"];
          } else if (
            typeof mascotLoadedSequences !== "undefined" &&
            mascotLoadedSequences["vui_ve"] &&
            mascotLoadedSequences["vui_ve"].length > 0
          ) {
            frames = mascotLoadedSequences["vui_ve"];
          }

          if (frames.length > 0) {
            warningSvg.classList.add("hidden");
            warningImg.classList.remove("hidden");
            warningImg.src = frames[0];
            let frameIdx = 0;
            window.profileWarningMascotInterval = setInterval(
              () => {
                frameIdx++;
                warningImg.src = frames[frameIdx % frames.length];
              },
              1000 / (typeof mascotFps !== "undefined" ? mascotFps : 12),
            );
          } else {
            warningImg.classList.add("hidden");
            warningSvg.classList.remove("hidden");
            let frameIdx = 0;
            const updateSvg = () => {
              let svgStr =
                typeof drawMascotSVG === "function"
                  ? drawMascotSVG("ngac_nhien", frameIdx)
                  : "";
              svgStr = svgStr.replace(
                'class="w-40 h-40 filter drop-shadow-[0_0_20px_rgba(16,185,129,0.4)]"',
                'class="w-full h-full drop-shadow-sm"',
              );
              warningSvg.innerHTML = svgStr;
            };
            updateSvg();
            window.profileWarningMascotInterval = setInterval(
              () => {
                frameIdx++;
                updateSvg();
              },
              1000 / (typeof mascotFps !== "undefined" ? mascotFps : 12),
            );
          }
        }
      }

      function showToast(message, type = "success") {
        const container = document.getElementById("toast-container");
        const toast = document.createElement("div");
        let icon =
          type === "success"
            ? '<i class="fa-solid fa-circle-check text-emerald-500"></i>'
            : type === "error"
              ? '<i class="fa-solid fa-circle-xmark text-red-500"></i>'
              : '<i class="fa-solid fa-circle-info text-blue-500"></i>';

        toast.className = `bg-white border border-slate-200 shadow-lg rounded-lg p-4 flex items-center gap-3 transform transition-all duration-300 translate-y-4 opacity-0 pointer-events-auto`;
        toast.innerHTML = `${icon} <span class="text-sm font-medium text-slate-800">${message}</span>`;

        container.appendChild(toast);
        setTimeout(
          () => toast.classList.remove("translate-y-4", "opacity-0"),
          10,
        );

        setTimeout(() => {
          toast.classList.add("translate-y-4", "opacity-0");
          setTimeout(() => toast.remove(), 300);
        }, 3000);
      }

      function openConfirmModal(message, callback) {
        document.getElementById("confirm-message").innerText = message;
        confirmActionCallback = callback;
        document.getElementById("confirm-modal").classList.remove("hidden");
      }

      function closeConfirmModal() {
        document.getElementById("confirm-modal").classList.add("hidden");
        confirmActionCallback = null;
      }

      document
        .getElementById("btn-confirm-action")
        .addEventListener("click", () => {
          if (confirmActionCallback) confirmActionCallback();
          closeConfirmModal();
        });

      // ==========================================
      // 3. SYSTEM & NAVIGATION
      // ==========================================

      function refreshBrandUI() {
        const savedSettings = localStorage.getItem("nutriadmin_settings");
        let settings = { brandName: "", brandLogo: "" };
        if (savedSettings) {
          settings = JSON.parse(savedSettings);
        }

        const storeName = settings.brandName || "Nuri Kitchen";
        const logoData = settings.brandLogo; // base64 string or empty
        const faviconData = settings.favicon || settings.brandLogo; // use favicon, fallback to brandLogo

        document.title = `${storeName} - Quản Lý Menu Healthy`;

        // Refresh Favicon
        let faviconLink = document.querySelector("link[rel='icon']");
        if (!faviconLink) {
          faviconLink = document.createElement("link");
          faviconLink.rel = "icon";
          document.head.appendChild(faviconLink);
        }
        if (faviconData) {
          faviconLink.href = faviconData;
          faviconLink.type = faviconData.startsWith("data:image/svg") ? "image/svg+xml"
            : faviconData.startsWith("data:image/png") ? "image/png" : "image/jpeg";
        } else {
          faviconLink.href = "/logo.svg";
          faviconLink.type = "image/svg+xml";
        }

        // Refresh Header Logo & Name
        const headerBrandEl = document.getElementById("header-brand-name");
        if (headerBrandEl) headerBrandEl.innerText = storeName;

        const headerLogoContainer = document.getElementById(
          "header-logo-container",
        );
        if (headerLogoContainer) {
          if (logoData) {
            headerLogoContainer.innerHTML = `<img src="${logoData}" class="w-8 h-8 rounded-lg object-cover" alt="Logo" />`;
          } else {
            headerLogoContainer.innerHTML = `<i class="fa-solid fa-leaf"></i>`;
          }
        }

        // Refresh Chatbot greeting name
        const chatbotGreetingMsg = document.getElementById(
          "chatbot-greeting-msg",
        );
        if (chatbotGreetingMsg) {
          chatbotGreetingMsg.innerHTML = `Chào bạn! Nuri là chuyên gia dinh dưỡng ảo của ${storeName}. 👋<br /><br />Nuri có thể giúp bạn giải đáp các thắc mắc về calo, gợi ý món ăn, hoặc tư vấn lộ trình giảm cân. Bạn cần hỗ trợ gì ạ?`;
        }

        // Refresh success overlay
        // Refresh Kitchen Footer
        const footerKitchenBrand = document.getElementById("footer-kitchen-brand-name");
        if (footerKitchenBrand) footerKitchenBrand.innerText = storeName;
        const footerKitchenCopy = document.getElementById("footer-kitchen-copyright-name");
        if (footerKitchenCopy) footerKitchenCopy.innerText = storeName;
        
        let addressStr = [];
        if (settings.street) addressStr.push(settings.street);
        if (settings.ward) addressStr.push(settings.ward);
        if (settings.district) addressStr.push(settings.district);
        addressStr.push("TP. Hồ Chí Minh");
        
        const footerKitchenAddress = document.getElementById("footer-kitchen-address");
        if (footerKitchenAddress) footerKitchenAddress.innerText = addressStr.join(", ");
        
        const footerKitchenPhone = document.getElementById("footer-kitchen-phone");
        if (footerKitchenPhone) footerKitchenPhone.innerText = settings.phone || "Chưa cập nhật";
        
        const footerKitchenZalo = document.getElementById("footer-kitchen-zalo");
        if (footerKitchenZalo) footerKitchenZalo.innerText = settings.zalo || "Chưa cập nhật";

        const fbIcon = document.getElementById("footer-social-facebook");
        if (fbIcon) fbIcon.href = formatSocialUrl(settings.facebook, "facebook");
        const igIcon = document.getElementById("footer-social-instagram");
        if (igIcon) igIcon.href = formatSocialUrl(settings.instagram, "instagram");
        const ttIcon = document.getElementById("footer-social-tiktok");
        if (ttIcon) ttIcon.href = formatSocialUrl(settings.tiktok, "tiktok");

        const successOverlayText = document.getElementById(
          "success-overlay-text",
        );
        if (successOverlayText) {
          successOverlayText.innerText = `${storeName} đã tiếp nhận thông tin và sẽ liên hệ với bạn trong thời gian sớm nhất.`;
        }

        // Refresh Landing Brand Name
        const landingBrandName = document.getElementById("landing-brand-name");
        if (landingBrandName) {
          landingBrandName.innerText = storeName;
        }
        if (typeof window.updateOrderPlatformButtonsVisibility === "function") {
          window.updateOrderPlatformButtonsVisibility();
        }
      }

      window.updateOrderPlatformButtonsVisibility = function() {
        try {
          const settingsStr = localStorage.getItem("nutriadmin_settings");
          const settings = settingsStr ? JSON.parse(settingsStr) : {};
          const isWebsiteOn = settings.orderWebsiteEnable !== false;
          const isShopeeOn = !!settings.orderShopeeFoodEnable;
          const isGrabOn = !!settings.orderGrabFoodEnable;
          const isXanhsmOn = !!settings.orderXanhSMEnable;

          const hasAnyPlatform = isWebsiteOn || isShopeeOn || isGrabOn || isXanhsmOn;

          const btnRegisterSingle = document.getElementById("btn-register-single-meal");
          if (btnRegisterSingle) {
            btnRegisterSingle.style.display = hasAnyPlatform ? "" : "none";
          }

          const btnSkipAnalysis = document.getElementById("skip-analysis-btn");
          if (btnSkipAnalysis) {
            btnSkipAnalysis.style.display = hasAnyPlatform ? "" : "none";
          }

          const btnOrderOutside = document.getElementById("btn-order-outside-pkg");
          if (btnOrderOutside) {
            btnOrderOutside.style.display = hasAnyPlatform ? "" : "none";
          }
        } catch(e) {
          console.error("Lỗi cập nhật ẩn hiện nút đặt hàng:", e);
        }
      };

      function getKitchenPos() {
        const savedSettings = localStorage.getItem("nutriadmin_settings");
        let settingsLat = 10.7769;
        let settingsLng = 106.7009;
        if (savedSettings) {
          const parsed = JSON.parse(savedSettings);
          if (parsed.lat && parsed.lng) {
            settingsLat = parseFloat(parsed.lat);
            settingsLng = parseFloat(parsed.lng);
          }
        }
        return [settingsLat, settingsLng];
      }

      function initSettingsLocation() {
        const d = document.getElementById("set-district");
        if (!d) return;
        d.innerHTML = '<option value="">Quận/Huyện</option>';
        for (let k in locationData["TP. Hồ Chí Minh"]) {
          d.innerHTML += `<option value="${k}">${k}</option>`;
        }
      }

      function updateSetWards() {
        const setDistrict = document.getElementById("set-district");
        if (!setDistrict) return;
        const d = setDistrict.value,
          w = document.getElementById("set-ward");
        if (!w) return;
        const currentW = w.value;
        w.innerHTML = '<option value="">Phường/Xã</option>';
        if (d && window.locationData && window.locationData["TP. Hồ Chí Minh"] && window.locationData["TP. Hồ Chí Minh"][d]) {
          w.disabled = false;
          window.locationData["TP. Hồ Chí Minh"][d].forEach(wd => {
            w.innerHTML += `<option value="${wd}">${wd}</option>`;
          });
          if (currentW) w.value = currentW;
        } else {
          w.disabled = true;
        }
      }

      function getStoreLocationFromGoogle() {
        if ("geolocation" in navigator) {
          navigator.geolocation.getCurrentPosition(
            function (position) {
              document.getElementById("set-lat").value =
                position.coords.latitude;
              document.getElementById("set-lng").value =
                position.coords.longitude;
              showToast("Đã lấy định vị cửa hàng thành công!", "success");
            },
            function (error) {
              showToast("Không thể lấy định vị: " + error.message, "error");
            },
          );
        } else {
          showToast("Trình duyệt không hỗ trợ Geolocation", "error");
        }
      }

      let syncTimeout = null;
      window.promptUpdateImage = function (id) {
        const input = document.createElement("input");
        input.type = "file";
        input.accept = "image/*";
        input.onchange = function (e) {
          const file = e.target.files[0];
          if (!file) return;
          const reader = new FileReader();
          reader.onload = function (event) {
            const base64 = event.target.result;
            const el = document.getElementById(id);
            if (el) el.src = base64;
            
            const savedSettings = localStorage.getItem("nutriadmin_settings");
            let existingSettings = savedSettings ? JSON.parse(savedSettings) : {};
            if (!existingSettings.packagesImages) existingSettings.packagesImages = {};
            existingSettings.packagesImages[id] = base64;
            
            localStorage.setItem("nutriadmin_settings", JSON.stringify(existingSettings));
            if (typeof syncStateToServer === "function") {
              clearTimeout(syncTimeout);
              syncTimeout = setTimeout(() => {
                syncStateToServer();
              }, 500);
            }
          };
          reader.readAsDataURL(file);
        };
        input.click();
      };

      window.updateTextSync = function (id, text, isHtml = false) {
        var el = document.getElementById(id);
        if (el && el !== document.activeElement) {
          if (isHtml) el.innerHTML = text;
          else el.innerText = text;
        }

        const savedSettings = localStorage.getItem("nutriadmin_settings");
        let existingSettings = savedSettings ? JSON.parse(savedSettings) : {};
        let changed = false;

        if (id === "user-banner-grand-opening-text") {
          if (existingSettings.bannerGrandOpeningText !== text) {
            existingSettings.bannerGrandOpeningText = text;
            changed = true;
          }
        } else if (id === "revenue-goal") {
          if (existingSettings.revenueGoal !== text) {
            existingSettings.revenueGoal = text;
            changed = true;
            if (typeof renderDashboard === "function") {
              clearTimeout(window.revenueGoalUpdateTimeout);
              window.revenueGoalUpdateTimeout = setTimeout(
                renderDashboard,
                300,
              );
            }
          }
        } else if (id.startsWith("front-pkg")) {
          if (!existingSettings.packagesText)
            existingSettings.packagesText = {};
          if (existingSettings.packagesText[id] !== text) {
            existingSettings.packagesText[id] = text;
            changed = true;
          }
        } else if (id.startsWith("user-banner")) {
          if (!existingSettings.bannerTexts) existingSettings.bannerTexts = {};
          if (existingSettings.bannerTexts[id] !== text) {
            existingSettings.bannerTexts[id] = text;
            changed = true;
          }
        }

        if (changed) {
          localStorage.setItem(
            "nutriadmin_settings",
            JSON.stringify(existingSettings),
          );
          if (typeof syncStateToServer === "function") {
            clearTimeout(syncTimeout);
            syncTimeout = setTimeout(() => {
              syncStateToServer();
            }, 500);
          }
        }
      };

      // Real-time synchronization of Trust Banner fields
      window.updateTrustField = function (field, value) {
        const savedSettings = localStorage.getItem("nutriadmin_settings");
        let settings = savedSettings ? JSON.parse(savedSettings) : {};
        if (!settings.trustBanner) {
          settings.trustBanner = {};
        }
        settings.trustBanner[field] = value;
        localStorage.setItem("nutriadmin_settings", JSON.stringify(settings));

        // Immediately sync to DOM elements across the 3 banners
        if (field === "brandName") {
          [
            "landing-brand-name",
            "user-trust-brand-name-2",
            "admin-trust-brand-name",
          ].forEach((id) => {
            const el = document.getElementById(id);
            if (el && el !== document.activeElement) {
              if (id === "landing-brand-name") {
                const subSpan = document.getElementById(
                  "user-trust-brand-name-1",
                );
                if (subSpan) subSpan.innerText = value;
                else el.innerText = value;
              } else {
                el.innerText = value;
              }
            }
          });
        } else if (field === "title") {
          [
            "user-trust-title-1",
            "user-trust-title-2",
            "admin-trust-title",
          ].forEach((id) => {
            const el = document.getElementById(id);
            if (el && el !== document.activeElement) el.innerHTML = value;
          });
        } else if (field === "subtitle") {
          [
            "user-trust-subtitle-1",
            "user-trust-subtitle-2",
            "admin-trust-subtitle",
          ].forEach((id) => {
            const el = document.getElementById(id);
            if (el && el !== document.activeElement) el.innerHTML = value;
          });
        } else if (field === "trustCount") {
          [
            "user-trust-count-1",
            "user-trust-count-2",
            "admin-trust-count",
          ].forEach((id) => {
            const el = document.getElementById(id);
            if (el && el !== document.activeElement) el.innerText = value;
          });
        } else if (field === "trustText") {
          [
            "user-trust-text-1",
            "user-trust-text-2",
            "admin-trust-text",
          ].forEach((id) => {
            const el = document.getElementById(id);
            if (el && el !== document.activeElement) el.innerText = value;
          });
        } else if (field === "ctaText") {
          ["user-trust-cta-1", "user-trust-cta-2", "admin-trust-cta"].forEach(
            (id) => {
              const el = document.getElementById(id);
              if (el && el !== document.activeElement) el.innerText = value;
            },
          );
        } else if (field === "freeText") {
          [
            "user-trust-free-1",
            "user-trust-free-2",
            "admin-trust-free",
          ].forEach((id) => {
            const el = document.getElementById(id);
            if (el && el !== document.activeElement) el.innerText = value;
          });
        }

        // Trigger network sync if needed
        if (typeof syncStateToServer === "function") {
          clearTimeout(syncTimeout);
          syncTimeout = setTimeout(() => {
            syncStateToServer();
          }, 500);
        }
      };

      // Appends defaults or actual settings to all 3 Trust Banners on load
      window.applyTrustBannerSettings = function (settings) {
        const tb = settings.trustBanner || {};
        const defaultBrand = "Nuri Kitchen";
        const defaultTitle =
          'Khám phá dinh dưỡng<br class="hidden md:block" /> cá nhân hóa';
        const defaultSubtitle =
          "Nuri phân tích chỉ số cơ thể và đề xuất thực đơn phù hợp với mục tiêu của bạn chỉ trong 4 bước đơn giản.";
        const defaultCount = "5.000+";
        const defaultText = "khách đã tin tưởng";
        const defaultCta = "Bắt đầu phân tích";
        const defaultFree = "Miễn phí 100%";

        const brandVal =
          tb.brandName !== undefined ? tb.brandName : defaultBrand;
        const titleVal = tb.title !== undefined ? tb.title : defaultTitle;
        const subtitleVal =
          tb.subtitle !== undefined ? tb.subtitle : defaultSubtitle;
        const countVal =
          tb.trustCount !== undefined ? tb.trustCount : defaultCount;
        const textVal = tb.trustText !== undefined ? tb.trustText : defaultText;
        const ctaVal = tb.ctaText !== undefined ? tb.ctaText : defaultCta;
        const freeVal = tb.freeText !== undefined ? tb.freeText : defaultFree;

        // Sync brand name
        const b1 = document.getElementById("user-trust-brand-name-1");
        if (b1) b1.innerText = brandVal;
        const b2 = document.getElementById("user-trust-brand-name-2");
        if (b2) b2.innerText = brandVal;
        const bAdmin = document.getElementById("admin-trust-brand-name");
        if (bAdmin) bAdmin.innerText = brandVal;

        // Sync title
        const t1 = document.getElementById("user-trust-title-1");
        if (t1) t1.innerHTML = titleVal;
        const t2 = document.getElementById("user-trust-title-2");
        if (t2) t2.innerHTML = titleVal;
        const tAdmin = document.getElementById("admin-trust-title");
        if (tAdmin) tAdmin.innerHTML = titleVal;

        // Sync subtitle
        const s1 = document.getElementById("user-trust-subtitle-1");
        if (s1) s1.innerHTML = subtitleVal;
        const s2 = document.getElementById("user-trust-subtitle-2");
        if (s2) s2.innerHTML = subtitleVal;
        const sAdmin = document.getElementById("admin-trust-subtitle");
        if (sAdmin) sAdmin.innerHTML = subtitleVal;

        // Sync count
        const c1 = document.getElementById("user-trust-count-1");
        if (c1) c1.innerText = countVal;
        const c2 = document.getElementById("user-trust-count-2");
        if (c2) c2.innerText = countVal;
        const cAdmin = document.getElementById("admin-trust-count");
        if (cAdmin) cAdmin.innerText = countVal;

        // Sync text
        const tx1 = document.getElementById("user-trust-text-1");
        if (tx1) tx1.innerText = textVal;
        const tx2 = document.getElementById("user-trust-text-2");
        if (tx2) tx2.innerText = textVal;
        const txAdmin = document.getElementById("admin-trust-text");
        if (txAdmin) txAdmin.innerText = textVal;

        // Sync CTA
        const cta1 = document.getElementById("user-trust-cta-1");
        if (cta1) cta1.innerText = ctaVal;
        const cta2 = document.getElementById("user-trust-cta-2");
        if (cta2) cta2.innerText = ctaVal;
        const ctaAdmin = document.getElementById("admin-trust-cta");
        if (ctaAdmin) ctaAdmin.innerText = ctaVal;

        // Sync Free
        const f1 = document.getElementById("user-trust-free-1");
        if (f1) f1.innerText = freeVal;
        const f2 = document.getElementById("user-trust-free-2");
        if (f2) f2.innerText = freeVal;
        const fAdmin = document.getElementById("admin-trust-free");
        if (fAdmin) fAdmin.innerText = freeVal;

        // Sync Image display (On/Off)
        const showTop = tb.showTopImage !== undefined ? tb.showTopImage : true;
        const showBottom =
          tb.showBottomImage !== undefined ? tb.showBottomImage : true;
        const showCenter =
          tb.showCenterImage !== undefined ? tb.showCenterImage : true;
        const centerScale =
          tb.centerImageScale !== undefined ? tb.centerImageScale : 100;

        // Toggle Top Containers
        [
          "admin-trust-top-container",
          "user-trust-top-container-1",
          "user-trust-top-container-2",
        ].forEach((id) => {
          const el = document.getElementById(id);
          if (el) {
            if (showTop) {
              el.classList.remove("hidden");
            } else {
              el.classList.add("hidden");
            }
          }
        });

        // Toggle Bottom Containers
        [
          "admin-trust-bottom-container",
          "user-trust-bottom-container-1",
          "user-trust-bottom-container-2",
        ].forEach((id) => {
          const el = document.getElementById(id);
          if (el) {
            if (showBottom) {
              el.classList.remove("hidden");
            } else {
              el.classList.add("hidden");
            }
          }
        });

        // Toggle Center Containers
        [
          "admin-trust-center-container",
          "user-trust-center-container-1",
          "user-trust-center-container-2",
        ].forEach((id) => {
          const el = document.getElementById(id);
          if (el) {
            if (showCenter) {
              el.classList.remove("hidden");
            } else {
              el.classList.add("hidden");
            }
          }
        });

        // Apply Center Image Scale (to scale wrappers)
        [
          "admin-trust-center-scale-wrapper",
          "user-trust-center-scale-wrapper-1",
          "user-trust-center-scale-wrapper-2",
        ].forEach((id) => {
          const el = document.getElementById(id);
          if (el) {
            el.style.transform = `scale(${centerScale / 100})`;
          }
        });

        // Also update the checkboxes in the UI!
        const toggleTopCheckbox = document.getElementById("toggle-trust-top");
        if (toggleTopCheckbox) {
          toggleTopCheckbox.checked = showTop;
          const textSpan =
            toggleTopCheckbox.nextElementSibling?.nextElementSibling;
          if (textSpan) textSpan.innerText = showTop ? "Hiện" : "Ẩn";
        }
        const toggleBottomCheckbox = document.getElementById(
          "toggle-trust-bottom",
        );
        if (toggleBottomCheckbox) {
          toggleBottomCheckbox.checked = showBottom;
          const textSpan =
            toggleBottomCheckbox.nextElementSibling?.nextElementSibling;
          if (textSpan) textSpan.innerText = showBottom ? "Hiện" : "Ẩn";
        }
        const toggleCenterCheckbox = document.getElementById(
          "toggle-trust-center",
        );
        if (toggleCenterCheckbox) {
          toggleCenterCheckbox.checked = showCenter;
          const textSpan =
            toggleCenterCheckbox.nextElementSibling?.nextElementSibling;
          if (textSpan) textSpan.innerText = showCenter ? "Hiện" : "Ẩn";
        }

        const scaleSlider = document.getElementById("scale-trust-center");
        if (scaleSlider) {
          scaleSlider.value = centerScale;
        }
        const scaleValSpan = document.getElementById("scale-trust-center-val");
        if (scaleValSpan) {
          scaleValSpan.innerText = `${centerScale}%`;
        }
      };

      window.toggleTrustImage = function (position, isChecked) {
        const savedSettings = localStorage.getItem("nutriadmin_settings");
        let settings = savedSettings ? JSON.parse(savedSettings) : {};
        if (!settings.trustBanner) {
          settings.trustBanner = {};
        }
        if (position === "top") {
          settings.trustBanner.showTopImage = isChecked;
        } else if (position === "bottom") {
          settings.trustBanner.showBottomImage = isChecked;
        } else if (position === "center") {
          settings.trustBanner.showCenterImage = isChecked;
        }
        localStorage.setItem("nutriadmin_settings", JSON.stringify(settings));

        // Sync instantly to DOM
        if (typeof applyTrustBannerSettings === "function") {
          applyTrustBannerSettings(settings);
        }

        // Sync to server
        if (typeof syncStateToServer === "function") {
          clearTimeout(syncTimeout);
          syncTimeout = setTimeout(() => {
            syncStateToServer();
          }, 500);
        }
      };

      window.changeTrustCenterScale = function (value) {
        const savedSettings = localStorage.getItem("nutriadmin_settings");
        let settings = savedSettings ? JSON.parse(savedSettings) : {};
        if (!settings.trustBanner) {
          settings.trustBanner = {};
        }
        settings.trustBanner.centerImageScale = parseInt(value, 10);
        localStorage.setItem("nutriadmin_settings", JSON.stringify(settings));

        // Sync instantly to DOM
        if (typeof applyTrustBannerSettings === "function") {
          applyTrustBannerSettings(settings);
        }

        // Sync to server
        if (typeof syncStateToServer === "function") {
          clearTimeout(syncTimeout);
          syncTimeout = setTimeout(() => {
            syncStateToServer();
          }, 500);
        }
      };

