            if (settings.packagesImages) {
              Object.entries(settings.packagesImages).forEach(([id, src]) => {
                const elId = document.getElementById(id);
                if (elId) elId.src = src;
                const pubId = id.replace('front-', 'public-');
                const pubEl = document.getElementById(pubId);
                if (pubEl) pubEl.src = src;
              });
            }

            if (settings.bannerTexts) {
              Object.entries(settings.bannerTexts).forEach(([id, text]) => {
                const el = document.querySelector(`[oninput*="${id}"]`);
                if (el && el !== document.activeElement) {
                  if (id === "user-banner-badge2-line2") el.innerHTML = text;
                  else el.innerText = text;
                }
                const elId = document.getElementById(id);
                if (elId && elId !== document.activeElement) {
                  if (id === "user-banner-badge2-line2") elId.innerHTML = text;
                  else elId.innerText = text;
                }
                document.querySelectorAll(`.public-pkg-sync[data-sync="${id}"]`).forEach(pubEl => {
                  pubEl.innerText = text;
                });
              });
            }

            if (window.loadAllBannerImages) window.loadAllBannerImages();
