      async function testFirebaseConfig() {
        let configStr = document
          .getElementById("custom-firebase-config")
          .value.trim();
        if (!configStr) {
          showToast("Vui lòng điền cấu hình Firebase để kiểm tra.", "error");
          return;
        }

        let config;
        try {
          const match = configStr.match(/\{[\s\S]*\}/);
          if (match) {
            config = new Function("return " + match[0])();
            configStr = JSON.stringify(config); // Normalize
          } else {
            throw new Error("No object found");
          }
        } catch (e) {
          showToast(
            "Cấu hình không đúng định dạng. Vui lòng copy đúng Object config.",
            "error",
          );
          return;
        }

        if (!config.apiKey || !config.projectId) {
          showToast("Cấu hình Firebase thiếu apiKey hoặc projectId.", "error");
          return;
        }

        showToast("Đang kiểm tra kết nối...", "info");
        try {
          if (typeof firebase !== "undefined") {
            const tempId = "test_app_" + Date.now();
            const tempApp = firebase.initializeApp(config, tempId);
            const tempDb = tempApp.firestore(); tempDb.settings({ experimentalForceLongPolling: true });
            await tempDb.collection("nutriadmin_v1").limit(1).get();
            showToast("Kết nối Firebase thành công!", "success");
            tempApp.delete();
          } else {
            const response = await fetch(
              `https://firestore.googleapis.com/v1/projects/${config.projectId}/databases/(default)/documents?key=${config.apiKey}&pageSize=1`,
            );
            if (response.ok) {
              showToast("Kết nối Firebase thành công!", "success");
            } else if (response.status === 403 || response.status === 401) {
              showToast(
                "Kết nối Firebase thành công! (Dữ liệu được bảo mật bởi Rules)",
                "success",
              );
            } else if (response.status === 404) {
              showToast(
                "Dự án Firebase không tồn tại hoặc chưa bật Firestore.",
                "error",
              );
            } else if (response.status === 400) {
              showToast("API Key không hợp lệ.", "error");
            } else {
              showToast(
                "Kết nối Firebase thất bại (Mã lỗi " + response.status + ").",
                "error",
              );
            }
          }
        } catch (error) {
          console.error("Firebase Test Error:", error);
          if (
            error &&
            error.code &&
            (error.code.includes("permission-denied") ||
              error.code === "permission-denied" ||
              (error.message &&
                error.message.includes("Missing or insufficient permissions")))
          ) {
            showToast(
              "Kết nối Firebase thành công! (Dữ liệu được bảo vệ bởi Rules)",
              "success",
            );
            // Cleanup temp app if rules blocked it
            try {
              const tempApp = firebase.app(
                "test_app_" + Date.now().toString().slice(0, -3),
              ); // Approximate cleanup
            } catch (e) {}
          } else {
            showToast(
              "Lỗi mạng hoặc sai cấu hình khi kết nối Firebase.",
              "error",
            );
          }
        }
      }

