      function decodeJwtResponse(token) {
        var base64Url = token.split(".")[1];
        var base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
        var jsonPayload = decodeURIComponent(
          window
            .atob(base64)
            .split("")
            .map(function (c) {
              return "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2);
            })
            .join(""),
        );
        return JSON.parse(jsonPayload);
      }

      function handleGoogleCredentialResponse(response) {
        const payload = decodeJwtResponse(response.credential);
        const email = payload.email;
        const name = payload.name;

        let customer =
          purchasedCustomers.find(
            (c) => c.email === email || c.phone === email,
          ) ||
          potentialCustomers.find(
            (c) => c.email === email || c.phone === email,
          );

        if (!customer) {
          customer = {
            id: Date.now().toString(),
            name: name,
            email: email,
            phone: email, // use email as identifier if no phone
            points: 0,
            joinDate: new Date().toISOString(),
          };
          potentialCustomers.push(customer);
          syncStateToServer();
          showToast("Tạo tài khoản Google thành công!", "success");
        } else {
          showToast("Đăng nhập Google thành công!", "success");
        }

        currentUser = customer;
        localStorage.setItem(
          "nutriadmin_current_user",
          JSON.stringify(currentUser),
        );
        saveToLocalAccounts(currentUser);

        closeAuthModal("login");
        closeAuthModal("register");
        if (typeof closeSwitchAccountModal === "function")
          closeSwitchAccountModal();

        renderLandingAuth();
        switchView("customer-profile");

        if (typeof renderAccountsList === "function") {
          renderAccountsList();
        }
      }

      function initGoogleSignIn() {
        const clientId = localStorage.getItem("nutriadmin_google_client_id");
        const originDisplay = document.getElementById("current-origin-display");
        if (originDisplay) {
          originDisplay.innerText = window.location.origin;
        }

        if (clientId) {
          const inputEl = document.getElementById("custom-google-client-id");
          if (inputEl) inputEl.value = clientId;

          if (
            typeof google !== "undefined" &&
            google.accounts &&
            google.accounts.id
          ) {
            google.accounts.id.initialize({
              client_id: clientId,
              callback: handleGoogleCredentialResponse,
            });

            const btnConfig = {
              theme: "outline",
              size: "power",
              width: "100%",
              text: "continue_with",
            };

            const loginContainer = document.getElementById("g_id_signin_login");
            if (loginContainer) {
              google.accounts.id.renderButton(loginContainer, btnConfig);
              document
                .getElementById("google-signin-container-login")
                .classList.remove("hidden");
            }

            const regContainer = document.getElementById(
              "g_id_signin_register",
            );
            if (regContainer) {
              google.accounts.id.renderButton(regContainer, btnConfig);
              document
                .getElementById("google-signin-container-register")
                .classList.remove("hidden");
            }

            const switchContainer =
              document.getElementById("g_id_signin_switch");
            if (switchContainer) {
              google.accounts.id.renderButton(switchContainer, btnConfig);
              document
                .getElementById("google-signin-container-switch")
                .classList.remove("hidden");
            }
          } else {
            // Google script might not be fully loaded yet, try again in a moment
            setTimeout(initGoogleSignIn, 1000);
          }
        }
      }

      let firebaseConfigTimeout;
      function onFirebaseConfigInput() {
        clearTimeout(firebaseConfigTimeout);
        firebaseConfigTimeout = setTimeout(() => {
          const config = document
            .getElementById("custom-firebase-config")
            .value.trim();
          if (config) {
            try {
              const match = config.match(/\{[\s\S]*\}/);
              let parsedConfig;
              if (match) {
                parsedConfig = new Function("return " + match[0])();
              } else {
                parsedConfig = JSON.parse(config);
              }
              localStorage.setItem(
                "nutriadmin_custom_firebase_config",
                JSON.stringify(parsedConfig),
              );
              showToast("Đã tự động lưu cấu hình Cloud.", "success");
            } catch (e) {
              // Ignore parse errors silently during auto-save
            }
          } else {
            localStorage.removeItem("nutriadmin_custom_firebase_config");
          }
        }, 2000);
      }

      function exportData() {
        const dataToExport = {
          settings: JSON.parse(
            localStorage.getItem("nutriadmin_settings") || "{}",
          ),
          dishes: dishes,
          inventory: typeof inventory !== 'undefined' ? inventory : [],
          trackingSources: trackingSources,
          discountCodes: discountCodes,
          potentialCustomers: potentialCustomers,
          purchasedCustomers: purchasedCustomers,
          shippers: shippers,
          orders: orders,
          allReviews: typeof allReviews !== 'undefined' ? allReviews : {},
          allChats: typeof allChats !== 'undefined' ? allChats : {},
          qrScans: typeof qrScans !== 'undefined' ? qrScans : [],
          mascotExpressions: typeof mascotExpressions !== 'undefined' ? mascotExpressions : [],
          mascotActions: typeof mascotActions !== 'undefined' ? mascotActions : [],
          mascotAges: typeof mascotAges !== 'undefined' ? mascotAges : [],
          activeMascotId: typeof activeMascotId !== 'undefined' ? activeMascotId : null,
          pwaCustomIcon: typeof pwaCustomIcon !== 'undefined' ? pwaCustomIcon : null,
          pwaNotifications: typeof pwaNotifications !== 'undefined' ? pwaNotifications : [],
          pwaBadgeActive: typeof pwaBadgeActive !== 'undefined' ? pwaBadgeActive : false
        };

        const dataStr =
          "data:text/json;charset=utf-8," +
          encodeURIComponent(JSON.stringify(dataToExport, null, 2));
        const downloadNode = document.createElement("a");
        downloadNode.setAttribute("href", dataStr);

        const date = new Date();
        const dateString = `${date.getFullYear()}${String(date.getMonth() + 1).padStart(2, "0")}${String(date.getDate()).padStart(2, "0")}`;
        downloadNode.setAttribute(
          "download",
          `NuriKitchen_Backup_${dateString}.json`,
        );

        document.body.appendChild(downloadNode);
        downloadNode.click();
        downloadNode.remove();
        showToast("Đã tải xuống file sao lưu dữ liệu!", "success");
      }

      function importData(event) {
        const file = event.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = function (e) {
          try {
            const importedData = JSON.parse(e.target.result);

            // Basic structure validation
            if (!importedData.dishes || !importedData.orders) {
              throw new Error(
                "File JSON không đúng cấu trúc dữ liệu của Nuri Kitchen.",
              );
            }

            openConfirmModal(
              "Cảnh báo: Toàn bộ dữ liệu hiện tại sẽ bị ghi đè bằng dữ liệu trong file. Bạn có chắc chắn muốn phục hồi?",
              () => {
                // Apply imported data
                if (importedData.settings)
                  localStorage.setItem(
                    "nutriadmin_settings",
                    JSON.stringify(importedData.settings),
                  );
                dishes = importedData.dishes || [];
                if (importedData.inventory) inventory = importedData.inventory;
                trackingSources = importedData.trackingSources || [];
                discountCodes = importedData.discountCodes || [];
                shippers = importedData.shippers || [];
                
                if (importedData.allReviews) allReviews = importedData.allReviews;
                if (importedData.allChats) {
                   allChats = importedData.allChats;
                   localStorage.setItem("nutriadmin_all_chats", JSON.stringify(allChats));
                }
                if (importedData.qrScans) qrScans = importedData.qrScans;
                if (importedData.mascotExpressions) mascotExpressions = importedData.mascotExpressions;
                if (importedData.mascotActions) mascotActions = importedData.mascotActions;
                if (importedData.mascotAges) mascotAges = importedData.mascotAges;
                if (importedData.activeMascotId !== undefined) activeMascotId = importedData.activeMascotId;
                if (importedData.pwaCustomIcon !== undefined) pwaCustomIcon = importedData.pwaCustomIcon;
                if (importedData.pwaNotifications !== undefined) pwaNotifications = importedData.pwaNotifications;
                if (importedData.pwaBadgeActive !== undefined) pwaBadgeActive = importedData.pwaBadgeActive;

                // Parse date strings back to Date objects
                orders = (importedData.orders || []).map((o) => ({
                  ...o,
                  timestamp: new Date(o.timestamp),
                }));
                potentialCustomers = (
                  importedData.potentialCustomers || []
                ).map((c) => ({ ...c, date: new Date(c.date) }));
                purchasedCustomers = importedData.purchasedCustomers || [];

                // Re-render UI
                loadSettings();
                if (window.loadAllBannerImages) window.loadAllBannerImages();
                renderCategories();
                renderDishes();
                renderOrdersAdmin();
                renderShippers();
                renderTrackingSources();
                renderDiscountCodes();
                renderPotentialCustomers();
                renderPurchasedCustomers();
                if (
                  document
                    .getElementById("view-dashboard")
                    .classList.contains("block")
                )
                  renderDashboard();
                if (
                  document
                    .getElementById("view-marketing")
                    .classList.contains("block")
                )
                  renderMarketingDashboard();

                showToast("Đã phục hồi dữ liệu thành công!", "success");
              },
            );
          } catch (error) {
            console.error("Import Error:", error);
            showToast("Lỗi đọc file: " + error.message, "error");
          } finally {
            // Reset input so the same file can be selected again
            event.target.value = "";
          }
        };
        reader.readAsText(file);
      }

      function isAdminViewActive() {
        const params = new URLSearchParams(window.location.search);
        return params.get("mode") === "admin";
      }

      function switchView(viewName) {
  document.querySelectorAll('.reveal.active, .reveal-left.active, .reveal-right.active, .reveal-scale.active').forEach(el => el.classList.remove('active'));
        if (isAdminViewActive()) {
          if (!checkAdminSessionSilent()) {
            window.pendingAdminView = viewName;
            showAdminAuthOverlay();
            const notifContainer = document.getElementById("admin-notification-container");
            if (notifContainer) {
                notifContainer.classList.add("hidden");
                notifContainer.classList.remove("flex");
            }
            return;
          }
          // Đã pass kiểm tra session (đã đăng nhập), cho phép truy cập tất cả các tab
          const notifContainer = document.getElementById("admin-notification-container");
          if (notifContainer) {
              notifContainer.classList.remove("hidden");
              notifContainer.classList.add("flex");
              if (typeof renderAdminNotifications === "function") {
                  renderAdminNotifications();
              }
          }
        } else {
          const notifContainer = document.getElementById("admin-notification-container");
          if (notifContainer) {
              notifContainer.classList.add("hidden");
              notifContainer.classList.remove("flex");
          }
        }

        if (viewName !== "consulting" && window.isUpdatingProfile) {
          window.isUpdatingProfile = false;
          let rec = document.getElementById("menu-recommendation-container");
          if (rec && rec.parentElement)
            rec.parentElement.style.display = "block";
          let saveBtn = document.getElementById("save-profile-action");
          if (saveBtn) saveBtn.classList.add("hidden");
        }
        if (viewName === "landing") viewName = "consulting";
        const urlParams = new URLSearchParams(window.location.search);
        const _up = new URLSearchParams(window.location.search);
        const isUrlLandingMode =
          _up.get("mode") === "landing" ||
          !!_up.get("utm_source") ||
          !!_up.get("source");
        const isLandingMode = isUrlLandingMode || isSimulating;

        if (
          isLandingMode &&
          ![
            "consulting",
            "kitchen",
            "order-form",
            "tracking",
            "customer-profile",
          ].includes(viewName)
        )
          return;

        const main = document.querySelector("main");
        if (main) {
          if (
            viewName === "shipper-app" ||
            (isLandingMode &&
              [
                "consulting",
                "kitchen",
                "order-form",
                "tracking",
                "customer-profile",
              ].includes(viewName))
          ) {
            main.classList.add("px-4", "sm:px-6", "lg:px-8", "py-8");
            main.classList.remove("px-0", "py-0");
          } else {
            main.classList.add("px-4", "sm:px-6", "lg:px-8", "py-8");
            main.classList.remove("px-0", "py-0");
          }
        }

        const views = [
          "dashboard",
          "marketing",
          "menu",
          "inventory",
          "messages",
          "system",
          "consulting",
          "kitchen",
          "customers",
          "order-form",
          "tracking",
          "customer-profile",
          "orders",
          "shipper-app",
        ];
        views.forEach((v) => {
          const el = document.getElementById(`view-${v}`);
          if (el) {
            el.classList.add("hidden");
            if (v === "consulting" || v === "messages")
              el.classList.remove("flex");
          }
        });

        const chatbotFab = document.getElementById("chatbot-fab");
        const chatbotWindow = document.getElementById("chatbot-window");
        if (chatbotFab) {
          let showChatbot = false;
          if (viewName === "order-form" || viewName === "customer-profile" || viewName === "consulting" || viewName === "kitchen") {
            showChatbot = true;
          }

          if (showChatbot) {
            chatbotFab.classList.remove("hidden");
            chatbotFab.classList.add("flex");

            // Di chuyển chatbot vào trong wrapper nếu đang ở chế độ giả lập điện thoại
            let activeWrapper = null;
            if (viewName === "consulting")
              activeWrapper = document.getElementById(
                "consulting-content-wrapper",
              );
            if (viewName === "order-form")
              activeWrapper = document.getElementById(
                "order-form-content-wrapper",
              );
            if (viewName === "customer-profile")
              activeWrapper = document.getElementById(
                "customer-profile-wrapper",
              );

            if (
              activeWrapper &&
              window.innerWidth > 768 &&
              activeWrapper.classList.contains("mobile-sim-mode")
            ) {
              activeWrapper.appendChild(chatbotFab);
              if (chatbotWindow) activeWrapper.appendChild(chatbotWindow);
            } else {
              document.body.appendChild(chatbotFab);
              if (chatbotWindow) document.body.appendChild(chatbotWindow);
            }
          } else {
            chatbotFab.classList.add("hidden");
            chatbotFab.classList.remove("flex");
            if (chatbotWindow) chatbotWindow.classList.add("hidden");
          }
        }

        const mainNavs = [
          "dashboard",
          "marketing",
          "orders",
          "inventory",
          "messages",
          "menu",
          "customers",
          "consulting",
          "kitchen",
          "system",
        ];
        const inactiveClass =
          "border-transparent text-slate-500 hover:border-slate-300 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 dark:hover:border-slate-600 inline-flex items-center px-1 pt-1 border-b-2 text-sm font-medium transition-colors cursor-pointer whitespace-nowrap";
        const activeClass =
          "border-primary text-primary dark:text-emerald-400 dark:border-emerald-400 inline-flex items-center px-1 pt-1 border-b-2 text-sm font-medium cursor-pointer whitespace-nowrap";

        mainNavs.forEach((v) => {
          const navEl = document.getElementById(`nav-${v}`);
          if (navEl) navEl.className = inactiveClass;
        });

        const targetView = document.getElementById(`view-${viewName}`);
        const targetNav = document.getElementById(`nav-${viewName}`);

        const navElement = document.getElementById("main-navbar") || document.querySelector("nav");
        if (navElement) {
          if (viewName === "shipper-app" || isLandingMode || !isAdminViewActive()) {
            navElement.classList.add("hidden");
          } else {
            navElement.classList.remove("hidden");
          }
        }

        const initialLoader = document.getElementById("page-initial-loader");
        if (initialLoader) {
          initialLoader.classList.add("hidden");
          initialLoader.setAttribute("aria-busy", "false");
        }

        if (targetView) targetView.classList.remove("hidden");

        if (targetNav) targetNav.className = activeClass;
        else if (
          (viewName === "order-form" || viewName === "tracking") &&
          !isLandingMode
        )
          document.getElementById("nav-consulting").className = activeClass;

        if (viewName === "system") loadSettings();
        if (window.loadAllBannerImages) window.loadAllBannerImages();
        if (viewName === "inventory") renderInventory();
        if (viewName === "order-form") {
          renderCustomerMenu();
          generateDeliveryTimes();
          if (window.innerWidth <= 768) {
            setOrderFormViewMode("mobile");
          } else {
            setOrderFormViewMode("desktop");
          }
        }
        if (viewName === "tracking") {
          renderCustomerTracking();
          if (window.innerWidth <= 768) {
            setTrackingViewMode("mobile");
          } else {
            setTrackingViewMode("desktop");
          }
        }
        if (viewName === "customer-profile" || viewName === "customer-portal") {
          renderCustomerProfile();
          if (typeof updateNutritionDashboard === "function") {
            updateNutritionDashboard(true);
          }
          if (typeof checkAndShowPwaInstallBanner === "function") {
            checkAndShowPwaInstallBanner();
          }
        } else {
          const pwaBanner = document.getElementById("pwa-install-banner");
          if (pwaBanner) pwaBanner.classList.add("hidden");
        }
        if (viewName === "messages") {
          if (currentMessagesTab === "messages") {
            renderMessagesList();
          } else {
            if (typeof renderAdminReviewsList === "function")
              renderAdminReviewsList();
          }
          const badge1 = document.getElementById("nav-messages-badge");
          if (badge1) {
            badge1.classList.add("hidden");
            badge1.innerText = "0";
          }
          const badge2 = document.getElementById("nav-mobile-messages-badge");
          if (badge2) {
            badge2.classList.add("hidden");
            badge2.innerText = "0";
          }
          document.getElementById("view-messages").classList.add("flex");
        }
        if (viewName === "consulting") {
          document.getElementById("view-consulting").classList.add("flex");
          if (window.innerWidth <= 768) {
            setConsultingViewMode("mobile");
          } else {
            setConsultingViewMode("desktop");
          }
        }
        if (viewName === "orders") {
          switchOrderTab("orders-list");
          const badge = document.getElementById("order-badge");
          if (badge) {
            badge.classList.add("hidden");
            badge.innerText = "0";
          }
          const mobileBadge = document.getElementById("mobile-order-badge");
          if (mobileBadge) {
            mobileBadge.classList.add("hidden");
            mobileBadge.innerText = "0";
          }
        }
        if (viewName === "customers") switchCustomerTab("discount");
        if (viewName === "dashboard") renderDashboard();
        if (viewName === "marketing") renderMarketingDashboard();
        if (viewName === "kitchen") {
          if (typeof initKitchenNavbarMascots === "function") {
            initKitchenNavbarMascots();
          }
        }
        window.scrollTo({ top: 0, behavior: "smooth" });

        // Auto-detect mobile screen to trigger mobile view simulation on load (optional: CSS already handles responsiveness, but if we want toggle logic)
        if (viewName === "consulting" && window.innerWidth <= 768) {
          // we could force mobile view,, but 'hidden lg:flex' hides the buttons, so standard phone width applies.
        } else if (viewName === "consulting") {
          setConsultingViewMode("desktop");
        }
        
        // Luôn luôn khởi tạo lại scroll reveal cho mọi view để tránh lỗi ẩn thành phần
        if (window.initScrollReveal) setTimeout(window.initScrollReveal, 100);
      }

      function updateChatbotParent() {
        const fab = document.getElementById("chatbot-fab");
        const windowEl = document.getElementById("chatbot-window");
        if (!fab) return;

        let activeWrapper = null;
        const consultingView = document.getElementById("view-consulting");
        const orderView = document.getElementById("view-order-form");
        const profileView = document.getElementById("view-customer-profile");
        const trackingView = document.getElementById("view-tracking");

        if (consultingView && !consultingView.classList.contains("hidden"))
          activeWrapper = document.getElementById("consulting-content-wrapper");
        else if (orderView && !orderView.classList.contains("hidden"))
          activeWrapper = document.getElementById("order-form-content-wrapper");
        else if (profileView && !profileView.classList.contains("hidden"))
          activeWrapper = document.getElementById("customer-profile-wrapper");
        else if (trackingView && !trackingView.classList.contains("hidden"))
          activeWrapper = document.getElementById("tracking-content-wrapper");

        if (
          activeWrapper &&
          window.innerWidth > 768 &&
          activeWrapper.classList.contains("mobile-sim-mode")
        ) {
          activeWrapper.appendChild(fab);
          if (windowEl) activeWrapper.appendChild(windowEl);
        } else {
          document.body.appendChild(fab);
          if (windowEl) document.body.appendChild(windowEl);
        }
      }

      function setConsultingViewMode(mode) {
        const wrapper = document.getElementById("consulting-content-wrapper");
        const btnDesktop = document.getElementById("btn-view-desktop");
        const btnMobile = document.getElementById("btn-view-mobile");
        const qrBtn = document.getElementById("btn-share-qr");

        if (!wrapper || !btnDesktop || !btnMobile) return;

        if (mode === "mobile") {
          wrapper.classList.add("mobile-sim-mode");

          btnMobile.className =
            "px-5 py-2 rounded-lg text-sm transition-all flex items-center gap-2 bg-white text-slate-800 shadow-sm font-bold";
          btnDesktop.className =
            "px-5 py-2 rounded-lg text-sm transition-all flex items-center gap-2 font-medium text-slate-500 hover:text-slate-800 hover:bg-white/50";

          if (qrBtn) qrBtn.classList.add("hidden");
        } else {
          wrapper.classList.remove("mobile-sim-mode");

          btnDesktop.className =
            "px-5 py-2 rounded-lg text-sm transition-all flex items-center gap-2 bg-white text-slate-800 shadow-sm font-bold";
          btnMobile.className =
            "px-5 py-2 rounded-lg text-sm transition-all flex items-center gap-2 font-medium text-slate-500 hover:text-slate-800 hover:bg-white/50";

          if (qrBtn) {
            qrBtn.classList.remove("hidden");
            qrBtn.classList.add("lg:flex");
          }
        }
        updateChatbotParent();
      }

