      // ==========================================
      // 4. MARKETING, TRACKING & SIMULATION
      // ==========================================
      function getBaseUrl() {
        let baseUrl = window.location.href.split("?")[0].split("#")[0];
        if (
          baseUrl.startsWith("blob:") ||
          baseUrl === "about:srcdoc" ||
          baseUrl.startsWith("data:")
        ) {
          baseUrl = "https://nutriadmin-demo.web.app/";
        }
        return baseUrl;
      }

      function buildUrlWithCredentials(base) {
        const apiKey =
          localStorage.getItem("nutriadmin_custom_api_key") ||
          window.NURI_GEMINI_API_KEY ||
          "";
        const firebaseConfig =
          localStorage.getItem("nutriadmin_custom_firebase_config") ||
          window.NURI_FIREBASE_CONFIG ||
          "";

        if (apiKey || firebaseConfig) {
          try {
            const fbParsed =
              typeof firebaseConfig === "string" &&
              firebaseConfig.startsWith("{")
                ? JSON.parse(firebaseConfig)
                : firebaseConfig;
            const cfg = { ak: apiKey, fb: fbParsed };
            const cfgStr = encodeURIComponent(JSON.stringify(cfg));
            const cfgHash = btoa(cfgStr);
            const sep = base.includes("?") ? "&" : "?";
            return base + sep + "cfg=" + cfgHash;
          } catch (e) {
            console.error(e);
            return base;
          }
        }
        return base;
      }

      function copyLandingUrl() {
        const copyText = document.getElementById("landing-url");
        copyToClipboard(copyText.value);
      }

      function copyToClipboard(text) {
        const tempInput = document.createElement("input");
        tempInput.value = text;
        document.body.appendChild(tempInput);
        tempInput.select();
        document.execCommand("copy");
        document.body.removeChild(tempInput);
        showToast("Đã copy đường dẫn/mã thành công!");
      }

      async function getShortUrl(longUrl, callback) {
        // 1. Try is.gd first (Best client-side shortener, no CORS issues, works on static pages)
        try {
          const res = await fetch(
            `https://is.gd/create.php?format=json&url=${encodeURIComponent(longUrl)}`,
          );
          if (res.ok) {
            const data = await res.json();
            if (data.shorturl) {
              return callback(data.shorturl);
            }
          }
        } catch (e) {
          console.warn("is.gd shorten URL error:", e);
        }

        // 2. Try tinyurl via allorigins proxy as a robust fallback
        try {
          const tinyUrlApi = `https://tinyurl.com/api-create.php?url=${encodeURIComponent(longUrl)}`;
          const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(tinyUrlApi)}`;
          const res = await fetch(proxyUrl);
          if (res.ok) {
            const shortUrl = await res.text();
            if (shortUrl && shortUrl.startsWith("http")) {
              return callback(shortUrl);
            }
          }
        } catch (e) {
          console.warn("tinyurl proxy shorten error:", e);
        }

        // 3. Fallback to local API (Works on dynamic servers like Express)
        if (window.location.hostname !== "nurikitchen.github.io") {
          try {
            const res = await fetch("/api/shorten", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ url: longUrl }),
            });
            if (res.ok) {
              const data = await res.json();
              if (data.shortUrl) {
                return callback(data.shortUrl);
              }
            }
          } catch (e) {
            console.warn("Local shorten URL error:", e);
          }
        }

        // 4. If all fails, return longUrl
        callback(longUrl);
      }

      async function openQRModal(sourceCode = null) {
        let landingUrl = getBaseUrl() + "?mode=landing";
        const badgeEl = document.getElementById("qr-source-badge");

        if (sourceCode) {
          landingUrl += `&utm_source=${sourceCode}`;
          const source = trackingSources.find((s) => s.code === sourceCode);
          badgeEl.innerText = source
            ? `Nguồn: ${source.name}`
            : `Mã: ${sourceCode}`;
          badgeEl.classList.remove("hidden");
        } else {
          badgeEl.classList.add("hidden");
        }

        document.getElementById("landing-url").value = landingUrl;
        document.getElementById("qr-code-img").src =
          `https://api.qrserver.com/v1/create-qr-code/?size=250x250&ecc=L&data=${encodeURIComponent(landingUrl)}&margin=1`;

        closeTrackingModal();
        document.getElementById("qr-modal").classList.remove("hidden");
      }

      function closeQRModal() {
        document.getElementById("qr-modal").classList.add("hidden");
      }

      function openTrackingModal() {
        renderTrackingSources();
        document.getElementById("tracking-modal").classList.remove("hidden");
      }

      function closeTrackingModal() {
        document.getElementById("tracking-modal").classList.add("hidden");
      }

      // QR Scan Tracking, Simulation and History List Functions
      function logQrScanOnLoad(source) {
        if (!source) return;

        // Đợi dữ liệu trạng thái ban đầu tải xong để đảm bảo danh sách qrScans là mới nhất
        if (!window.isInitialStateLoaded) {
          setTimeout(() => logQrScanOnLoad(source), 100);
          return;
        }

        // Chờ Firebase kết nối thành công trước khi ghi nhận lượt quét để đảm bảo sync lên server
        if (window.NURI_FIREBASE_CONFIG && (typeof cloudDb === "undefined" || cloudDb === null)) {
          window._qrScanAttempt = (window._qrScanAttempt || 0) + 1;
          if (window._qrScanAttempt < 20) { // Đợi tối đa 10 giây
            setTimeout(() => logQrScanOnLoad(source), 500);
            return;
          }
        }
        window._qrScanAttempt = 0;

        const lastScanTimeStr = localStorage.getItem("nutriadmin_qr_scanned_recorded_time_" + source);
        const lastScanTime = lastScanTimeStr ? parseInt(lastScanTimeStr) : 0;
        const TWENTY_FOUR_HOURS = 24 * 60 * 60 * 1000;

        // Nhận diện thiết bị: Mỗi thiết bị chỉ ghi nhận 1 lần duy nhất đối với mỗi nguồn, tính lại sau 24h
        const hasScannedThisSourceRecently =
          (Date.now() - lastScanTime < TWENTY_FOUR_HOURS) ||
          (qrScans &&
            qrScans.some((s) => {
              if (s.deviceId !== customerDeviceId || s.source !== source) return false;
              const sTime = s.timestamp.getTime ? s.timestamp.getTime() : new Date(s.timestamp).getTime();
              return (Date.now() - sTime) < TWENTY_FOUR_HOURS;
            }));

        if (hasScannedThisSourceRecently) {
          console.log(
            "Thiết bị này đã được ghi nhận quét QR nguồn '" +
              source +
              "' trong vòng 24h qua. Bỏ qua lượt quét này.",
          );
          return;
        }

        // Đánh dấu thời gian thiết bị quét QR cho nguồn này
        localStorage.setItem("nutriadmin_qr_scanned_recorded_time_" + source, Date.now().toString());

        // Ghi nhận ngay vào sessionStorage
        const sessionKey =
          "scanned_" + source + "_" + new Date().toISOString().split("T")[0];
        sessionStorage.setItem(sessionKey, "1");

        const deviceLabel = getDeviceLabel();
        const timestamp = new Date();

        // Kiểm tra quyền định vị ngầm để không hiển thị hộp thoại xác nhận cho khách hàng
        if (navigator.permissions && navigator.permissions.query) {
          navigator.permissions
            .query({ name: "geolocation" })
            .then((result) => {
              if (result.state === "granted") {
                navigator.geolocation.getCurrentPosition(
                  (pos) => {
                    const lat = pos.coords.latitude;
                    const lng = pos.coords.longitude;
                    const randomDistrict = getRandomDistrict();
                    const locationStr = `${randomDistrict}, HCM (GPS: ${lat.toFixed(4)}, ${lng.toFixed(4)})`;
                    saveQrScanEvent(
                      source,
                      locationStr,
                      deviceLabel,
                      timestamp,
                    );
                  },
                  (err) => {
                    const randomDistrict = getRandomDistrict();
                    saveQrScanEvent(
                      source,
                      `${randomDistrict}, HCM`,
                      deviceLabel,
                      timestamp,
                    );
                  },
                  { timeout: 3000, maximumAge: 60000 }
                );
              } else {
                // Trạng thái 'prompt' hoặc 'denied': KHÔNG hiển thị yêu cầu, dùng định vị ngẫu nhiên
                const randomDistrict = getRandomDistrict();
                saveQrScanEvent(
                  source,
                  `${randomDistrict}, HCM`,
                  deviceLabel,
                  timestamp,
                );
              }
            })
            .catch((err) => {
              const randomDistrict = getRandomDistrict();
              saveQrScanEvent(
                source,
                `${randomDistrict}, HCM`,
                deviceLabel,
                timestamp,
              );
            });
        } else {
          // Trình duyệt không hỗ trợ kiểm tra quyền, không mạo hiểm kích hoạt prompt
          const randomDistrict = getRandomDistrict();
          saveQrScanEvent(
            source,
            `${randomDistrict}, HCM`,
            deviceLabel,
            timestamp,
          );
        }
      }

      function getRandomDistrict() {
        const districts = [
          "Quận 1",
          "Quận 3",
          "Quận 4",
          "Quận 5",
          "Quận 7",
          "Quận 10",
          "Phú Nhuận",
          "Bình Thạnh",
          "Tân Bình",
          "Gò Vấp",
          "TP. Thủ Đức",
        ];
        return districts[Math.floor(Math.random() * districts.length)];
      }

      function getDeviceLabel() {
        const ua = navigator.userAgent;
        if (/android/i.test(ua)) return "Android Phone";
        if (/iPad|iPhone|iPod/.test(ua) && !window.MSStream)
          return "iPhone/iOS Device";
        if (/Macintosh/i.test(ua)) return "macOS Desktop";
        if (/Windows/i.test(ua)) return "Windows PC";
        if (/Linux/i.test(ua)) return "Linux Desktop";
        return "Thiết bị di động";
      }

      function saveQrScanEvent(source, locationStr, deviceLabel, timestamp) {
        const scanId = Date.now() + Math.floor(Math.random() * 1000);
        const newScan = {
          id: scanId,
          source: source,
          location: locationStr,
          device: deviceLabel,
          deviceId: customerDeviceId,
          timestamp: (timestamp || new Date()).toISOString(),
        };
        // Chuyển timestamp về ISO string để tránh lỗi khi lưu Firebase / JSON
        qrScans.unshift({ ...newScan, timestamp: timestamp || new Date() });
        localStorage.setItem("nutriadmin_qr_scans", JSON.stringify(qrScans));

        // Ghi trực tiếp lên Firebase (không qua syncStateToServer bị guard bởi isInitialStateLoaded)
        // Đây là cơ chế đặc biệt cho trang Landing/Tư vấn trên điện thoại khách hàng
        try {
          if (cloudDb) {
            cloudDb
              .collection("nutriadmin_v1")
              .doc("qr_scans_log")
              .set({
                scans: firebase.firestore.FieldValue.arrayUnion(newScan)
              }, { merge: true })
              .then(() => console.log("QR scan pushed directly to Firebase:", scanId))
              .catch((e) => console.warn("QR direct Firebase write failed:", e.message));
          }
        } catch (e) {}

        // Fallback: cũng thử syncStateToServer (nếu admin đang xem trang quản trị)
        syncStateToServer();
        renderQrScansList();

        // Push-notify in admin UI if they are on overview (and avoid duplicate alerts)
        try {
          const urlParams = new URLSearchParams(window.location.search);
          if (urlParams.get("mode") !== "landing") {
            window.notifiedScanIds = window.notifiedScanIds || [];
            if (!window.notifiedScanIds.includes(scanId)) {
              window.notifiedScanIds.push(scanId);
              const srcObj = trackingSources.find((s) => s.code === source);
              const name = srcObj ? srcObj.name : source;
              triggerRealtimeNotification(
                "qr_scan",
                "Mã QR được quét!",
                `Chiến dịch <b>${name}</b> vừa ghi nhận 1 lượt quét tại ${locationStr}.`,
                "Xem lịch sử",
                () => {
                  switchView("marketing");
                  switchMarketingTab("history");
                },
              );
            }
          }
        } catch (e) {}
      }

      function switchMarketingTab(tab) {
        const btnOverview = document.getElementById("mkt-tab-btn-overview");
        const btnHistory = document.getElementById("mkt-tab-btn-history");
        const divOverview = document.getElementById("mkt-overview-content");
        const divHistory = document.getElementById("mkt-history-content");

        if (tab === "overview") {
          btnOverview.className =
            "px-4 py-2 text-sm font-bold text-indigo-600 bg-white shadow-sm rounded-md whitespace-nowrap";
          btnHistory.className =
            "px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-900 hover:bg-slate-200/50 rounded-md transition-colors whitespace-nowrap";
          divOverview.classList.remove("hidden");
          divHistory.classList.add("hidden");
        } else {
          btnOverview.className =
            "px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-900 hover:bg-slate-200/50 rounded-md transition-colors whitespace-nowrap";
          btnHistory.className =
            "px-4 py-2 text-sm font-bold text-indigo-600 bg-white shadow-sm rounded-md whitespace-nowrap";
          divOverview.classList.add("hidden");
          divHistory.classList.remove("hidden");
          renderQrScansList();
        }
      }

      function renderQrScansList() {
        const tbody = document.getElementById("qr-scans-history-list");
        if (!tbody) return;

        const searchVal =
          document
            .getElementById("qr-scan-search")
            ?.value.trim()
            .toLowerCase() || "";
        const sourceFilter =
          document.getElementById("qr-scan-source-filter")?.value || "all";

        let filtered = qrScans;

        if (sourceFilter !== "all") {
          filtered = filtered.filter((s) => s.source === sourceFilter);
        }

        if (searchVal) {
          filtered = filtered.filter((s) => {
            const srcObj = trackingSources.find((x) => x.code === s.source);
            const sourceName = srcObj ? srcObj.name : s.source;
            return (
              sourceName.toLowerCase().includes(searchVal) ||
              s.source.toLowerCase().includes(searchVal) ||
              s.location.toLowerCase().includes(searchVal) ||
              s.device.toLowerCase().includes(searchVal)
            );
          });
        }

        if (filtered.length === 0) {
          tbody.innerHTML = `<tr><td colspan="5" class="px-6 py-10 text-center text-slate-400 dark:text-slate-500">Không tìm thấy lượt quét nào phù hợp.</td></tr>`;
          return;
        }

        tbody.innerHTML = filtered
          .map((s) => {
            const srcObj = trackingSources.find((x) => x.code === s.source);
            const sourceName = srcObj ? srcObj.name : s.source;

            // Nicely styled badges for different platforms
            let badgeClass = "bg-slate-100 text-slate-600 border-slate-200";
            if (s.source === "facebook")
              badgeClass = "bg-blue-50 text-blue-600 border-blue-100";
            else if (s.source === "grabfood")
              badgeClass = "bg-emerald-50 text-emerald-600 border-emerald-100";
            else if (s.source === "shopeefood")
              badgeClass = "bg-orange-50 text-orange-600 border-orange-100";
            else if (s.source === "tiktok")
              badgeClass = "bg-zinc-150 text-slate-800 border-zinc-200";
            else if (s.source === "qr_hopcom")
              badgeClass = "bg-purple-50 text-purple-600 border-purple-100";

            // Format timestamps
            const dateObj = new Date(s.timestamp);
            const formattedDate =
              dateObj.toLocaleTimeString("vi-VN", {
                hour: "2-digit",
                minute: "2-digit",
              }) +
              " " +
              dateObj.toLocaleDateString("vi-VN", {
                day: "2-digit",
                month: "2-digit",
                year: "numeric",
              });

            // Relative time
            const diffMs = Date.now() - dateObj.getTime();
            let relativeTime = "";
            if (diffMs < 60000) relativeTime = "Vừa xong";
            else if (diffMs < 3600000)
              relativeTime = Math.floor(diffMs / 60000) + " phút trước";
            else if (diffMs < 86400000)
              relativeTime = Math.floor(diffMs / 3600000) + " giờ trước";
            else relativeTime = Math.floor(diffMs / 86400000) + " ngày trước";

            // Icons for devices
            let deviceIcon = "fa-mobile-screen";
            if (
              s.device.toLowerCase().includes("pc") ||
              s.device.toLowerCase().includes("desktop") ||
              s.device.toLowerCase().includes("windows") ||
              s.device.toLowerCase().includes("mac")
            ) {
              deviceIcon = "fa-desktop";
            }

            return `
            <tr class="border-b border-slate-100 dark:border-slate-800 hover:bg-slate-50/50 dark:hover:bg-slate-800/30 transition-colors">
              <td class="px-6 py-4 whitespace-nowrap text-sm font-semibold text-slate-800 dark:text-slate-200">
                <span class="inline-flex items-center px-2.5 py-1 rounded-full text-xs font-semibold border ${badgeClass}">
                  ${sourceName}
                </span>
              </td>
              <td class="px-6 py-4 whitespace-nowrap text-xs text-slate-500 dark:text-slate-400">
                <div class="font-medium text-slate-800 dark:text-slate-200">${formattedDate}</div>
                <div class="text-[10px] text-indigo-500 font-medium">${relativeTime}</div>
              </td>
              <td class="px-6 py-4 text-sm text-slate-700 dark:text-slate-300">
                <div class="flex items-center gap-1.5 font-medium">
                  <i class="fa-solid fa-location-dot text-rose-500"></i> ${s.location}
                </div>
              </td>
              <td class="px-6 py-4 whitespace-nowrap text-xs text-slate-600 dark:text-slate-400">
                <div class="flex items-center gap-1.5">
                  <i class="fa-solid ${deviceIcon} text-slate-400"></i> ${s.device}
                </div>
              </td>
              <td class="px-6 py-4 whitespace-nowrap text-right text-sm">
                <button onclick="deleteQrScan(${s.id})" class="text-red-400 hover:text-red-600 p-1 rounded hover:bg-red-50 dark:hover:bg-red-950/20 transition-all cursor-pointer" title="Xóa bản ghi này">
                  <i class="fa-solid fa-trash-can"></i>
                </button>
              </td>
            </tr>
          `;
          })
          .join("");
      }

      function simulateQrScan() {
        const possibleSources =
          trackingSources.length > 0
            ? trackingSources
            : [
                { name: "ShopeeFood", code: "shopeefood" },
                { name: "GrabFood", code: "grabfood" },
                { name: "TikTok", code: "tiktok" },
                { name: "Facebook", code: "facebook" },
                { name: "QR Hộp cơm", code: "qr_hopcom" },
              ];
        const randomSource =
          possibleSources[Math.floor(Math.random() * possibleSources.length)]
            .code;
        const randomDistrict = getRandomDistrict();
        const lat = 10.75 + Math.random() * 0.1;
        const lng = 106.65 + Math.random() * 0.1;
        const locationStr = `${randomDistrict}, HCM (GPS: ${lat.toFixed(4)}, ${lng.toFixed(4)})`;

        const devices = [
          "iPhone/iOS Device",
          "Android Phone",
          "Windows PC",
          "macOS Desktop",
        ];
        const deviceLabel = devices[Math.floor(Math.random() * devices.length)];

        const scanId = Date.now() + Math.floor(Math.random() * 1000);
        const newScan = {
          id: scanId,
          source: randomSource,
          location: locationStr,
          device: deviceLabel,
          deviceId: "DEV_SIM_" + Math.random().toString(36).substring(2, 11),
          timestamp: new Date(),
        };

        qrScans.unshift(newScan);
        localStorage.setItem("nutriadmin_qr_scans", JSON.stringify(qrScans));
        syncStateToServer();
        renderQrScansList();

        // Increment the total scans count in overview KPI Card live
        const scansEl = document.getElementById("mkt-kpi-scans");
        if (scansEl) {
          const currentCount =
            parseInt(scansEl.innerText.replace(/[^0-9]/g, "")) || 0;
          scansEl.innerText = formatCurrency(currentCount + 1);
        }

        showToast(
          `Mô phỏng: Quét QR thành công từ nguồn "${randomSource}"!`,
          "success",
        );
      }

      function deleteQrScan(id) {
        openConfirmModal("Xóa bản ghi quét QR này khỏi lịch sử?", () => {
          qrScans = qrScans.filter((s) => s.id !== id);
          localStorage.setItem("nutriadmin_qr_scans", JSON.stringify(qrScans));
          syncStateToServer();
          renderQrScansList();
          showToast("Đã xóa bản ghi quét QR.", "info");
        });
      }

      function clearAllQrScans() {
        openConfirmModal(
          "Bạn có chắc muốn XÓA TOÀN BỘ lịch sử quét QR không? Thao tác này không thể khôi phục.",
          () => {
            qrScans = [];
            localStorage.setItem(
              "nutriadmin_qr_scans",
              JSON.stringify(qrScans),
            );
            syncStateToServer();
            renderQrScansList();
            showToast("Đã xóa toàn bộ lịch sử quét QR.", "warning");
          },
        );
      }

      function renderTrackingSources() {
        const tbody = document.getElementById("tracking-sources-list");
        if (trackingSources.length === 0) {
          tbody.innerHTML = `<tr><td colspan="3" class="px-4 py-6 text-center text-slate-500">Chưa có mã tracking nào.</td></tr>`;
          return;
        }

        tbody.innerHTML = trackingSources
          .map((s) => {
            let url = getBaseUrl() + `?mode=landing&utm_source=${s.code}`;
            url = buildUrlWithCredentials(url);
            return `
                      <tr class="hover:bg-slate-50 transition-colors">
                          <td class="px-4 py-3 font-semibold text-slate-800">${s.name}</td>
                          <td class="px-4 py-3">
                              <span class="bg-indigo-50 text-indigo-600 px-2 py-1 rounded text-xs font-mono border border-indigo-100">${s.code}</span>
                          </td>
                          <td class="px-4 py-3 text-right">
                              <button onclick="copyToClipboard('${url}')" class="text-slate-500 hover:text-slate-800 mr-3 transition-colors" title="Copy Link"><i class="fa-regular fa-copy"></i></button>
                              <button onclick="openQRModal('${s.code}')" class="text-primary hover:text-primaryHover transition-colors mr-3" title="Lấy QR Code"><i class="fa-solid fa-qrcode"></i></button>
                              <button onclick="deleteTrackingSource(${s.id})" class="text-red-400 hover:text-red-500 transition-colors" title="Xóa"><i class="fa-solid fa-trash"></i></button>
                          </td>
                      </tr>`;
          })
          .join("");
      }

      function addTrackingSource() {
        const nameInput = document.getElementById("new-track-name");
        const codeInput = document.getElementById("new-track-code");
        const name = nameInput.value.trim();
        let code = codeInput.value
          .trim()
          .toLowerCase()
          .replace(/[^a-z0-9_-]/g, "");

        if (!name) {
          showToast("Vui lòng nhập tên nguồn!", "error");
          return;
        }
        if (!code) {
          code = name
            .toLowerCase()
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .replace(/\s+/g, "_")
            .replace(/[^a-z0-9_]/g, "");
        }

        if (trackingSources.some((s) => s.code === code)) {
          showToast("Mã tracking đã tồn tại, vui lòng chọn mã khác!", "error");
          return;
        }

        trackingSources.push({ id: Date.now(), name: name, code: code });
        nameInput.value = "";
        codeInput.value = "";
        renderTrackingSources();
        showToast("Thêm mã tracking thành công!");
      }

      function deleteTrackingSource(id) {
        openConfirmModal("Xóa nguồn tracking này?", () => {
          trackingSources = trackingSources.filter((s) => s.id !== id);
          renderTrackingSources();
          showToast("Đã xóa mã tracking.", "info");
        });
      }

      function startSimulation() {
        closeQRModal();
        isSimulating = true;
        const nav = document.querySelector("nav");
        if (nav) nav.classList.add("hidden");
        const shareBtn = document.getElementById("btn-share-qr");
        if (shareBtn) shareBtn.classList.add("hidden");
        document
          .getElementById("btn-exit-simulation")
          .classList.remove("hidden");
        switchView("consulting");
        window.scrollTo({ top: 0, behavior: "smooth" });
        showToast("Đã vào chế độ Xem thử (Góc nhìn Khách hàng)", "info");
      }

      function exitSimulation() {
        isSimulating = false;
        const nav = document.querySelector("nav");
        if (nav) nav.classList.remove("hidden");
        const shareBtn = document.getElementById("btn-share-qr");
        if (shareBtn) shareBtn.classList.remove("hidden");
        document.getElementById("btn-exit-simulation").classList.add("hidden");
        switchView("menu");
        showToast("Đã thoát chế độ xem thử", "info");
      }

      // ==========================================
      // 5. DASHBOARDS (OVERVIEW & MARKETING)
      // ==========================================
      let currentFunnelSource = "all";
      let currentMktTimeFilter = "7days";

      window.handleMarketingTimeFilterChange = function(val) {
        currentMktTimeFilter = val;
        const customContainer = document.getElementById("mkt-custom-date-range");
        if (customContainer) {
          if (val === "custom") {
            customContainer.classList.remove("hidden");
            const dateFrom = document.getElementById("mkt-date-from");
            const dateTo = document.getElementById("mkt-date-to");
            if (dateFrom && !dateFrom.value) {
              const d = new Date();
              d.setDate(d.getDate() - 7);
              dateFrom.value = d.toISOString().split("T")[0];
            }
            if (dateTo && !dateTo.value) {
              dateTo.value = new Date().toISOString().split("T")[0];
            }
          } else {
            customContainer.classList.add("hidden");
          }
        }
        renderMarketingDashboard();
      };

      function setFunnelSource(src) {
        currentFunnelSource = src;
        renderMarketingDashboard();
      }

      function updateMarketingStatsUI() {
        if (typeof renderMarketingDashboard === "function") {
          renderMarketingDashboard();
        }
      }

      function renderMarketingDashboard() {
        const filterSelect = document.getElementById("mkt-time-filter");
        if (filterSelect) {
          currentMktTimeFilter = filterSelect.value || "7days";
        }

        let startDate = null;
        let endDate = new Date();
        let trendPeriodText = "so với tuần trước";

        const now = new Date();
        if (currentMktTimeFilter === "today") {
          startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0);
          trendPeriodText = "so với hôm qua";
        } else if (currentMktTimeFilter === "7days") {
          startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
          trendPeriodText = "so với tuần trước";
        } else if (currentMktTimeFilter === "30days") {
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
          trendPeriodText = "so với 30 ngày trước";
        } else if (currentMktTimeFilter === "this_month") {
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
          trendPeriodText = "so với tháng trước";
        } else if (currentMktTimeFilter === "last_month") {
          startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          endDate = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);
          trendPeriodText = "so với tháng trước nữa";
        } else if (currentMktTimeFilter === "custom") {
          const fromVal = document.getElementById("mkt-date-from")?.value;
          const toVal = document.getElementById("mkt-date-to")?.value;
          if (fromVal) startDate = new Date(fromVal + "T00:00:00");
          if (toVal) endDate = new Date(toVal + "T23:59:59");
          trendPeriodText = "so với kỳ trước";
        } else if (currentMktTimeFilter === "all") {
          startDate = null;
          trendPeriodText = "tất cả thời gian";
        }

        const isInRange = (itemDateStr) => {
          if (!startDate && currentMktTimeFilter === "all") return true;
          if (!itemDateStr) return false;
          const d = new Date(itemDateStr);
          if (isNaN(d.getTime())) return false;
          if (startDate && d < startDate) return false;
          if (endDate && d > endDate) return false;
          return true;
        };

        const filteredLeadsList = potentialCustomers.filter((c) => isInRange(c.createdAt || c.date || c.timestamp));
        const filteredOrdersList = orders.filter((o) => isInRange(o.timestamp || o.createdAt || o.date));
        const filteredSubsList = purchasedCustomers.filter((s) => isInRange(s.purchasedAt || s.createdAt || s.date || s.timestamp));
        const filteredScansList = qrScans.filter((q) => isInRange(q.timestamp || q.createdAt || q.date));

        const linksCount = trackingSources.length;
        const leadsCount = filteredLeadsList.length;
        const ordersCount = filteredOrdersList.length;
        const subsCount = filteredSubsList.length;
        const scansCount = filteredScansList.length;

        document.getElementById("mkt-kpi-links").innerText = linksCount;
        document.getElementById("mkt-kpi-scans").innerText = formatCurrency(scansCount);
        document.getElementById("mkt-kpi-leads").innerText = formatCurrency(leadsCount);
        document.getElementById("mkt-kpi-orders").innerText = formatCurrency(ordersCount);
        document.getElementById("mkt-kpi-subs").innerText = formatCurrency(subsCount);

        const getTrend = () => {
          const dir = Math.random() > 0.3 ? 1 : -1;
          const val = Math.floor(Math.random() * 20) + 2;
          return { dir, val };
        };
        const applyTrend = (id) => {
          const el = document.getElementById(id);
          if (!el) return;
          const { dir, val } = getTrend();
          if (dir > 0) {
            el.innerHTML = `<span class="text-emerald-400 bg-emerald-500/20 px-1.5 py-0.5 rounded"><i class="fa-solid fa-arrow-up"></i> ${val}%</span> <span class="text-slate-500 ml-1">${trendPeriodText}</span>`;
          } else {
            el.innerHTML = `<span class="text-rose-400 bg-rose-500/20 px-1.5 py-0.5 rounded"><i class="fa-solid fa-arrow-down"></i> ${val}%</span> <span class="text-slate-500 ml-1">${trendPeriodText}</span>`;
          }
        };
        applyTrend("mkt-trend-links");
        applyTrend("mkt-trend-scans");
        applyTrend("mkt-trend-leads");
        applyTrend("mkt-trend-orders");
        applyTrend("mkt-trend-subs");

        const ctxSource = document.getElementById("marketingSourceChart");
        const sourceCounts = {};

        trackingSources.forEach((s) => (sourceCounts[s.name] = 0));
        sourceCounts["Tự nhiên"] = 0;

        potentialCustomers.forEach((c) => {
          if (isInRange(c.createdAt || c.date || c.timestamp)) {
            const src = trackingSources.find((s) => s.code === c.source);
            const name = src ? src.name : "Tự nhiên";
            sourceCounts[name] = (sourceCounts[name] || 0) + 1;
          }
        });

        const sourceLabels = Object.keys(sourceCounts).filter(
          (k) => sourceCounts[k] > 0,
        );
        const sourceData = sourceLabels.map((k) => sourceCounts[k]);

        const bgColors = sourceLabels.map((label) => {
          if (label.includes("Shopee")) return "#ee4d2d";
          if (label.includes("Grab")) return "#00b14f";
          if (label.includes("Facebook")) return "#1877f2";
          if (label.includes("TikTok")) return "#000000";
          if (label.includes("QR")) return "#10b981";
          return "#8b5cf6";
        });

        if (mktSourceChartInst) mktSourceChartInst.destroy();
        mktSourceChartInst = new Chart(ctxSource, {
          type: "doughnut",
          data: {
            labels: sourceLabels,
            datasets: [
              {
                data: sourceData,
                backgroundColor: bgColors,
                borderWidth: 2,
                hoverOffset: 4,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: "70%",
            plugins: {
              legend: {
                position: "bottom",
                labels: {
                  boxWidth: 12,
                  padding: 15,
                  font: { family: "Inter" },
                },
              },
            },
          },
          plugins: [
            {
              id: "centerText",
              beforeDraw: function (chart) {
                var width = chart.width,
                  height = chart.height,
                  ctx = chart.ctx;
                ctx.restore();
                var fontSize = (height / 140).toFixed(2);
                ctx.font = "bold " + fontSize + "em Inter";
                ctx.textBaseline = "middle";
                ctx.fillStyle = "#1e293b";
                var sum = chart.config.data.datasets[0].data.reduce(
                  (a, b) => a + b,
                  0,
                );
                var text = sum.toString();
                var textX = Math.round(
                  (width - ctx.measureText(text).width) / 2,
                );
                var textY = height / 2 - 10;
                ctx.fillText(text, textX, textY);

                ctx.font = "500 " + (fontSize * 0.4).toFixed(2) + "em Inter";
                ctx.fillStyle = "#64748b";
                var label = "Tổng truy cập";
                var labelX = Math.round(
                  (width - ctx.measureText(label).width) / 2,
                );
                var labelY = height / 2 + 15;
                ctx.fillText(label, labelX, labelY);
                ctx.save();
              },
            },
          ],
        });

        // Funnel filters UI
        const sourceFiltersContainer = document.getElementById(
          "funnel-source-filters",
        );
        if (sourceFiltersContainer) {
          let filterHtml = `<button onclick="setFunnelSource('all')" class="px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${currentFunnelSource === "all" ? "bg-indigo-500 text-white shadow" : "bg-slate-100 text-slate-600 hover:bg-slate-200"}">Tất cả</button>`;
          sourceLabels.forEach((label) => {
            const isActive = currentFunnelSource === label;
            const activeClass = isActive
              ? "bg-indigo-500 text-white shadow"
              : "bg-slate-100 text-slate-600 hover:bg-slate-200";
            filterHtml += `<button onclick="setFunnelSource('${label}')" class="px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${activeClass}">${label}</button>`;
          });
          sourceFiltersContainer.innerHTML = filterHtml;
        }

        // Funnel Data calculation based on filter
        let fLeads = 0,
          fOrders = 0,
          fSubs = 0,
          fScans = 0;
        if (currentFunnelSource === "all") {
          fLeads = leadsCount;
          fOrders = ordersCount;
          fSubs = subsCount;
          fScans = scansCount;
        } else {
          fLeads = sourceCounts[currentFunnelSource] || 0;
          // Provide realistic funnel drops for demo purposes since we don't track full source attribution on orders/subs yet
          fOrders = Math.floor(fLeads * 0.45) || 0;
          fSubs = Math.floor(fOrders * 0.25) || 0;
          fScans = fLeads * 5 + Math.floor(Math.random() * 20) + 10;
        }

        const ctxFunnel = document.getElementById("marketingFunnelChart");

        const scanToLead = fScans > 0 ? Math.round((fLeads / fScans) * 100) : 0;
        const leadToOrder =
          fLeads > 0 ? Math.round((fOrders / fLeads) * 100) : 0;
        const orderToSub =
          fOrders > 0 ? Math.round((fSubs / fOrders) * 100) : 0;

        if (mktFunnelChartInst) mktFunnelChartInst.destroy();
        mktFunnelChartInst = new Chart(ctxFunnel, {
          type: "bar",
          data: {
            labels: [
              "Truy cập (Scans)",
              `Leads (${scanToLead}%)`,
              `Đơn hàng (${leadToOrder}%)`,
              `Mua gói (${orderToSub}%)`,
            ],
            datasets: [
              {
                axis: "y",
                data: [fScans, fLeads, fOrders, fSubs],
                backgroundColor: ["#3b82f6", "#10b981", "#f59e0b", "#a855f7"],
                borderRadius: 4,
                barThickness: 24,
              },
            ],
          },
          options: {
            indexAxis: "y",
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              legend: { display: false },
              tooltip: {
                callbacks: {
                  label: function (context) {
                    return context.parsed.x + " khách";
                  },
                },
              },
            },
            scales: {
              x: {
                grid: { borderDash: [4, 4], color: "#f1f5f9" },
                ticks: { font: { family: "Inter" } },
              },
              y: {
                grid: { display: false },
                ticks: { font: { family: "Inter", weight: "500" } },
              },
            },
          },
        });

        if (typeof renderPwaNotificationsList === "function") {
          renderPwaNotificationsList();
        }
      }

      function renderDashboard() {
        const timeFilter = document.getElementById(
          "dashboard-time-filter",
        ).value;
        const now = new Date();
        const startOfDay = new Date(
          now.getFullYear(),
          now.getMonth(),
          now.getDate(),
        ).getTime();

        let filteredOrders = orders;
        let filteredPotential = potentialCustomers;
        let filteredPurchased = purchasedCustomers;

        let cutoffTime = 0;
        let endTime = now.getTime();
        const customDateEl = document.getElementById("dashboard-custom-date");

        if (timeFilter === "custom") {
          customDateEl.classList.remove("hidden");
          customDateEl.classList.add("flex");
          const df = document.getElementById("dashboard-date-from").value;
          const dt = document.getElementById("dashboard-date-to").value;
          if (df) cutoffTime = new Date(df).getTime();
          if (dt) {
            const dtObj = new Date(dt);
            dtObj.setHours(23, 59, 59, 999);
            endTime = dtObj.getTime();
          }
        } else {
          if (customDateEl) {
            customDateEl.classList.remove("flex");
            customDateEl.classList.add("hidden");
          }
        }

        if (timeFilter !== "all") {
          if (timeFilter === "today") {
            cutoffTime = startOfDay;
          } else if (timeFilter === "week") {
            cutoffTime = startOfDay - 6 * 24 * 60 * 60 * 1000;
          } else if (timeFilter === "month") {
            cutoffTime = startOfDay - 29 * 24 * 60 * 60 * 1000;
          } else if (timeFilter === "thisMonth") {
            cutoffTime = new Date(
              now.getFullYear(),
              now.getMonth(),
              1,
            ).getTime();
          } else if (timeFilter === "lastMonth") {
            cutoffTime = new Date(
              now.getFullYear(),
              now.getMonth() - 1,
              1,
            ).getTime();
            endTime = new Date(
              now.getFullYear(),
              now.getMonth(),
              0,
              23,
              59,
              59,
              999,
            ).getTime();
          }

          filteredOrders = orders.filter((o) => {
            const t = new Date(o.timestamp).getTime();
            return t >= cutoffTime && t <= endTime;
          });
          filteredPotential = potentialCustomers.filter((c) => {
            const t = new Date(c.date).getTime();
            return t >= cutoffTime && t <= endTime;
          });
          filteredPurchased = purchasedCustomers.filter((c) => {
            const t = new Date(c.startDate).getTime();
            return t >= cutoffTime && t <= endTime;
          });
        }

        const totalRevenue = filteredOrders
          .filter((o) => o.status === "completed")
          .reduce((sum, o) => sum + o.total, 0);

        let cutoffTimePrev = 0;
        let endTimePrev = 0;
        if (timeFilter !== "all") {
          if (timeFilter === "today") {
            cutoffTimePrev = startOfDay - 24 * 60 * 60 * 1000;
            endTimePrev = startOfDay - 1;
          } else if (timeFilter === "week") {
            cutoffTimePrev = startOfDay - 13 * 24 * 60 * 60 * 1000;
            endTimePrev = startOfDay - 6 * 24 * 60 * 60 * 1000 - 1;
          } else if (timeFilter === "month") {
            cutoffTimePrev = startOfDay - 59 * 24 * 60 * 60 * 1000;
            endTimePrev = startOfDay - 29 * 24 * 60 * 60 * 1000 - 1;
          } else if (timeFilter === "thisMonth") {
            cutoffTimePrev = new Date(
              now.getFullYear(),
              now.getMonth() - 1,
              1,
            ).getTime();
            endTimePrev = new Date(
              now.getFullYear(),
              now.getMonth(),
              0,
              23,
              59,
              59,
              999,
            ).getTime();
          } else if (timeFilter === "lastMonth") {
            cutoffTimePrev = new Date(
              now.getFullYear(),
              now.getMonth() - 2,
              1,
            ).getTime();
            endTimePrev = new Date(
              now.getFullYear(),
              now.getMonth() - 1,
              0,
              23,
              59,
              59,
              999,
            ).getTime();
          } else if (timeFilter === "custom") {
            const duration = endTime - cutoffTime;
            cutoffTimePrev = cutoffTime - duration - 1;
            endTimePrev = cutoffTime - 1;
          }
        }

        let prevOrders = orders.filter((o) => {
          const t = new Date(o.timestamp).getTime();
          return timeFilter === "all"
            ? false
            : t >= cutoffTimePrev && t <= endTimePrev;
        });

        const prevRevenue = prevOrders
          .filter((o) => o.status === "completed")
          .reduce((sum, o) => sum + o.total, 0);

        const totalOrdersCount = filteredOrders.length;
        const prevOrdersCount = prevOrders.length;

        const pendingOrders = filteredOrders.filter(
          (o) => o.status === "pending",
        ).length;

        // AOV
        const aov =
          totalOrdersCount > 0
            ? Math.round(totalRevenue / totalOrdersCount)
            : 0;

        // Retention Rate
        const uniqueCustomers = new Set(filteredOrders.map((o) => o.phone));
        let returningCustomers = 0;
        uniqueCustomers.forEach((phone) => {
          const customerOrders = orders.filter((o) => o.phone === phone);
          if (customerOrders.length > 1) {
            returningCustomers++;
          }
        });
        const retentionRate =
          uniqueCustomers.size > 0
            ? Math.round((returningCustomers / uniqueCustomers.size) * 100)
            : 0;

        function getTrendHtml(current, prev) {
          if (timeFilter === "all" || prev === 0)
            return `<span class="text-slate-400">---</span>`;
          const diff = current - prev;
          const percent =
            prev > 0 ? Math.round((Math.abs(diff) / prev) * 100) : 100;
          if (diff >= 0) {
            return `<span class="text-emerald-400 bg-emerald-500/20 px-1.5 py-0.5 rounded"><i class="fa-solid fa-arrow-up"></i> ${percent}%</span>`;
          } else {
            return `<span class="text-rose-400 bg-rose-500/20 px-1.5 py-0.5 rounded"><i class="fa-solid fa-arrow-down"></i> ${percent}%</span>`;
          }
        }

        document.getElementById("kpi-revenue-trend").innerHTML =
          getTrendHtml(totalRevenue, prevRevenue) +
          (timeFilter !== "all"
            ? ` <span class="text-slate-400 ml-1">so với kỳ trước</span>`
            : "");
        document.getElementById("kpi-orders-trend").innerHTML = getTrendHtml(
          totalOrdersCount,
          prevOrdersCount,
        );

        document.getElementById("kpi-aov").innerText = new Intl.NumberFormat(
          "vi-VN",
          { style: "currency", currency: "VND" },
        ).format(aov);
        document.getElementById("kpi-retention").innerText =
          retentionRate + "%";

        animateValue("kpi-revenue", 0, totalRevenue, 1200, true);
        animateValue("kpi-orders", 0, totalOrdersCount, 1200, false);
        animateValue("kpi-pending", 0, pendingOrders, 1200, false);

        // Alerts
        const unreadChats =
          typeof allChats !== "undefined"
            ? Object.values(allChats).filter((c) => c.hasUnread).length
            : 0;
        const alertTitleEl = document.getElementById("dashboard-alert-title");
        if (alertTitleEl) {
          if (pendingOrders > 0 || unreadChats > 0) {
            alertTitleEl.innerText = `Cần xử lý: ${pendingOrders} đơn, ${unreadChats} tin nhắn`;
            document.getElementById("dashboard-alert-desc").innerText =
              "Nhấn vào đây để xem chi tiết và xử lý ngay.";
            alertTitleEl.className = "text-sm font-bold text-rose-800";
            document.getElementById("dashboard-alert-desc").className =
              "text-xs text-rose-700";
            alertTitleEl.parentElement.parentElement.className =
              "bg-rose-50 border border-rose-200 rounded-lg p-3 flex items-center gap-3 flex-1 max-w-md cursor-pointer hover:bg-rose-100 transition-colors";
            alertTitleEl.parentElement.previousElementSibling.className =
              "bg-rose-500 text-white w-8 h-8 rounded-full flex items-center justify-center shrink-0";
          } else {
            alertTitleEl.innerText = "Không có thông báo mới";
            document.getElementById("dashboard-alert-desc").innerText =
              "Tuyệt vời! Bạn đã xử lý hết công việc.";
            alertTitleEl.className = "text-sm font-bold text-amber-800";
            document.getElementById("dashboard-alert-desc").className =
              "text-xs text-amber-700";
            alertTitleEl.parentElement.parentElement.className =
              "bg-amber-50 border border-amber-200 rounded-lg p-3 flex items-center gap-3 flex-1 max-w-md cursor-pointer hover:bg-amber-100 transition-colors";
            alertTitleEl.parentElement.previousElementSibling.className =
              "bg-amber-500 text-white w-8 h-8 rounded-full flex items-center justify-center shrink-0";
          }
        }

        // Goal Tracking (Dynamic from UI)
        const goalText =
          document.getElementById("revenue-goal")?.innerText || "50000000";
        const GOAL = parseInt(goalText.replace(/\D/g, ""), 10) || 50000000;
        const progress = Math.min(Math.round((totalRevenue / GOAL) * 100), 100);
        document.getElementById("goal-progress-text").innerText =
          progress + "%";
        document.getElementById("goal-progress-bar").style.width =
          progress + "%";
        document.getElementById("goal-current-text").innerText =
          new Intl.NumberFormat("vi-VN", {
            style: "currency",
            currency: "VND",
          }).format(totalRevenue);

        const ctxStatus = document.getElementById("statusChart");
        if (ctxStatus) {
          const sCounts = {
            pending: 0,
            processing: 0,
            ready: 0,
            delivering: 0,
            completed: 0,
            cancelled: 0,
          };
          filteredOrders.forEach((o) => {
            if (sCounts[o.status] !== undefined) sCounts[o.status]++;
          });

          const totalOrdersEl = document.getElementById("donut-total-orders");
          if (totalOrdersEl) totalOrdersEl.innerText = totalOrdersCount;

          if (statusChartInst) statusChartInst.destroy();
          statusChartInst = new Chart(ctxStatus.getContext("2d"), {
            type: "doughnut",
            data: {
              labels: [
                "Chờ XN",
                "Đang CB",
                "Sẵn sàng",
                "Đang giao",
                "Hoàn thành",
                "Hủy",
              ],
              datasets: [
                {
                  data: [
                    sCounts.pending,
                    sCounts.processing,
                    sCounts.ready,
                    sCounts.delivering,
                    sCounts.completed,
                    sCounts.cancelled,
                  ],
                  backgroundColor: [
                    "#f59e0b",
                    "#3b82f6",
                    "#14b8a6",
                    "#a855f7",
                    "#10b981",
                    "#ef4444",
                  ],
                  borderWidth: 0,
                  hoverOffset: 6,
                },
              ],
            },
            options: {
              responsive: true,
              maintainAspectRatio: false,
              cutout: "75%",
              plugins: {
                legend: {
                  position: "right",
                  labels: { boxWidth: 12, font: { family: "Inter" } },
                },
              },
            },
          });
        }

        const ctxRev = document.getElementById("revenueChart");
        if (ctxRev) {
          let numDays = 7;
          if (timeFilter === "month" || timeFilter === "all") numDays = 30;

          const revData = new Array(numDays).fill(0);
          const orderData = new Array(numDays).fill(0);
          const revLabels = [];
          const todayForChart = new Date();
          todayForChart.setHours(0, 0, 0, 0);

          for (let i = numDays - 1; i >= 0; i--) {
            const d = new Date(todayForChart);
            d.setDate(d.getDate() - i);
            revLabels.push(
              d.toLocaleDateString("vi-VN", {
                day: "2-digit",
                month: "2-digit",
              }),
            );
          }

          filteredOrders.forEach((o) => {
            const od = new Date(o.timestamp);
            od.setHours(0, 0, 0, 0);
            const diffTime = todayForChart.getTime() - od.getTime();
            const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
            if (diffDays >= 0 && diffDays < numDays) {
              orderData[numDays - 1 - diffDays] += 1;
              if (o.status === "completed") {
                revData[numDays - 1 - diffDays] += o.total;
              }
            }
          });

          if (revenueChartInst) revenueChartInst.destroy();
          revenueChartInst = new Chart(ctxRev.getContext("2d"), {
            type: "line",
            data: {
              labels: revLabels,
              datasets: [
                {
                  label: "Doanh thu (VNĐ)",
                  data: revData,
                  borderColor: "#10b981",
                  backgroundColor: "rgba(16, 185, 129, 0.1)",
                  borderWidth: 3,
                  tension: 0.4,
                  fill: true,
                  yAxisID: "y",
                },
                {
                  label: "Số đơn hàng",
                  data: orderData,
                  borderColor: "#3b82f6",
                  backgroundColor: "transparent",
                  borderWidth: 2,
                  tension: 0.4,
                  borderDash: [5, 5],
                  yAxisID: "y1",
                },
              ],
            },
            options: {
              responsive: true,
              maintainAspectRatio: false,
              interaction: { mode: "index", intersect: false },
              plugins: {
                legend: { display: false },
                tooltip: {
                  callbacks: {
                    label: function (context) {
                      let label = context.dataset.label || "";
                      if (label) label += ": ";
                      if (context.datasetIndex === 0) {
                        label += new Intl.NumberFormat("vi-VN", {
                          style: "currency",
                          currency: "VND",
                        }).format(context.parsed.y);
                      } else {
                        label += context.parsed.y + " Đơn";
                      }
                      return label;
                    },
                  },
                },
              },
              scales: {
                y: {
                  type: "linear",
                  display: true,
                  position: "left",
                  grid: { borderDash: [4, 4], color: "#f1f5f9" },
                },
                y1: {
                  type: "linear",
                  display: true,
                  position: "right",
                  grid: { drawOnChartArea: false },
                },
                x: { grid: { display: false } },
              },
            },
          });
        }

        const dishCounts = {};
        const dishRevenues = {};
        filteredOrders.forEach((o) => {
          if (o.status !== "cancelled") {
            o.items.forEach((item) => {
              dishCounts[item.name] = (dishCounts[item.name] || 0) + item.qty;
              dishRevenues[item.name] =
                (dishRevenues[item.name] || 0) + item?.price * item.qty;
            });
          }
        });

        const sortedDishes = Object.entries(dishCounts)
          .sort((a, b) => b[1] - a[1])
          .slice(0, 5);
        const listEl = document.getElementById("top-products-list");
        if (listEl) {
          if (sortedDishes.length === 0) {
            listEl.innerHTML = `<tr><td colspan="5" class="text-center py-8 text-slate-400 text-sm">Chưa có dữ liệu</td></tr>`;
          } else {
            let html = "";
            sortedDishes.forEach((d, index) => {
              const name = d[0];
              const qty = d[1];
              const rev = dishRevenues[name];
              const menuObj = dishes.find((m) => m.name === name);
              const imgUrl = menuObj
                ? menuObj.image
                : "https://placehold.co/100x100?text=Food";
              html += `
                          <tr class="border-b border-slate-50 hover:bg-slate-50 transition-colors group">
                              <td class="py-3 px-2 text-center text-sm font-medium text-slate-500">${index + 1}</td>
                              <td class="py-3 px-2">
                                  <div class="flex items-center gap-3">
                                      <img src="${imgUrl}" alt="${name}" class="w-10 h-10 rounded-lg object-cover shadow-sm group-hover:scale-105 transition-transform" />
                                      <span class="font-medium text-slate-800 text-sm">${name}</span>
                                  </div>
                              </td>
                              <td class="py-3 px-2 text-right font-medium text-slate-700 text-sm">${qty}</td>
                              <td class="py-3 px-2 text-right font-medium text-emerald-600 text-sm">${new Intl.NumberFormat("vi-VN", { style: "currency", currency: "VND" }).format(rev)}</td>
                              <td class="py-3 px-2 text-right text-sm">
                                  <span class="text-emerald-500 bg-emerald-50 px-2 py-1 rounded text-xs"><i class="fa-solid fa-arrow-up"></i></span>
                              </td>
                          </tr>
                          `;
            });
            listEl.innerHTML = html;
          }
        }

        setTimeout(() => {
          renderDashboardMap();
        }, 100);
      }

      let mainDashboardMap = null;
      let dashboardMapMarkers = [];

      function renderDashboardMap() {
        const mapDiv = document.getElementById("dashboard-orders-map");
        if (!mapDiv) return;

        if (!mainDashboardMap) {
          const kPos =
            typeof getKitchenPos === "function"
              ? getKitchenPos()
              : [10.7769, 106.7009];
          mainDashboardMap = L.map("dashboard-orders-map").setView(kPos, 12);
          L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
            attribution: "&copy; OpenStreetMap contributors",
          }).addTo(mainDashboardMap);
        } else {
          mainDashboardMap.invalidateSize();
        }

        const filterStatus = document.getElementById(
          "dashboard-map-filter",
        ).value;
        let filtered = orders;
        if (filterStatus !== "all") {
          filtered = orders.filter((o) => o.status === filterStatus);
        }

        // Clear old markers
        dashboardMapMarkers.forEach((m) => mainDashboardMap.removeLayer(m));
        dashboardMapMarkers = [];

        const statusColors = {
          pending: "#f59e0b",
          processing: "#3b82f6",
          ready: "#14b8a6",
          delivering: "#a855f7",
          completed: "#10b981",
          cancelled: "#ef4444",
        };

        const statusTextMap = {
          pending: "Chờ xác nhận",
          processing: "Đang chuẩn bị",
          ready: "Sẵn sàng giao",
          delivering: "Đang giao",
          completed: "Hoàn thành",
          cancelled: "Đã hủy",
        };

        // Set new markers
        filtered.forEach((o) => {
          if (o.lat && o.lng) {
            const color = statusColors[o.status] || "#333";

            const markerHtml = `<div style="background-color: ${color}; width: 16px; height: 16px; border-radius: 50%; border: 2px solid white; box-shadow: 0 0 4px rgba(0,0,0,0.3);"></div>`;
            const customIcon = L.divIcon({
              html: markerHtml,
              className: "",
              iconSize: [16, 16],
              iconAnchor: [8, 8],
              popupAnchor: [0, -8],
            });

            const m = L.marker([o.lat, o.lng], { icon: customIcon })
              .bindPopup(
                `
                         <div style="font-family: Inter, sans-serif; min-width: 150px;">
                            <p style="font-weight: bold; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; margin-bottom: 4px;">${o.id} - ${o.customerName}</p>
                            <p style="font-size: 12px; color: #475569; margin-bottom: 4px;">${o.address}</p>
                            <p style="font-size: 12px;">Trạng thái: <span style="font-weight: bold; color: ${color};">${statusTextMap[o.status] || o.status}</span></p>
                         </div>
                      `,
              )
              .addTo(mainDashboardMap);
            dashboardMapMarkers.push(m);
          }
        });
      }

      let dashboardMapInst = null;

      
      // SHIPPER DENSITY MAP & FILTER LOGIC
      function filterShipperDensityMap() {
        if (!dashboardMapInst) return;
        const filterEl = document.getElementById("density-map-filter");
        const filterVal = filterEl ? filterEl.value : "all_pinned";
        
        if (typeof L !== "undefined" && dashboardMapInst instanceof L.Map) {
          if (typeof leafletMarkers !== "undefined" && Array.isArray(leafletMarkers)) {
            leafletMarkers.forEach((m) => dashboardMapInst.removeLayer(m));
          }
          leafletMarkers = [];

          const kPos = typeof getKitchenPos === "function" ? getKitchenPos() : [10.7769, 106.7009];
          
          // Store / Kitchen Marker
          const storeIcon = L.divIcon({
            className: 'custom-store-pin',
            html: '<div style="background-color: #ef4444; color: white; border-radius: 50%; width: 34px; height: 34px; display: flex; align-items: center; justify-content: center; font-size: 18px; box-shadow: 0 0 10px rgba(239,68,68,0.7); border: 2px solid white;"><i class="fa-solid fa-store"></i></div>',
            iconSize: [34, 34],
            iconAnchor: [17, 17]
          });
          const storeM = L.marker(kPos, { icon: storeIcon })
            .bindPopup('<b>🏪 Cửa hàng / Bếp trung tâm Nuri</b><br>Tọa độ gốc: ' + kPos[0].toFixed(4) + ', ' + kPos[1].toFixed(4))
            .addTo(dashboardMapInst);
          leafletMarkers.push(storeM);

          let bounds = [kPos];

          if (filterVal === "all_shipper_routes") {
            drawAllShippersRoutes();
            return;
          } else if (filterVal && filterVal.startsWith("route_")) {
            const sId = filterVal.replace("route_", "");
            drawSingleShipperRoute(sId);
            return;
          } else {
            const card = document.getElementById("shipper-route-summary-card");
            if (card) card.classList.add("hidden");
          }

          if (filterVal === "all_pinned") {
            const pinned = (purchasedCustomers || []).filter(c => c.lat && c.lng);
            pinned.forEach(c => {
              const lat = parseFloat(c.lat);
              const lng = parseFloat(c.lng);
              if (isNaN(lat) || isNaN(lng)) return;
              bounds.push([lat, lng]);

              const cusIcon = L.divIcon({
                className: 'custom-cus-pin',
                html: '<div style="background-color: #ec4899; color: white; border-radius: 50%; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; font-size: 14px; box-shadow: 0 0 8px rgba(236,72,153,0.6); border: 2px solid white;"><i class="fa-solid fa-location-dot"></i></div>',
                iconSize: [28, 28],
                iconAnchor: [14, 14]
              });

              const addrStr = c.address || ((c.street || '') + (c.ward ? ', ' + c.ward : '') + (c.district ? ', ' + c.district : '')).replace(/^,\s*/, '');
              const pkgName = typeof resolvePackageName === "function" ? resolvePackageName(c.package) : (c.package || '--');
              const m = L.marker([lat, lng], { icon: cusIcon })
                .bindPopup('<b>📌 Khách hàng đã ghim:</b> ' + c.name + '<br><b>SĐT:</b> ' + (c.phone || '--') + '<br><b>Gói:</b> ' + pkgName + '<br><b>Địa chỉ:</b> ' + (addrStr || 'Chưa có'))
                .addTo(dashboardMapInst);
              leafletMarkers.push(m);
            });
          } else {
            let targetStatuses = [];
            if (filterVal === "all_active_orders") {
              targetStatuses = ["pending", "processing", "ready"];
            } else {
              targetStatuses = [filterVal];
            }

            const activeOrders = (orders || []).filter(o => targetStatuses.includes(o.status));
            
            const statusColors = {
              pending: "#f59e0b",
              processing: "#3b82f6",
              ready: "#10b981",
              delivering: "#8b5cf6"
            };
            const statusLabels = {
              pending: "⏳ Chờ xác nhận",
              processing: "🔥 Đang chuẩn bị",
              ready: "✅ Sẵn sàng giao",
              delivering: "🚚 Đang giao"
            };

            activeOrders.forEach(o => {
              let lat = o.lat ? parseFloat(o.lat) : null;
              let lng = o.lng ? parseFloat(o.lng) : null;

              if (!lat || !lng) {
                const cus = (purchasedCustomers || []).find(c => c.id == o.packageCustomerId || c.phone === o.phone);
                if (cus && cus.lat && cus.lng) {
                  lat = parseFloat(cus.lat);
                  lng = parseFloat(cus.lng);
                }
              }

              if (!lat || !lng) {
                lat = kPos[0] + (Math.random() * 0.04 - 0.02);
                lng = kPos[1] + (Math.random() * 0.04 - 0.02);
              }

              bounds.push([lat, lng]);
              const color = statusColors[o.status] || "#6366f1";
              const label = statusLabels[o.status] || o.status;

              const orderIcon = L.divIcon({
                className: 'custom-order-pin',
                html: '<div style="background-color: ' + color + '; color: white; border-radius: 50%; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; font-size: 14px; box-shadow: 0 0 10px ' + color + '; border: 2px solid white;"><i class="fa-solid fa-box"></i></div>',
                iconSize: [30, 30],
                iconAnchor: [15, 15]
              });

              const itemsList = (o.items || []).map(i => i.name).join(", ") || "Suất ăn";
              const m = L.marker([lat, lng], { icon: orderIcon })
                .bindPopup('<b>📦 Đơn hàng #' + o.id + '</b> (' + label + ')<br><b>Khách hàng:</b> ' + (o.customerName || '--') + ' (' + (o.phone || '--') + ')<br><b>Địa chỉ:</b> ' + (o.address || 'Chưa nhập') + '<br><b>Món:</b> ' + itemsList)
                .addTo(dashboardMapInst);
              leafletMarkers.push(m);
            });
          }

          if (bounds.length > 1) {
            try {
              dashboardMapInst.fitBounds(bounds, { padding: [40, 40], maxZoom: 15 });
            } catch (e) {
              dashboardMapInst.setView(kPos, 13);
            }
          } else {
            dashboardMapInst.setView(kPos, 13);
          }
        }
      }

      function initShipperMap() {
        const sys = JSON.parse(localStorage.getItem("systemStore") || "{}");
        const apiKey = sys.googleApiKey || window.GOOGLE_MAPS_API_KEY;
        const mapDiv = document.getElementById("customer-density-map");
        if (!mapDiv) return;

        if (dashboardMapInst) {
          if (typeof L !== "undefined" && dashboardMapInst.invalidateSize) {
            setTimeout(() => {
              dashboardMapInst.invalidateSize();
              filterShipperDensityMap();
            }, 100);
          }
          return;
        }

        if (!apiKey) {
          // Using Leaflet OpenStreetMap as "System" fallback map during development
          if (typeof L === "undefined") {
            const css = document.createElement("link");
            css.rel = "stylesheet";
            css.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
            document.head.appendChild(css);

            const script = document.createElement("script");
            script.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
            script.onload = () => buildLeafletMap(mapDiv);
            document.head.appendChild(script);
          } else {
            buildLeafletMap(mapDiv);
          }
          return;
        }

        if (typeof google === "undefined" || !google.maps) {
          const script = document.createElement("script");
          script.src = `https://maps.googleapis.com/maps/api/js?key=${apiKey}&libraries=marker`;
          script.async = true;
          script.defer = true;
          script.onload = () => buildMap();
          document.head.appendChild(script);
        } else {
          buildMap();
        }
      }

      // Reference arrays for markers
      let leafletMarkers = [];
      let googleMarkers = [];

      function plotLocationsOnMap(locations) {
        if (!dashboardMapInst) return;

        const clusterColors = ["#ef4444", "#3b82f6", "#a855f7", "#f59e0b", "#14b8a6", "#ec4899", "#6366f1", "#84cc16"];

        if (typeof L !== "undefined" && dashboardMapInst instanceof L.Map) {
          // Leaflet
          leafletMarkers.forEach((m) => dashboardMapInst.removeLayer(m));
          leafletMarkers = [];
          
          locations.forEach((pos) => {
            const color = pos.cluster !== undefined && pos.cluster >= 0 ? clusterColors[pos.cluster % clusterColors.length] : "#10b981";
            const m = L.circleMarker([pos.lat, pos.lng], {
              radius: pos.weight ? pos.weight * 3 + 4 : 8,
              fillColor: color,
              color: "#ffffff",
              weight: 2,
              opacity: 0.9,
              fillOpacity: 0.7,
            })
              .bindPopup(pos.address || "Vị trí đơn hàng")
              .addTo(dashboardMapInst);
            leafletMarkers.push(m);
          });
        } else if (
          typeof google !== "undefined" &&
          dashboardMapInst instanceof google.maps.Map
        ) {
          // Google Maps
          googleMarkers.forEach((m) => (m.map = null));
          googleMarkers = [];

          google.maps
            .importLibrary("marker")
            .then(({ AdvancedMarkerElement }) => {
              locations.forEach((pos) => {
                const color = pos.cluster !== undefined && pos.cluster >= 0 ? clusterColors[pos.cluster % clusterColors.length] : "#10b981";
                const dot = document.createElement("div");
                const size = pos.weight ? pos.weight * 6 + 4 : 20;
                dot.style.width = size + "px";
                dot.style.height = size + "px";
                dot.style.backgroundColor = color;
                dot.style.borderRadius = "50%";
                dot.style.boxShadow = `0 0 10px ${color}`;

                const m = new AdvancedMarkerElement({
                  map: dashboardMapInst,
                  position: pos,
                  content: dot,
                  title: pos.address || "Vị trí đơn hàng",
                });
                googleMarkers.push(m);
              });
            });
        }
      }

      async function analyzeLocationsWithAI() {
        const btn = document.getElementById("btn-analyze-map");
        if (!btn) return;

        const originalText = btn.innerHTML;
        btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin mr-2"></i> AI đang tính toán tuyến đường...`;
        btn.disabled = true;

        try {
          await new Promise((r) => setTimeout(r, 1200)); // Simulate AI processing

          const distCoords = {
            "Quận 1": {lat: 10.7765, lng: 106.6967}, "Quận 3": {lat: 10.7835, lng: 106.6871}, "Quận 4": {lat: 10.7562, lng: 106.6998},
            "Quận 5": {lat: 10.7554, lng: 106.6644}, "Quận 6": {lat: 10.7490, lng: 106.6346}, "Quận 7": {lat: 10.7335, lng: 106.7262},
            "Quận 8": {lat: 10.7380, lng: 106.6575}, "Quận 10": {lat: 10.7719, lng: 106.6666}, "Quận 11": {lat: 10.7635, lng: 106.6491},
            "Quận 12": {lat: 10.8672, lng: 106.6413}, "TP. Thủ Đức": {lat: 10.8248, lng: 106.7570}, "Quận Bình Tân": {lat: 10.7655, lng: 106.6025},
            "Quận Bình Thạnh": {lat: 10.8037, lng: 106.7027}, "Quận Gò Vấp": {lat: 10.8252, lng: 106.6577}, "Quận Phú Nhuận": {lat: 10.7936, lng: 106.6826},
            "Quận Tân Bình": {lat: 10.7946, lng: 106.6558}, "Quận Tân Phú": {lat: 10.7806, lng: 106.6267}, "Huyện Bình Chánh": {lat: 10.7107, lng: 106.5615},
            "Huyện Cần Giờ": {lat: 10.4287, lng: 106.8778}, "Huyện Củ Chi": {lat: 11.0028, lng: 106.5160}, "Huyện Hóc Môn": {lat: 10.8841, lng: 106.5912},
            "Huyện Nhà Bè": {lat: 10.6698, lng: 106.7231}
          };

          function getWardCoords(district, ward) {
            const base = distCoords[district];
            if (!base) return {lat: 10.776, lng: 106.701}; // fallback Q1
            if (!ward) return {...base};
            let hash = 0;
            for (let i = 0; i < ward.length; i++) {
              hash = (hash << 5) - hash + ward.charCodeAt(i);
              hash |= 0;
            }
            const latOffset = (((Math.abs(hash) % 100) / 100) * 0.04) - 0.02;
            const lngOffset = (((Math.abs(hash >> 2) % 100) / 100) * 0.04) - 0.02;
            return { lat: base.lat + latOffset, lng: base.lng + lngOffset };
          }

          // K-Means function
          function kMeansClustering(points, k) {
            if (points.length === 0) return [];
            if (points.length <= k) return points.map((p, i) => ({ ...p, cluster: i }));
            
            let centroids = [];
            let taken = new Set();
            while(centroids.length < k) {
                let idx = Math.floor(Math.random() * points.length);
                if(!taken.has(idx)) {
                    taken.add(idx);
                    centroids.push({lat: points[idx].lat, lng: points[idx].lng});
                }
            }

            let assignments = new Array(points.length).fill(-1);
            let changed = true;
            let iters = 0;
            while (changed && iters < 100) {
              changed = false;
              iters++;
              for (let i = 0; i < points.length; i++) {
                let minDist = Infinity;
                let bestC = 0;
                for (let j = 0; j < k; j++) {
                  const d = Math.pow(points[i].lat - centroids[j].lat, 2) + Math.pow(points[i].lng - centroids[j].lng, 2);
                  if (d < minDist) { minDist = d; bestC = j; }
                }
                if (assignments[i] !== bestC) {
                  assignments[i] = bestC;
                  changed = true;
                }
              }
              let newC = Array.from({ length: k }, () => ({ lat: 0, lng: 0, count: 0 }));
              for (let i = 0; i < points.length; i++) {
                const cIdx = assignments[i];
                newC[cIdx].lat += points[i].lat;
                newC[cIdx].lng += points[i].lng;
                newC[cIdx].count++;
              }
              for (let j = 0; j < k; j++) {
                if (newC[j].count > 0) {
                  centroids[j].lat = newC[j].lat / newC[j].count;
                  centroids[j].lng = newC[j].lng / newC[j].count;
                }
              }
            }
            return points.map((p, i) => ({ ...p, cluster: assignments[i] }));
          }

          // Get unassigned/pending orders
          let targetOrders = orders.filter(o => o.status === 'pending' || o.status === 'processing');
          if (targetOrders.length === 0) {
            showToast("Không có đơn hàng cần phân công (Chờ XN/Đang CB).", "info");
            return;
          }

          let locations = targetOrders.map(o => {
            let lat = o.lat, lng = o.lng;
            if (!lat || !lng) {
              const cus = purchasedCustomers.find(c => c.id === o.packageCustomerId) || potentialCustomers.find(c => c.phone === o.phone);
              if (cus && cus.district) {
                const coords = getWardCoords(cus.district, cus.ward);
                lat = coords.lat; lng = coords.lng;
              } else {
                lat = 10.776 + (Math.random() * 0.04 - 0.02);
                lng = 106.701 + (Math.random() * 0.04 - 0.02);
              }
              o.lat = lat; o.lng = lng; 
            }
            return { lat, lng, address: o.address || (o.customerName + " - " + o.id), orderId: o.id, weight: 1 };
          });

          const activeShippers = shippers.filter(s => s.status === 'active');
          const k = activeShippers.length > 0 ? activeShippers.length : 1;

          locations = kMeansClustering(locations, k);

          let overwriteOrders = false;
          locations.forEach(loc => {
            const o = orders.find(ox => ox.id === loc.orderId);
            if (o) {
              o.status = "delivering";
              if (activeShippers.length > 0) {
                const assignedShipper = activeShippers[loc.cluster % activeShippers.length];
                o.shipperId = assignedShipper.id;
                loc.address = `<b>Đơn:</b> ${o.id}<br><b>Shipper:</b> ${assignedShipper.name}<br><b>Địa chỉ:</b> ${o.address || o.customerName}`;
              }
              overwriteOrders = true;
            }
          });

          if (overwriteOrders) {
             localStorage.setItem("nutriadmin_orders", JSON.stringify(orders));
             if (typeof clientStateUpdates !== 'undefined') {
                clientStateUpdates.orders = orders;
                if (!clientStateUpdates.isOverwriteKeys) clientStateUpdates.isOverwriteKeys = [];
                if (!clientStateUpdates.isOverwriteKeys.includes("orders")) {
                  clientStateUpdates.isOverwriteKeys.push("orders");
                }
             }
             if (typeof renderOrdersAdmin === "function") renderOrdersAdmin();
             if (typeof renderDashboard === "function") renderDashboard();
             if (typeof renderShippers === "function") renderShippers();
          }

          plotLocationsOnMap(locations);
          showToast(`AI đã chia ${locations.length} đơn thành ${k} cụm và phân công cho Shipper!`, "success");

        } catch (error) {
          console.error("Analysis Error:", error);
          showToast("Lỗi phân tích dữ liệu mạng.", "error");
        } finally {
          btn.innerHTML = originalText;
          btn.disabled = false;
        }
      }

      function buildLeafletMap(mapDiv) {
        mapDiv.innerHTML = "";
        const kPos = typeof getKitchenPos === "function" ? getKitchenPos() : [10.7769, 106.7009];
        dashboardMapInst = L.map(mapDiv).setView(kPos, 13);

        L.tileLayer(
          "https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png",
          {
            attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
            subdomains: "abcd",
            maxZoom: 20,
          }
        ).addTo(dashboardMapInst);

        setTimeout(() => {
          dashboardMapInst.invalidateSize();
          filterShipperDensityMap();
        }, 200);
      }

      async function buildMap() {
        const mapDiv = document.getElementById("customer-density-map");
        if (!mapDiv) return;
        mapDiv.innerHTML = ""; // clear loading

        // For the map
        const { Map } = await google.maps.importLibrary("maps");
        const { AdvancedMarkerElement } =
          await google.maps.importLibrary("marker");

        dashboardMapInst = new Map(mapDiv, {
          center: { lat: 10.776, lng: 106.7 }, // TP.HCM
          zoom: 13,
          mapId: "95da68bb1d34cd45", // Custom style or fallback DEMO
          mapTypeControl: false,
          streetViewControl: false,
          internalUsageAttributionIds: ["gmp_mcp_codeassist_v1_aistudio"],
        });
      }

      // ==========================================
      // 6. MENU & DISH MANAGEMENT
      // ==========================================
      function renderCategories() {
        const container = document.getElementById("category-filters");
        container.innerHTML = categories
          .map(
            (cat) => `
                      <button onclick="setFilter('${cat.id}')"
                              class="whitespace-nowrap px-4 py-2 rounded-full text-sm font-medium transition-all ${
                                currentFilter === cat.id
                                  ? "bg-emerald-100 text-emerald-800 border border-emerald-200"
                                  : "bg-white text-slate-600 border border-slate-200 hover:bg-slate-50"
                              }">${cat.id === "complete" ? "Món theo công thức" : cat.name}</button>`,
          )
          .join("");

        // Sub-categories for 'complete'
        const subContainer = document.getElementById("sub-category-filters");
        if (subContainer) {
          if (currentFilter === "complete") {
            subContainer.classList.remove("hidden");
            const proteins = dishes.filter(
              (d) =>
                d.category === "protein" &&
                d.isActive !== false &&
                d.name !== "Tôm",
            );
            const subCats = [{ id: "all", name: "Tất cả" }].concat(
              proteins.map((p) => ({ id: p.id.toString(), name: p.name })),
            );

            subContainer.innerHTML = subCats
              .map(
                (cat) => `
                          <button onclick="setSubFilter('${cat.id}')"
                                  class="whitespace-nowrap px-3 py-1.5 rounded-full text-xs font-medium transition-all ${
                                    currentSubFilter === cat.id
                                      ? "bg-amber-100 text-amber-800 border border-amber-200"
                                      : "bg-white text-slate-600 border border-slate-200 hover:bg-slate-50"
                                  }">${cat.name}</button>`,
              )
              .join("");
          } else {
            subContainer.classList.add("hidden");
          }
        }
      }

      function setSubFilter(id) {
        currentSubFilter = id;
        renderCategories();
        renderDishes();
      }

      function setFilter(id) {
        currentFilter = id;
        currentSubFilter = "all";
        renderCategories();
        renderDishes();
      }

      function getDishStarsHtml(rating) {
        const value = parseFloat(rating) || 5;
        const fullStars = Math.floor(value);
        const hasHalfStar = value % 1 >= 0.5;
        const totalStars = 5;
        let html = "";

        for (let i = 0; i < fullStars; i++) {
          html += '<i class="fa-solid fa-star text-amber-400"></i>';
        }
        if (hasHalfStar) {
          html += '<i class="fa-solid fa-star-half-stroke text-amber-400"></i>';
        }
        const emptyStars = totalStars - fullStars - (hasHalfStar ? 1 : 0);
        for (let i = 0; i < emptyStars; i++) {
          html += '<i class="fa-regular fa-star text-amber-400"></i>';
        }
        return html;
      }

      function renderDishes() {
        const container = document.getElementById("dish-grid");

        if (!container) return;

        let filteredDishes = dishes.filter((d) => !d.isCustom);
        if (currentFilter !== "all") {
          filteredDishes = filteredDishes.filter(
            (d) => d.category === currentFilter,
          );
        }

        if (currentFilter === "complete" && currentSubFilter !== "all") {
          const protein = dishes.find(
            (d) =>
              d.id.toString() === currentSubFilter && d.category === "protein",
          );
          if (protein) {
            filteredDishes = filteredDishes.filter(
              (d) =>
                d.ingredients &&
                (d.ingredients.startsWith(protein.name) ||
                  d.name.includes(protein.name)),
            );
          }
        }

        window.weeklyFixedDishes = window.weeklyFixedDishes || JSON.parse(
          localStorage.getItem("nutriadmin_weekly_fixed_dishes") || '{"lunch":[],"dinner":[]}'
        );
        if (!window.weeklyFixedDishes.lunch) window.weeklyFixedDishes.lunch = [];
        if (!window.weeklyFixedDishes.dinner) window.weeklyFixedDishes.dinner = [];

        if (filteredDishes.length === 0) {
          if (currentFilter === "weekly_special") {
            container.innerHTML = renderWeeklyFixedDishesSection() + `<div class="col-span-full py-8 text-center text-slate-400"><i class="fa-solid fa-box-open text-4xl mb-2 opacity-40"></i><p class="text-sm font-medium">Chưa có món mới nào được tạo trong tuần này.</p></div>`;
          } else {
            container.innerHTML = `<div class="col-span-full py-12 text-center text-slate-500"><i class="fa-solid fa-box-open text-4xl mb-3 opacity-50"></i><p>Chưa có món ăn nào trong nhóm này.</p></div>`;
          }
          return;
        }

        const cardsHtml = filteredDishes
          .map(
            (dish) => `
                          <div ${currentFilter === "weekly_special" ? `draggable="true" ondragstart="handleDishDragStart(event, '${dish.id}')"` : ""} class="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden lg:hover:shadow-lg lg:hover:scale-105 active:scale-[0.98] transition-all duration-300 relative flex flex-col cursor-grab active:cursor-grabbing">
                              ${!dish.isActive ? '<div class="absolute top-2 left-2 bg-slate-800 text-white text-xs font-bold px-2 py-1 rounded z-10 opacity-80">Đã ẩn</div>' : ""}
                              <div class="h-48 overflow-hidden bg-slate-100 relative">
                                  <img src="${dish.image}" alt="${dish.name}" class="w-full h-full object-cover ${!dish.isActive ? "grayscale" : ""}">
                              </div>
                              <div class="p-5 flex-1 flex flex-col">
                                  <h3 class="font-bold text-lg text-slate-800 mb-1 leading-tight ${!dish.isActive ? "text-slate-400" : ""}">${dish.name}</h3>
                                  <div class="flex items-center gap-1 mb-2">
                                     <div class="flex text-[10px] gap-0.5">
                                         ${getDishStarsHtml(dish.rating || 5)}
                                     </div>
                                     <span class="text-xs font-bold text-slate-600 ml-1">${dish.rating || 5}</span>
                                  </div>
                                  <p class="text-sm text-slate-500 mb-4">${dish.ingredients}</p>
                                  <div class="mt-auto space-y-3">
                                      ${
                                        dish.category === "protein" &&
                                        dish.methods
                                          ? `
                                          <button onclick="openCookingMethodModal(${dish.id})" class="w-full py-2.5 bg-emerald-50 text-emerald-700 font-semibold rounded-lg hover:bg-emerald-100 transition-colors border border-emerald-200">
                                            <i class="fa-solid fa-fire-burner mr-1"></i> Chọn cách chế biến
                                          </button>
                                      `
                                          : `
                                      ${
                                        dish.sizes?.lean
                                          ? `
                                      <div class="bg-slate-50 rounded-lg p-2.5 border border-slate-100">
                                          <div class="flex justify-between items-center mb-1.5">
                                              <span class="text-xs font-bold text-slate-700">Lean (S) <span class="text-emerald-500 font-medium ml-1">${formatCurrency(dish.sizes?.lean?.price)}đ</span></span>
                                              <span class="text-xs font-bold text-primary">${dish.sizes?.lean?.kcal || 0} Kcal</span>
                                          </div>
                                          <div class="grid grid-cols-3 gap-1 text-center divide-x divide-slate-200">
                                              <div><p class="text-[10px] text-slate-400 uppercase">Đạm</p><p class="text-xs font-semibold">${dish.sizes?.lean?.protein || 0}g</p></div>
                                              <div><p class="text-[10px] text-slate-400 uppercase">Tinh bột</p><p class="text-xs font-semibold">${dish.sizes?.lean?.carbs || 0}g</p></div>
                                              <div><p class="text-[10px] text-slate-400 uppercase">Béo</p><p class="text-xs font-semibold">${dish.sizes?.lean?.fat || 0}g</p></div>
                                          </div>
                                      </div>
                                      `
                                          : ""
                                      }
                                      <div class="bg-slate-50 rounded-lg p-2.5 border border-slate-100">
                                          <div class="flex justify-between items-center mb-1.5">
                                              <span class="text-xs font-bold text-slate-700">Balance (M) <span class="text-emerald-600 font-medium ml-1">${formatCurrency(dish.sizes?.balance?.price)}đ</span></span>
                                              <span class="text-xs font-bold text-primary">${dish.sizes?.balance?.kcal || 0} Kcal</span>
                                          </div>
                                          <div class="grid grid-cols-3 gap-1 text-center divide-x divide-slate-200">
                                              <div><p class="text-[10px] text-slate-400 uppercase">Đạm</p><p class="text-xs font-semibold">${dish.sizes?.balance?.protein || 0}g</p></div>
                                              <div><p class="text-[10px] text-slate-400 uppercase">Tinh bột</p><p class="text-xs font-semibold">${dish.sizes?.balance?.carbs || 0}g</p></div>
                                              <div><p class="text-[10px] text-slate-400 uppercase">Béo</p><p class="text-xs font-semibold">${dish.sizes?.balance?.fat || 0}g</p></div>
                                          </div>
                                      </div>
                                      <div class="bg-slate-50 rounded-lg p-2.5 border border-slate-100">
                                          <div class="flex justify-between items-center mb-1.5">
                                              <span class="text-xs font-bold text-slate-700">Power (L) <span class="text-amber-600 font-medium ml-1">${formatCurrency(dish.sizes?.power?.price)}đ</span></span>
                                              <span class="text-xs font-bold text-amber-600">${dish.sizes?.power?.kcal || 0} Kcal</span>
                                          </div>
                                          <div class="grid grid-cols-3 gap-1 text-center divide-x divide-slate-200">
                                              <div><p class="text-[10px] text-slate-400 uppercase">Đạm</p><p class="text-xs font-semibold">${dish.sizes?.power?.protein || 0}g</p></div>
                                              <div><p class="text-[10px] text-slate-400 uppercase">Tinh bột</p><p class="text-xs font-semibold">${dish.sizes?.power?.carbs || 0}g</p></div>
                                              <div><p class="text-[10px] text-slate-400 uppercase">Béo</p><p class="text-xs font-semibold">${dish.sizes?.power?.fat || 0}g</p></div>
                                          </div>
                                      </div>
                                      `
                                      }
                                  </div>
                                  ${
                                    currentFilter === "weekly_special"
                                      ? `
                                  <div class="mt-3 pt-3 border-t border-slate-100 flex gap-2">
                                      <button onclick="addFixedDishQuick('${dish.id}', 'lunch')" class="flex-1 py-1.5 px-2 bg-amber-50 hover:bg-amber-100 text-amber-800 text-xs font-bold rounded-lg transition-colors border border-amber-200 text-center cursor-pointer">
                                          <i class="fa-solid fa-sun text-amber-500 mr-1"></i> + Bữa trưa
                                      </button>
                                      <button onclick="addFixedDishQuick('${dish.id}', 'dinner')" class="flex-1 py-1.5 px-2 bg-indigo-50 hover:bg-indigo-100 text-indigo-800 text-xs font-bold rounded-lg transition-colors border border-indigo-200 text-center cursor-pointer">
                                          <i class="fa-solid fa-moon text-indigo-500 mr-1"></i> + Bữa tối
                                      </button>
                                  </div>
                                      `
                                      : ""
                                  }
                                  ${
                                    typeof isAdminViewActive === "function" && isAdminViewActive() && typeof checkAdminSessionSilent === "function" && checkAdminSessionSilent()
                                      ? `
                                  <div class="mt-3 grid grid-cols-3 gap-1">
                                      <button onclick="toggleDishStatus('${dish.id}')" class="py-1.5 border border-slate-200 rounded-lg text-[13px] font-medium ${dish.isActive ? "text-amber-600 hover:bg-amber-50" : "text-primary hover:bg-emerald-50"} transition-colors"><i class="fa-solid ${dish.isActive ? "fa-eye-slash" : "fa-eye"} mr-1"></i> ${dish.isActive ? "Ẩn" : "Hiện"}</button>
                                      <button onclick="openModal('edit', '${dish.id}')" class="py-1.5 border border-slate-200 rounded-lg text-[13px] font-medium text-slate-600 hover:bg-slate-50 transition-colors"><i class="fa-solid fa-pen-to-square mr-1"></i> Sửa</button>
                                      <button onclick="deleteDish('${dish.id}')" class="py-1.5 border border-red-200 rounded-lg text-[13px] font-medium text-red-600 hover:bg-red-50 transition-colors"><i class="fa-solid fa-trash mr-1"></i> Xóa</button>
                                  </div>
                                      `
                                      : ""
                                  }
                              </div>
                          </div>`,
          )
          .join("");

        if (currentFilter === "weekly_special") {
          container.innerHTML = renderWeeklyFixedDishesSection() + cardsHtml;
        } else {
          container.innerHTML = cardsHtml;
        }
      }

      window.weeklyFixedDishes = JSON.parse(
        localStorage.getItem("nutriadmin_weekly_fixed_dishes") ||
        '{"enabled":true,"activeDays":["monday","tuesday","wednesday","thursday","friday"],"lunch":[],"dinner":[]}'
      );
      if (typeof window.weeklyFixedDishes.enabled === "undefined") window.weeklyFixedDishes.enabled = true;
      if (!Array.isArray(window.weeklyFixedDishes.activeDays)) {
        window.weeklyFixedDishes.activeDays = ["monday", "tuesday", "wednesday", "thursday", "friday"];
      }
      if (!Array.isArray(window.weeklyFixedDishes.lunch)) window.weeklyFixedDishes.lunch = [];
      if (!Array.isArray(window.weeklyFixedDishes.dinner)) window.weeklyFixedDishes.dinner = [];

      window.ensureCustomerWeeklyMenuDefaults = function (c) {
        if (!c) return;
        if (!c.weeklyMenu) c.weeklyMenu = {};

        const allWeekDays = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];
        const isEnabled = window.weeklyFixedDishes && window.weeklyFixedDishes.enabled !== false;
        const activeDays = (isEnabled && Array.isArray(window.weeklyFixedDishes.activeDays)) ? window.weeklyFixedDishes.activeDays : [];

        // Lọc các món cố định hợp lệ (tồn tại trong mảng dishes)
        const validLunchList = (window.weeklyFixedDishes.lunch || []).filter((id) =>
          dishes.some((d) => String(d.id) === String(id) && d.isActive !== false)
        );
        const validDinnerList = (window.weeklyFixedDishes.dinner || []).filter((id) =>
          dishes.some((d) => String(d.id) === String(id) && d.isActive !== false)
        );

        const fixedLunch = (isEnabled && validLunchList.length > 0) ? validLunchList[0] : null;
        const fixedDinner = (isEnabled && validDinnerList.length > 0) ? validDinnerList[0] : null;

        // Hàm kiểm tra ô món ăn đã được người dùng tự chọn món hợp lệ hay chưa
        const hasValidCustomDish = (mealObj) => {
          if (!mealObj || !mealObj.dishId || mealObj._isFixedDefault) return false;
          return dishes.some((d) => String(d.id) === String(mealObj.dishId) && d.isActive !== false);
        };

        allWeekDays.forEach((dKey) => {
          if (!c.weeklyMenu[dKey]) c.weeklyMenu[dKey] = {};

          const isDayActive = activeDays.includes(dKey);

          if (isDayActive) {
            // Gán fixedLunch cho Bữa 1 (Bữa Trưa) nếu chưa có món chọn tay hợp lệ
            if (fixedLunch) {
              if (!hasValidCustomDish(c.weeklyMenu[dKey].meal1)) {
                c.weeklyMenu[dKey].meal1 = {
                  dishId: String(fixedLunch),
                  size: c.size || "balance",
                  _isFixedDefault: true
                };
              }
            } else if (c.weeklyMenu[dKey].meal1 && c.weeklyMenu[dKey].meal1._isFixedDefault) {
              delete c.weeklyMenu[dKey].meal1;
            }

            // Gán fixedDinner cho Bữa 2 (Bữa Tối) nếu chưa có món chọn tay hợp lệ
            if (fixedDinner) {
              if (!hasValidCustomDish(c.weeklyMenu[dKey].meal2)) {
                c.weeklyMenu[dKey].meal2 = {
                  dishId: String(fixedDinner),
                  size: c.size || "balance",
                  _isFixedDefault: true
                };
              }
            } else if (c.weeklyMenu[dKey].meal2 && c.weeklyMenu[dKey].meal2._isFixedDefault) {
              delete c.weeklyMenu[dKey].meal2;
            }
          } else {
            // Ngày không được chọn: Gỡ bỏ món cố định tự động nếu có
            if (c.weeklyMenu[dKey].meal1 && (c.weeklyMenu[dKey].meal1._isFixedDefault || (fixedLunch && c.weeklyMenu[dKey].meal1.dishId === String(fixedLunch)) || (fixedDinner && c.weeklyMenu[dKey].meal1.dishId === String(fixedDinner)))) {
              delete c.weeklyMenu[dKey].meal1;
            }
            if (c.weeklyMenu[dKey].meal2 && (c.weeklyMenu[dKey].meal2._isFixedDefault || (fixedLunch && c.weeklyMenu[dKey].meal2.dishId === String(fixedLunch)) || (fixedDinner && c.weeklyMenu[dKey].meal2.dishId === String(fixedDinner)))) {
              delete c.weeklyMenu[dKey].meal2;
            }
          }
        });
      };

      function renderWeeklyFixedDishesSection() {
        const isEnabled = window.weeklyFixedDishes.enabled !== false;
        const activeDays = window.weeklyFixedDishes.activeDays || ["monday", "tuesday", "wednesday", "thursday", "friday"];

        const dayButtons = [
          { key: "monday", label: "Thứ 2" },
          { key: "tuesday", label: "Thứ 3" },
          { key: "wednesday", label: "Thứ 4" },
          { key: "thursday", label: "Thứ 5" },
          { key: "friday", label: "Thứ 6" },
        ];

        const dayButtonsHtml = dayButtons
          .map((d) => {
            const isSelected = activeDays.includes(d.key);
            return `<button type="button" onclick="toggleWeeklyFixedDay('${d.key}')" class="px-2.5 py-1 text-xs font-bold rounded-lg border transition-all cursor-pointer ${isSelected ? "bg-emerald-600 text-white border-emerald-600 shadow-2xs" : "bg-white text-slate-600 border-slate-200 hover:bg-slate-50"}">${d.label}</button>`;
          })
          .join("");

        const renderList = (slot) => {
          const list = window.weeklyFixedDishes[slot] || [];
          const validList = list.filter((id) => dishes.some((d) => String(d.id) === String(id)));
          if (validList.length === 0) {
            return `
              <div class="h-full min-h-[90px] flex flex-col items-center justify-center text-slate-400 text-xs py-4 border border-dashed border-slate-300/80 rounded-xl bg-white/60">
                <i class="fa-solid fa-cloud-arrow-down text-xl mb-1 opacity-40"></i>
                Kéo thả món mới mỗi tuần vào đây
              </div>`;
          }
          return validList
            .map((id) => {
              const dish = dishes.find((d) => String(d.id) === String(id));
              if (!dish) return "";
              return `
                <div class="flex items-center justify-between p-2.5 bg-white rounded-xl border border-slate-200 shadow-2xs">
                  <div class="flex items-center gap-2.5 overflow-hidden">
                    <img src="${dish.image}" alt="${dish.name}" class="w-10 h-10 rounded-lg object-cover flex-shrink-0" />
                    <div class="truncate">
                      <p class="text-xs font-bold text-slate-800 truncate">${dish.name}</p>
                      <p class="text-[11px] text-emerald-600 font-semibold">${formatCurrency(dish.sizes?.balance?.price || dish.price || 0)}đ</p>
                    </div>
                  </div>
                  <button onclick="removeFixedDish('${dish.id}', '${slot}')" title="Bỏ ghim món" class="text-slate-400 hover:text-red-500 p-1.5 rounded-lg hover:bg-red-50 transition-colors cursor-pointer">
                    <i class="fa-solid fa-xmark text-sm"></i>
                  </button>
                </div>`;
            })
            .join("");
        };

        const lunchCount = (window.weeklyFixedDishes.lunch || []).filter((id) => dishes.some((d) => String(d.id) === String(id))).length;
        const dinnerCount = (window.weeklyFixedDishes.dinner || []).filter((id) => dishes.some((d) => String(d.id) === String(id))).length;

        return `
          <div class="col-span-full mb-6">
            <div class="flex flex-col lg:flex-row lg:items-center justify-between gap-3 mb-4 bg-gradient-to-r from-emerald-50 to-teal-50 p-4 rounded-2xl border border-emerald-100/80 shadow-2xs">
              <div>
                <div class="flex items-center gap-3 mb-1 flex-wrap">
                  <h3 class="font-bold text-slate-800 text-base flex items-center gap-2">
                    <i class="fa-solid fa-thumbtack text-amber-500"></i> Món cố định tuần này
                  </h3>
                  <label class="relative inline-flex items-center cursor-pointer select-none">
                    <input type="checkbox" onchange="toggleWeeklyFixedEnabled(this.checked)" class="sr-only peer" ${isEnabled ? "checked" : ""}>
                    <div class="w-11 h-6 bg-slate-300 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-600"></div>
                    <span class="ml-2 text-xs font-bold ${isEnabled ? "text-emerald-700" : "text-slate-400"}">${isEnabled ? "Đang BẬT món mặc định" : "TẮT món mặc định"}</span>
                  </label>
                </div>
                <p class="text-xs text-slate-500">Khi bật, 2 món cố định (bữa trưa & bữa tối) sẽ trở thành món mặc định cho khách đăng ký gói vào các ngày được chọn.</p>
              </div>

              <div class="flex items-center gap-1.5 bg-white/90 p-1.5 rounded-xl border border-emerald-200/60 shadow-2xs flex-wrap">
                <span class="text-xs font-bold text-slate-600 mr-1 flex items-center gap-1"><i class="fa-solid fa-calendar-days text-emerald-600"></i> Chọn ngày áp dụng:</span>
                ${dayButtonsHtml}
              </div>
            </div>

            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
              <!-- Ô Bữa Trưa -->
              <div ondragover="handleDishDragOver(event)" ondrop="handleDishDrop(event, 'lunch')" class="bg-amber-50/60 border-2 border-dashed border-amber-300 hover:border-amber-400 rounded-2xl p-4 transition-all min-h-[170px] flex flex-col shadow-2xs">
                <div class="flex justify-between items-center mb-3 pb-2 border-b border-amber-200/60">
                  <span class="font-bold text-amber-900 flex items-center gap-2 text-sm">
                    <i class="fa-solid fa-sun text-amber-500 text-base"></i> Bữa Trưa (Lunch)
                  </span>
                  <span class="text-[11px] font-bold bg-amber-200/70 text-amber-800 px-2.5 py-0.5 rounded-full">
                    ${lunchCount} món
                  </span>
                </div>
                <div class="space-y-2 flex-1">
                  ${renderList('lunch')}
                </div>
              </div>

              <!-- Ô Bữa Tối -->
              <div ondragover="handleDishDragOver(event)" ondrop="handleDishDrop(event, 'dinner')" class="bg-indigo-50/60 border-2 border-dashed border-indigo-300 hover:border-indigo-400 rounded-2xl p-4 transition-all min-h-[170px] flex flex-col shadow-2xs">
                <div class="flex justify-between items-center mb-3 pb-2 border-b border-indigo-200/60">
                  <span class="font-bold text-indigo-900 flex items-center gap-2 text-sm">
                    <i class="fa-solid fa-moon text-indigo-500 text-base"></i> Bữa Tối (Dinner)
                  </span>
                  <span class="text-[11px] font-bold bg-indigo-200/70 text-indigo-800 px-2.5 py-0.5 rounded-full">
                    ${dinnerCount} món
                  </span>
                </div>
                <div class="space-y-2 flex-1">
                  ${renderList('dinner')}
                </div>
              </div>
            </div>
          </div>`;
      }

      window.toggleWeeklyFixedEnabled = function (val) {
        window.weeklyFixedDishes.enabled = !!val;
        saveWeeklyFixedDishesState();
        showToast(
          val ? "Đã BẬT món cố định làm món mặc định!" : "Đã TẮT món cố định mặc định!",
          val ? "success" : "info"
        );
      };

      window.toggleWeeklyFixedDay = function (dayKey) {
        if (!Array.isArray(window.weeklyFixedDishes.activeDays)) {
          window.weeklyFixedDishes.activeDays = ["monday", "tuesday", "wednesday", "thursday", "friday"];
        }
        const idx = window.weeklyFixedDishes.activeDays.indexOf(dayKey);
        if (idx > -1) {
          window.weeklyFixedDishes.activeDays.splice(idx, 1);
        } else {
          window.weeklyFixedDishes.activeDays.push(dayKey);
        }
        saveWeeklyFixedDishesState();
      };

      window.handleDishDragStart = function (e, dishId) {
        e.dataTransfer.setData("text/plain", String(dishId));
      };

      window.handleDishDragOver = function (e) {
        e.preventDefault();
      };

      window.handleDishDrop = function (e, slot) {
        e.preventDefault();
        const dishId = e.dataTransfer.getData("text/plain");
        if (dishId) {
          addFixedDishQuick(dishId, slot);
        }
      };

      window.addFixedDishQuick = function (dishId, slot) {
        if (!window.weeklyFixedDishes[slot]) window.weeklyFixedDishes[slot] = [];
        const idStr = String(dishId);
        if (!window.weeklyFixedDishes[slot].includes(idStr)) {
          window.weeklyFixedDishes[slot].push(idStr);
          saveWeeklyFixedDishesState();
          showToast(`Đã ghim món vào ${slot === "lunch" ? "Bữa trưa" : "Bữa tối"} cố định!`, "success");
        } else {
          showToast("Món này đã có trong danh sách cố định!", "info");
        }
      };

      window.removeFixedDish = function (dishId, slot) {
        if (!window.weeklyFixedDishes[slot]) return;
        const idStr = String(dishId);
        window.weeklyFixedDishes[slot] = window.weeklyFixedDishes[slot].filter(
          (id) => String(id) !== idStr,
        );
        saveWeeklyFixedDishesState();
        showToast("Đã bỏ ghim món cố định!", "info");
      };

      function saveWeeklyFixedDishesState() {
        localStorage.setItem(
          "nutriadmin_weekly_fixed_dishes",
          JSON.stringify(window.weeklyFixedDishes),
        );

        if (typeof purchasedCustomers !== "undefined" && Array.isArray(purchasedCustomers)) {
          purchasedCustomers.forEach((c) => {
            if (typeof ensureCustomerWeeklyMenuDefaults === "function") ensureCustomerWeeklyMenuDefaults(c);
          });
          localStorage.setItem("nutriadmin_purchased_customers", JSON.stringify(purchasedCustomers));
        }
        if (typeof potentialCustomers !== "undefined" && Array.isArray(potentialCustomers)) {
          potentialCustomers.forEach((c) => {
            if (typeof ensureCustomerWeeklyMenuDefaults === "function") ensureCustomerWeeklyMenuDefaults(c);
          });
          localStorage.setItem("nutriadmin_potential_customers", JSON.stringify(potentialCustomers));
        }
        if (typeof currentUser !== "undefined" && currentUser) {
          if (typeof ensureCustomerWeeklyMenuDefaults === "function") ensureCustomerWeeklyMenuDefaults(currentUser);
          localStorage.setItem("nutriadmin_current_user", JSON.stringify(currentUser));
        }

        if (typeof lastSyncedStateStr !== "undefined") lastSyncedStateStr = "";
        if (typeof syncStateToServer === "function") syncStateToServer();
        renderDishes();
      }
      function handleCategoryChange() {
        const category = document.getElementById("dish-category").value;
        const ingredientsSection = document.getElementById(
          "dish-ingredients-wrapper",
        );
        const nutritionSection = document.getElementById(
          "dish-nutrition-wrapper",
        );
        const ratingSection = document.getElementById("dish-rating-wrapper");

        const inputs = document.querySelectorAll(
          "#dish-nutrition-wrapper input[required]",
        );

        if (category === "protein") {
          if (ingredientsSection) ingredientsSection.classList.add("hidden");
          if (nutritionSection) nutritionSection.classList.remove("hidden"); // SHOW nutrition for protein
          if (ratingSection) ratingSection.classList.add("hidden");
          const applyToAllWrapper = document.getElementById(
            "apply-to-all-methods-wrapper",
          );
          if (applyToAllWrapper) applyToAllWrapper.classList.remove("hidden");

          inputs.forEach((input) => {
            input.removeAttribute("required");
            input.setAttribute("data-was-required", "true");
          });
        } else {
          const applyToAllWrapper = document.getElementById(
            "apply-to-all-methods-wrapper",
          );
          if (applyToAllWrapper) applyToAllWrapper.classList.add("hidden");
          if (ingredientsSection) ingredientsSection.classList.remove("hidden");
          if (nutritionSection) nutritionSection.classList.remove("hidden");
          if (ratingSection) ratingSection.classList.remove("hidden");

          const wasRequiredInputs = document.querySelectorAll(
            "#dish-nutrition-wrapper input[data-was-required='true']",
          );
          wasRequiredInputs.forEach((input) => {
            input.setAttribute("required", "required");
            input.removeAttribute("data-was-required");
          });
        }
      }

      function calculateDishYield(size, sourceField) {
        const rawInput = document.getElementById(`${size}-raw-ingQty`);
        const yieldInput = document.getElementById(`${size}-yield`);
        const cookedInput = document.getElementById(`${size}-main-ingQty`);

        if (!rawInput || !yieldInput || !cookedInput) return;

        const yieldVal = parseFloat(yieldInput.value) || 100;

        if (sourceField === "yield" || sourceField === "raw") {
          const rawVal = parseFloat(rawInput.value);
          if (!isNaN(rawVal)) {
            cookedInput.value = (rawVal * (yieldVal / 100)).toFixed(3);
          }
        } else if (sourceField === "cooked") {
          const cookedVal = parseFloat(cookedInput.value);
          if (!isNaN(cookedVal) && yieldVal > 0) {
            rawInput.value = (cookedVal / (yieldVal / 100)).toFixed(3);
          }
        }
      }

      function calculateMethodYield(size, sourceField) {
        const rawInput = document.getElementById(`me-${size}-raw-qty`);
        const yieldInput = document.getElementById(`me-${size}-yield`);
        const cookedInput = document.getElementById(`me-${size}-main-qty`);

        if (!rawInput || !yieldInput || !cookedInput) return;

        const yieldVal = parseFloat(yieldInput.value) || 100;

        if (sourceField === "yield" || sourceField === "raw") {
          const rawVal = parseFloat(rawInput.value);
          if (!isNaN(rawVal)) {
            cookedInput.value = (rawVal * (yieldVal / 100)).toFixed(3);
          }
        } else if (sourceField === "cooked") {
          const cookedVal = parseFloat(cookedInput.value);
          if (!isNaN(cookedVal) && yieldVal > 0) {
            rawInput.value = (cookedVal / (yieldVal / 100)).toFixed(3);
          }
        }
      }

      function closeModal() {
        document.getElementById("dish-modal").classList.add("hidden");
      }
      window.closeModal = closeModal;

      function openModal(mode, idOrCategory = null) {
        const modal = document.getElementById("dish-modal");
        const form = document.getElementById("dish-form");
        form.reset();

        if (mode === "edit" && idOrCategory) {
          document.getElementById("modal-title").innerText = "Chỉnh sửa món ăn";
          const applyToAll = document.getElementById("apply-to-all-methods");
          if (applyToAll) applyToAll.checked = false;
          let dish = dishes.find((d) => String(d.id) === String(idOrCategory));
          if (!dish) {
            try {
              const local = JSON.parse(localStorage.getItem("nutriadmin_dishes") || "[]");
              dish = local.find((d) => String(d.id) === String(idOrCategory));
              if (dish && !dishes.some((d) => String(d.id) === String(idOrCategory))) {
                dishes.unshift(dish);
              }
            } catch (e) {}
          }
          if (dish) {
            document.getElementById("dish-id").value = dish.id;
            document.getElementById("dish-name").value = dish.name;
            document.getElementById("dish-category").value = dish.category;
            document.getElementById("dish-rating").value = dish.rating || 5;
            document.getElementById("dish-image-data").value = dish.image;

            const preview = document.getElementById("dish-image-preview");
            const placeholder = document.getElementById(
              "dish-image-placeholder",
            );

            if (dish.image) {
              preview.src = dish.image;
              preview.classList.remove("hidden");
              placeholder.classList.add("hidden");
            }

            document.getElementById("dish-ingredients").value =
              dish.ingredients || "";
            document.getElementById("dish-active").checked = dish.isActive;

            if (dish.sizes) {
              document.getElementById("s-price").value =
                dish.sizes?.lean?.price || "";
              document.getElementById("s-kcal").value =
                dish.sizes?.lean?.kcal || "";
              document.getElementById("s-protein").value =
                dish.sizes?.lean?.protein || "";
              document.getElementById("s-carbs").value =
                dish.sizes?.lean?.carbs || "";
              document.getElementById("s-fat").value =
                dish.sizes?.lean?.fat || "";
              document.getElementById("s-main-ingQty").value =
                dish.sizes?.lean?.mainIngredientQty || "";
              document.getElementById("s-raw-ingQty").value =
                dish.sizes?.lean?.rawIngredientQty || "";
              document.getElementById("s-yield").value =
                dish.sizes?.lean?.yield || 100;
              document.getElementById("m-price").value =
                dish.sizes?.balance?.price || "";
              document.getElementById("m-kcal").value =
                dish.sizes?.balance?.kcal || "";
              document.getElementById("m-protein").value =
                dish.sizes?.balance?.protein || "";
              document.getElementById("m-carbs").value =
                dish.sizes?.balance?.carbs || "";
              document.getElementById("m-fat").value =
                dish.sizes?.balance?.fat || "";
              document.getElementById("m-main-ingQty").value =
                dish.sizes?.balance?.mainIngredientQty || "";
              document.getElementById("m-raw-ingQty").value =
                dish.sizes?.balance?.rawIngredientQty || "";
              document.getElementById("m-yield").value =
                dish.sizes?.balance?.yield || 100;
              document.getElementById("l-price").value =
                dish.sizes?.power?.price || "";
              document.getElementById("l-kcal").value =
                dish.sizes?.power?.kcal || "";
              document.getElementById("l-protein").value =
                dish.sizes?.power?.protein || "";
              document.getElementById("l-carbs").value =
                dish.sizes?.power?.carbs || "";
              document.getElementById("l-fat").value =
                dish.sizes?.power?.fat || "";
              document.getElementById("l-main-ingQty").value =
                dish.sizes?.power?.mainIngredientQty || "";
              document.getElementById("l-raw-ingQty").value =
                dish.sizes?.power?.rawIngredientQty || "";
              document.getElementById("l-yield").value =
                dish.sizes?.power?.yield || 100;
            } else {
              [
                "m-price",
                "m-kcal",
                "m-protein",
                "m-carbs",
                "m-fat",
                "m-main-ingQty",
                "m-raw-ingQty",
                "s-price",
                "s-kcal",
                "s-protein",
                "s-carbs",
                "s-fat",
                "s-main-ingQty",
                "s-raw-ingQty",
                "l-price",
                "l-kcal",
                "l-protein",
                "l-carbs",
                "l-fat",
                "l-main-ingQty",
                "l-raw-ingQty",
              ].forEach((id) => {
                document.getElementById(id).value = "";
              });
              ["s-yield", "m-yield", "l-yield"].forEach((id) => {
                document.getElementById(id).value = 100;
              });
            }
          }
        } else {
          document.getElementById("modal-title").innerText =
            "Thêm món ăn/Nguyên liệu mới";
          const applyToAll = document.getElementById("apply-to-all-methods");
          if (applyToAll) applyToAll.checked = false;
          document.getElementById("dish-id").value = "";
          document.getElementById("dish-active").checked = true;
          document.getElementById("dish-image-data").value = "";
          document.getElementById("dish-image-preview").classList.add("hidden");
          document
            .getElementById("dish-image-placeholder")
            .classList.remove("hidden");
          if (mode === "add" && typeof idOrCategory === "string") {
            document.getElementById("dish-category").value = idOrCategory;
          } else {
            document.getElementById("dish-category").value = "complete";
          }
        }

        handleCategoryChange();
        modal.classList.remove("hidden");
      }
      window.openModal = openModal;

      function closeMethodEditModal() {
        document.getElementById("method-edit-modal").classList.add("hidden");
      }

      function saveMethodEdit(e) {
        e.preventDefault();
        const dishId = parseInt(
          document.getElementById("method-edit-dish-id").value,
        );
        const methodIndex = parseInt(
          document.getElementById("method-edit-index").value,
        );

        const dish = dishes.find((d) => d.id === dishId);
        if (dish && dish.methods && dish.methods[methodIndex]) {
          const method = dish.methods[methodIndex];

          method.name = document.getElementById("me-name").value.trim();
          method.image = document.getElementById("me-image").value.trim();
          method.ingredients = document
            .getElementById("me-ingredients")
            .value.trim();

          if (!method.sizes) method.sizes = {};

          if (!method.sizes.lean) method.sizes.lean = {};

          method.sizes.lean.price =
            parseInt(document.getElementById("me-s-price").value) || 0;
          method.sizes.lean.kcal =
            parseInt(document.getElementById("me-s-kcal").value) || 0;
          method.sizes.lean.protein =
            parseFloat(document.getElementById("me-s-protein").value) || 0;
          method.sizes.lean.carbs =
            parseFloat(document.getElementById("me-s-carbs").value) || 0;
          method.sizes.lean.fat =
            parseFloat(document.getElementById("me-s-fat").value) || 0;
          const meSQty = document.getElementById("me-s-main-qty").value;
          method.sizes.lean.mainIngredientQty = meSQty
            ? parseFloat(meSQty)
            : null;
          method.sizes.lean.yield =
            parseFloat(document.getElementById("me-s-yield").value) || 100;
          const meSRawQty = document.getElementById("me-s-raw-qty").value;
          method.sizes.lean.rawIngredientQty = meSRawQty
            ? parseFloat(meSRawQty)
            : null;

          if (!method.sizes.balance) method.sizes.balance = {};
          if (!method.sizes.power) method.sizes.power = {};

          method.sizes.balance.price =
            parseInt(document.getElementById("me-m-price").value) || 0;
          method.sizes.balance.kcal =
            parseInt(document.getElementById("me-m-kcal").value) || 0;
          method.sizes.balance.protein =
            parseFloat(document.getElementById("me-m-protein").value) || 0;
          method.sizes.balance.carbs =
            parseFloat(document.getElementById("me-m-carbs").value) || 0;
          method.sizes.balance.fat =
            parseFloat(document.getElementById("me-m-fat").value) || 0;
          const sQty = document.getElementById("me-m-main-qty").value;
          method.sizes.balance.mainIngredientQty = sQty
            ? parseFloat(sQty)
            : null;
          method.sizes.balance.yield =
            parseFloat(document.getElementById("me-m-yield").value) || 100;
          const meMRawQty = document.getElementById("me-m-raw-qty").value;
          method.sizes.balance.rawIngredientQty = meMRawQty
            ? parseFloat(meMRawQty)
            : null;

          method.sizes.power.price =
            parseInt(document.getElementById("me-l-price").value) || 0;
          method.sizes.power.kcal =
            parseInt(document.getElementById("me-l-kcal").value) || 0;
          method.sizes.power.protein =
            parseFloat(document.getElementById("me-l-protein").value) || 0;
          method.sizes.power.carbs =
            parseFloat(document.getElementById("me-l-carbs").value) || 0;
          method.sizes.power.fat =
            parseFloat(document.getElementById("me-l-fat").value) || 0;
          const lQty = document.getElementById("me-l-main-qty").value;
          method.sizes.power.mainIngredientQty = lQty ? parseFloat(lQty) : null;
          method.sizes.power.yield =
            parseFloat(document.getElementById("me-l-yield").value) || 100;
          const meLRawQty = document.getElementById("me-l-raw-qty").value;
          method.sizes.power.rawIngredientQty = meLRawQty
            ? parseFloat(meLRawQty)
            : null;

          if (typeof syncStateToServer === "function") {
            lastStateStr = "";
            syncStateToServer();
          }
          window.recalculateCompleteDishes();
          closeMethodEditModal();
          openCookingMethodModal(dishId);
        }
      }

      function closeCookingMethodModal() {
        document.getElementById("cooking-method-modal").classList.add("hidden");
      }

