      let leafletMap = null;
      let leafletMarker = null;

      function openMapModal() {
        document.getElementById("map-modal").classList.remove("hidden");
        document.getElementById("map-modal").classList.add("flex");
        if (!leafletMap) {
          setTimeout(() => {
            const kPos =
              typeof getKitchenPos === "function"
                ? getKitchenPos()
                : [10.7769, 106.7009];
            leafletMap = L.map("leaflet-map").setView(kPos, 13);
            L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
              attribution: "&copy; OpenStreetMap contributors",
            }).addTo(leafletMap);

            leafletMarker = L.marker(kPos, { draggable: true }).addTo(
              leafletMap,
            );

            leafletMap.on("click", function (e) {
              leafletMarker.setLatLng(e.latlng);
            });
          }, 100);
        } else {
          setTimeout(() => {
            leafletMap.invalidateSize();
          }, 100);
        }
      }

      function closeMapModal() {
        document.getElementById("map-modal").classList.add("hidden");
        document.getElementById("map-modal").classList.remove("flex");
      }

      async function confirmMapLocation() {
        if (leafletMarker) {
          const pos = leafletMarker.getLatLng();
          document.getElementById("cust-lat").value = pos.lat;
          document.getElementById("cust-lng").value = pos.lng;
          const statusText = document.getElementById("selected-location-text");
          statusText.classList.remove("hidden");
          statusText.innerHTML =
            '<i class="fa-solid fa-spinner fa-spin mr-1"></i> Đang phân tích vị trí...';

          try {
            const res = await fetch(
              `https://nominatim.openstreetmap.org/reverse?format=json&lat=${pos.lat}&lon=${pos.lng}&addressdetails=1&accept-language=vi`,
            );
            const data = await res.json();

            if (data && data.address) {
              const addr = data.address;

              let fullString = (
                addr.city +
                " " +
                addr.state +
                " " +
                (addr["ISO3166-2-lvl4"] || "") +
                " " +
                data.display_name
              ).toLowerCase();
              let isHcm =
                fullString.includes("hồ chí minh") ||
                fullString.includes("ho chi minh") ||
                fullString.includes("vn-sg");
              if (isHcm) {
                document.getElementById("cust-city").value = "TP. Hồ Chí Minh";
                updateDistricts();
              }

              let districtFields = [
                addr.city_district,
                addr.county,
                addr.district,
                addr.suburb,
                addr.town,
                addr.city,
              ].filter(Boolean);
              let foundDistrict = false;
              for (let val of districtFields) {
                let v = String(val)
                  .toLowerCase()
                  .replace("district", "")
                  .replace("quận", "")
                  .replace("huyện", "")
                  .replace("thành phố", "")
                  .replace("thị xã", "")
                  .replace("tp.", "")
                  .trim();
                const dOpts = document.getElementById("cust-district").options;
                for (let i = 1; i < dOpts.length; i++) {
                  let oVal = dOpts[i].value.toLowerCase();
                  let baseName = oVal
                    .replace("quận", "")
                    .replace("huyện", "")
                    .replace("tp.", "")
                    .replace("thành phố", "")
                    .replace("thị xã", "")
                    .trim();
                  if (baseName.includes("thủ đức")) baseName = "thủ đức";

                  if (
                    v === oVal ||
                    v === baseName ||
                    v === "quận " + baseName ||
                    v === "huyện " + baseName ||
                    (v.includes("thủ đức") && baseName === "thủ đức") ||
                    v === "phường " + baseName
                  ) {
                    document.getElementById("cust-district").value =
                      dOpts[i].value;
                    updateWards();
                    foundDistrict = true;
                    break;
                  }
                }
                if (foundDistrict) break;
              }

              let wardFields = [
                addr.quarter,
                addr.neighbourhood,
                addr.suburb,
                addr.village,
                addr.hamlet,
                addr.residential,
              ].filter(Boolean);
              let foundWard = false;
              for (let val of wardFields) {
                let v = String(val)
                  .toLowerCase()
                  .replace("ward", "")
                  .replace("phường", "")
                  .replace("xã", "")
                  .replace("thị trấn", "")
                  .trim();
                // Prevent district matching as ward incorrectly if they share same name
                if (
                  foundDistrict &&
                  v ===
                    document
                      .getElementById("cust-district")
                      .value.toLowerCase()
                      .replace("quận", "")
                      .replace("huyện", "")
                      .trim()
                ) {
                  continue;
                }

                const wOpts = document.getElementById("cust-ward").options;
                for (let i = 1; i < wOpts.length; i++) {
                  let oVal = wOpts[i].value.toLowerCase();
                  let baseName = oVal
                    .replace("phường", "")
                    .replace("xã", "")
                    .replace("thị trấn", "")
                    .trim();

                  if (
                    v === oVal ||
                    v === baseName ||
                    v === "phường " + baseName ||
                    v === "xã " + baseName
                  ) {
                    document.getElementById("cust-ward").value = wOpts[i].value;
                    foundWard = true;
                    break;
                  }
                }
                if (foundWard) break;
              }

              let streetInfoArr = [];
              if (addr.house_number) {
                streetInfoArr.push(addr.house_number);
              } else if (
                data.name &&
                !data.name.toLowerCase().includes("phường") &&
                !data.name.toLowerCase().includes("quận") &&
                !data.name.toLowerCase().includes("city")
              ) {
                streetInfoArr.push(data.name);
              }

              if (addr.road && !streetInfoArr.includes(addr.road)) {
                streetInfoArr.push(addr.road);
              }

              if (streetInfoArr.length === 0) {
                streetInfoArr.push(data.display_name.split(",")[0]);
              }
              document.getElementById("cust-street").value =
                streetInfoArr.join(", ");

              statusText.innerHTML =
                '<i class="fa-solid fa-check mr-1"></i> Đã điền địa chỉ tự động từ bản đồ';
              showToast("Đã điền địa chỉ tự động!");
            } else {
              statusText.innerHTML =
                '<i class="fa-solid fa-check mr-1"></i> Đã chọn vị trí thủ công';
            }
          } catch (e) {
            console.error("Geocoding error:", e);
            statusText.innerHTML =
              '<i class="fa-solid fa-check mr-1"></i> Đã chọn vị trí thủ công';
          }
        }
        closeMapModal();
      }

      function updateDistricts() {
        const d = document.getElementById("cust-district"),
          w = document.getElementById("cust-ward");
        if (!d || !w) return;
        d.innerHTML = '<option value="">Quận/Huyện *</option>';
        w.innerHTML = '<option value="">Phường/Xã *</option>';
        w.disabled = true;
        for (let k in locationData["TP. Hồ Chí Minh"]) {
          d.innerHTML += `<option value="${k}">${k}</option>`;
        }
      }

      function updateWards() {
        const d = document.getElementById("cust-district").value;
        const w = document.getElementById("cust-ward");
        w.innerHTML = '<option value="">Phường/Xã *</option>';
        if (d) {
          w.disabled = false;
          locationData["TP. Hồ Chí Minh"][d].forEach(
            (x) => (w.innerHTML += `<option value="${x}">${x}</option>`),
          );
        } else {
          w.disabled = true;
        }
      }

