            eyeRight = `<path d="M82 52 L72 56 L82 60" stroke="#2DD4BF" stroke-width="4.5" fill="none" stroke-linejoin="round" stroke-linecap="round" />`;
            mouth = `<path d="M53 66 Q60 76 67 66" stroke="#2DD4BF" stroke-width="3.5" fill="none" stroke-linecap="round" />`;
